INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u3-C1','kor',1,1,'u3',1,'받침이 있어야 뜻이 살아요 — 받침을 빠뜨리면(수박 → 수바) 낱말의 뜻이 사라지거나 다른 낱말이 됨을 알고, 받침이 있는 글자를 가려 읽기',ARRAY['2국03-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u3-C2','kor',1,1,'u3',2,'짜임을 생각하며 받침 글자 만들기 — 첫 자음자 + 모음자 + 받침 세 조각을 모아 쓰고, 모음자가 옆에 있든 아래에 있든 받침은 글자 맨 아래에 쓰기',ARRAY['2국03-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u3-C3','kor',1,1,'u3',2,'받침을 넣어 낱말 완성하기 — 그림이 뜻하는 낱말을 떠올려 받침이 들어갈 글자를 찾고(바라 → 바람) 알맞은 받침을 넣어 낱말을 완성하기, 받침이 여러 글자에 올 수 있음을 알기',ARRAY['2국03-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u3-C4','kor',1,1,'u3',4,'틀린 받침을 바르게 고쳐 쓰기 — 틀린 곳을 찾고(잠화) → 바른 받침으로 고치고(장화) → 소리 내어 읽어 확인하기, 소리에 끌려 받침을 빼고 쓰지 않기(무통 → 물통)',ARRAY['2국03-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u3-C5','kor',1,1,'u3',4,'바른 자세로 또박또박 쓰기 — 허리를 펴고 앉아, 연필을 바르게 잡고, 공책을 살짝 기울여 한 글자씩 짜임을 생각하며 받침까지 또박또박 쓰기',ARRAY['2국03-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u3-C6','kor',1,1,'u3',6,'된소리 자음자의 모양 — 같은 자음자를 두 번 나란히 쓰면 된소리 자음자 ㄲ·ㄸ·ㅃ·ㅆ·ㅉ이 됨을 알고, 획을 더한 ㅋ·ㅌ·ㅍ·ㅊ과 가르기',ARRAY['2국04-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u3-C7','kor',1,1,'u3',6,'예사소리와 된소리 견주어 읽기 — 굴/꿀·방/빵·살/쌀처럼 자음자가 된소리로 바뀌면 소리가 세지고 뜻도 달라짐을 알고, 된소리가 없는 낱말은 세게 읽지 않기(가시 ≠ 까시)',ARRAY['2국04-01']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u3-C8','kor',1,1,'u3',8,'낱말을 자신 있게 읽기 — 받침과 된소리가 든 낱말, 움직임·소리를 흉내 내는 말(깡충깡충·뒤뚱뒤뚱·쨍쨍)을 모양·소리·뜻을 함께 떠올리며 또박또박 소리 내어 읽기',ARRAY['2국02-01']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u3-C9','kor',1,1,'u3',10,'주변 낱말 찾기와 낱자 바꾸기 — 교실·가족·집 같은 주제에서 받침이나 된소리가 든 낱말을 찾아 읽고 쓰며, 낱자 하나(첫 자음자·모음자·받침)만 바뀌어도 다른 낱말이 됨을 알기(곰 → 봄 · 말 → 물)',ARRAY['2국04-01']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X01','kor',1,'u3',ARRAY['K1-1-u3-C1','K1-1-u3-C3','K1-1-u3-C4']::text[],'받침을 빠뜨리고 쓰거나 읽고, 소리 나는 대로 받침을 뺀다(수박 → 수바, 물통 → 무통)','낱말의 뜻(그림)을 먼저 떠올리고, 글자마다 아래쪽에 받침이 있는지 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X02','kor',1,'u3',ARRAY['K1-1-u3-C2']::text[],'받침을 글자 옆(오른쪽)에 따로 쓴다(부ㄱ)','받침은 늘 글자 맨 아래 — 모음자가 옆에 있든(달) 아래에 있든(북) 아래 칸에 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X03','kor',1,'u3',ARRAY['K1-1-u3-C3','K1-1-u3-C4']::text[],'소리가 비슷한 받침을 헷갈려 쓴다(우산 → 우상, 장화 → 잠화)','고친 낱말을 소리 내어 읽고 끝소리의 입 모양을 견주기 — ㄴ은 혀, ㅇ은 코, ㅁ은 입술') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X04','kor',1,'u3',ARRAY['K1-1-u3-C3','K1-1-u3-C4']::text[],'받침을 넣을 글자(자리)를 잘못 고른다(바라 + ㅁ → 밤라)','낱말을 천천히 읽으며 「어느 글자에서 소리가 닫히지?」를 찾고 그 글자 아래에만 받침 넣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X05','kor',1,'u3',ARRAY['K1-1-u3-C3','K1-1-u3-C9']::text[],'받침은 한 낱말에 하나뿐이라 여기거나 두 번째 받침을 빠뜨린다(축구공 → 추구공)','글자 하나하나 아래쪽을 따로 살피기 — 「돌다리」의 돌, 「공책」의 공·책처럼 여러 글자에 올 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X06','kor',1,'u3',ARRAY['K1-1-u3-C2','K1-1-u3-C9']::text[],'첫 자음자·모음자·받침 자리를 헷갈린다(받침을 고치며 첫 자음자까지 바꿈, 첫 자음자 ㄲ을 받침으로 여김)','글자를 세 조각 카드로 나누어 놓고 「위 왼쪽 = 첫 자음자, 옆이나 아래 = 모음자, 맨 아래 = 받침」 자리 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X07','kor',1,'u3',ARRAY['K1-1-u3-C3']::text[],'뜻을 생각하지 않고 아무 받침이나 넣는다','받침을 넣은 뒤 「이 말이 그림과 같은가?」 소리 내어 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X08','kor',1,'u3',ARRAY['K1-1-u3-C5']::text[],'쓰기 자세·연필 잡기를 지키지 않고 빨리 쓰면 된다고 여긴다','쓰기 전 세 가지 — 허리 펴기, 연필 바르게 잡기, 공책 살짝 기울이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X09','kor',1,'u3',ARRAY['K1-1-u3-C6','K1-1-u3-C7']::text[],'된소리 자음자 모양을 헷갈린다(ㅃ을 ㅂ 하나로 씀, 다른 된소리 자음자를 겹쳐 씀)','「같은 자음자를 두 번」 — ㄱ ㄱ → ㄲ처럼 손가락으로 두 번 써 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X10','kor',1,'u3',ARRAY['K1-1-u3-C6','K1-1-u3-C7']::text[],'된소리 자음자를 거센소리 자음자와 헷갈린다(ㄲ ↔ ㅋ, ㄸ ↔ ㅌ, ㅃ ↔ ㅍ, ㅉ ↔ ㅊ)','ㅋ은 ㄱ에 획을 하나 더한 것, ㄲ은 ㄱ을 두 번 쓴 것 — 두 자음자를 나란히 놓고 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X11','kor',1,'u3',ARRAY['K1-1-u3-C7']::text[],'예사소리 낱말과 된소리 낱말이 같은 말이라고 여긴다(방 = 빵)','방·빵을 번갈아 소리 내어 읽고 그림을 이어 보기 — 소리가 다르면 뜻도 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X12','kor',1,'u3',ARRAY['K1-1-u3-C7']::text[],'된소리가 없는 낱말까지 세게 읽는다(가시 → 까시)','글자에 같은 자음자를 두 번 쓴 곳이 있을 때만 세게 — 없으면 여린 소리로 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X13','kor',1,'u3',ARRAY['K1-1-u3-C7','K1-1-u3-C8']::text[],'된소리 낱말을 여린 소리로 읽거나 쓴다(코뿔소 → 코불소, 쌀 → 살)','그림을 보며 낱말을 세게 한 번, 여리게 한 번 읽어 보고 맞는 소리를 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X14','kor',1,'u3',ARRAY['K1-1-u3-C8']::text[],'흉내 내는 말을 모습·소리에 어울리지 않게 고른다(해가 주룩주룩)','흉내 내는 말을 몸으로 따라 하며 읽고 그 모습이 그림과 맞는지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X15','kor',1,'u3',ARRAY['K1-1-u3-C8','K1-1-u3-C9']::text[],'글자를 하나하나 보지 않고 짐작하거나 빨리·작게 뭉개 읽는다','손가락으로 글자 하나하나를 짚으며 받침과 센 소리까지 또박또박 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u3-X16','kor',1,'u3',ARRAY['K1-1-u3-C1','K1-1-u3-C7','K1-1-u3-C9']::text[],'낱자 하나가 바뀌어도 같은 낱말이라 여기거나 무엇이 바뀌었는지 가르지 못한다(곰 = 봄)','두 낱말을 위아래로 놓고 첫 자음자·모음자·받침을 하나씩 견주어 다른 곳에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_basic#1','kor',1,1,'u3','L01','g1_1_kor_u3_L01_basic','lesson_basic','K1-1-u3-C1',1,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X06']::text[],true,'{"seq":1,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"수박","at":1,"pic":"🍉"},"options":[{"t":"ㄱ","correct":true},{"t":"ㅇ","mis":"K1-1-u3-X03"},{"t":"ㅂ","mis":"K1-1-u3-X06"}],"explanation":["그림은 「수박」이에요.","「바」에 받침 ㄱ을 넣어야 「박」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u3-C1","difficulty":1,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X03","role":"X06"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_basic#2','kor',1,1,'u3','L01','g1_1_kor_u3_L01_basic','lesson_basic','K1-1-u3-C1',1,'mc','auto','쪽지에 수박을 「수바」라고 썼어요. 무엇이 빠졌나요?',ARRAY['K1-1-u3-X04','K1-1-u3-X06']::text[],true,'{"seq":2,"concept":"K1-1-u3-C1","difficulty":1,"kind":"mc","stem":"쪽지에 수박을 「수바」라고 썼어요. 무엇이 빠졌나요?","options":[{"t":"「바」 아래의 받침 ㄱ","correct":true},{"t":"「수」 아래의 받침 ㄱ","mis":"K1-1-u3-X04"},{"t":"모음자 ㅏ","mis":"K1-1-u3-X06"}],"explanation":["「수박」은 「바」 아래에 받침 ㄱ이 있어야 해요.","「수」에는 받침이 없고, 모음자 ㅏ는 이미 있어요.","받침이 빠지면 무슨 말인지 알기 어려워요."],"asset":{"type":"scene","icon":"🍉","text":"수바"},"variant_rule":{"alt":[{"stem":"쪽지에 곰을 「고」라고 썼어요. 무엇이 빠졌나요?","options":[{"t":"「고」 아래의 받침 ㅁ","correct":true},{"t":"「고」 옆의 자음자 ㅁ","mis":"K1-1-u3-X02"},{"t":"모음자 ㅗ","mis":"K1-1-u3-X06"}],"explanation":["「곰」은 「고」 아래에 받침 ㅁ이 있어야 해요.","받침은 옆이 아니라 아래에 들어가요.","받침이 빠지면 뜻이 사라져요."],"asset":{"type":"scene","icon":"🐻","text":"고"}},{"stem":"쪽지에 가방을 「가바」라고 썼어요. 무엇이 빠졌나요?","options":[{"t":"「바」 아래의 받침 ㅇ","correct":true},{"t":"「가」 아래의 받침 ㅇ","mis":"K1-1-u3-X04"},{"t":"모음자 ㅏ","mis":"K1-1-u3-X06"}],"explanation":["「가방」은 「바」 아래에 받침 ㅇ이 있어야 해요.","「가」에는 받침이 없어요.","글자마다 아래쪽을 살펴요."],"asset":{"type":"scene","icon":"🎒","text":"가바"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_basic#3','kor',1,1,'u3','L01','g1_1_kor_u3_L01_basic','lesson_basic','K1-1-u3-C2',1,'mc','auto','「고」에 받침 ㅁ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X01','K1-1-u3-X03']::text[],true,'{"seq":3,"kind":"mc","stem":"「고」에 받침 ㅁ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"고","b":"ㅁ","s":null,"lay":true},"options":[{"t":"곰","correct":true},{"t":"고","mis":"K1-1-u3-X01"},{"t":"곱","mis":"K1-1-u3-X03"}],"explanation":["「고」 아래쪽에 받침 ㅁ을 더하면 「곰」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「곰」은 받침 ㅁ 소리까지 끝까지 읽어요."],"concept":"K1-1-u3-C2","difficulty":1,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X01","near":"X03"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_basic#4','kor',1,1,'u3','L01','g1_1_kor_u3_L01_basic','lesson_basic','K1-1-u3-C1',1,'ox','auto','받침을 빠뜨리고 쓰면 무슨 말인지 알기 어려워요.',ARRAY['K1-1-u3-X01']::text[],true,'{"seq":4,"concept":"K1-1-u3-C1","difficulty":1,"kind":"ox","stem":"받침을 빠뜨리고 쓰면 무슨 말인지 알기 어려워요.","answer":"O","reason_options":[{"t":"「수박」이 「수바」가 되면 뜻이 사라지니까","correct":true},{"t":"받침은 있어도 없어도 뜻이 같으니까","mis":"K1-1-u3-X01"}],"mis":"K1-1-u3-X01","explanation":["「수바」는 무슨 말인지 알 수 없어요.","받침 ㄱ을 넣어야 「수박」이 돼요.","받침을 정확히 써야 내 마음이 바르게 전해져요."],"variant_rule":{"alt":[{"stem":"「기린」을 「기리」라고 써도 뜻이 잘 전해져요.","answer":"X","reason_options":[{"t":"받침 ㄴ이 빠지면 「기린」의 뜻이 사라지니까","correct":true},{"t":"받침은 빠져도 읽는 사람이 알아서 읽으니까","mis":"K1-1-u3-X01"}],"explanation":["「기리」는 기린이 아니에요.","「리」 아래에 받침 ㄴ을 넣어야 해요.","받침까지 빠뜨리지 않고 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_basic#5','kor',1,1,'u3','L01','g1_1_kor_u3_L01_basic','lesson_basic','K1-1-u3-C1',2,'mc','auto','받침이 있는 글자만 모은 것은 어느 것인가요?',ARRAY['K1-1-u3-X01']::text[],true,'{"seq":5,"concept":"K1-1-u3-C1","difficulty":2,"kind":"mc","stem":"받침이 있는 글자만 모은 것은 어느 것인가요?","options":[{"t":"별 · 문 · 발","correct":true},{"t":"별 · 나 · 발","mis":"K1-1-u3-X01"},{"t":"코 · 문 · 소","mis":"K1-1-u3-X01"}],"explanation":["별·문·발은 모두 아래쪽에 받침이 있어요.","「나」·「코」·「소」는 아래쪽이 비어 있어요.","글자마다 아래쪽에 자음자가 있는지 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받침이 있는 글자만 모은 것은 어느 것인가요?","options":[{"t":"숲 · 문 · 별","correct":true},{"t":"숲 · 배 · 별","mis":"K1-1-u3-X01"},{"t":"나 · 문 · 소","mis":"K1-1-u3-X01"}],"explanation":["숲(ㅍ)·문(ㄴ)·별(ㄹ)은 모두 받침이 있어요.","「배」·「나」·「소」는 아래쪽이 비어 있어요.","아래쪽을 하나씩 살펴요."]},{"stem":"받침이 없는 글자만 모은 것은 어느 것인가요?","options":[{"t":"나 · 코 · 배","correct":true},{"t":"나 · 발 · 배","mis":"K1-1-u3-X01"},{"t":"코 · 소 · 숲","mis":"K1-1-u3-X01"}],"explanation":["나·코·배는 아래쪽이 비어 있어요.","「발」·「숲」에는 받침이 있어요.","아래쪽을 하나씩 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_basic#6','kor',1,1,'u3','L01','g1_1_kor_u3_L01_basic','lesson_basic','K1-1-u3-C2',2,'mc','auto','「별」의 받침은 어느 것인가요?',ARRAY['K1-1-u3-X06','K1-1-u3-X03']::text[],true,'{"seq":6,"kind":"mc","stem":"「별」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"별","eq":false},"options":[{"t":"ㄹ","correct":true},{"t":"ㅂ","mis":"K1-1-u3-X06"},{"t":"ㄴ","mis":"K1-1-u3-X03"}],"explanation":["「별」은 ㅂ + ㅕ + 받침 ㄹ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㅂ은 첫소리, 받침 ㄹ은 끝소리예요."],"concept":"K1-1-u3-C2","difficulty":2,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X06","near":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_basic#7','kor',1,1,'u3','L01','g1_1_kor_u3_L01_basic','lesson_basic','K1-1-u3-C3',2,'mc','auto','그림에 맞게 「사」 아래에 받침을 넣으면 어떤 낱말이 되나요?',ARRAY['K1-1-u3-X07']::text[],true,'{"seq":7,"concept":"K1-1-u3-C3","difficulty":2,"kind":"mc","stem":"그림에 맞게 「사」 아래에 받침을 넣으면 어떤 낱말이 되나요?","options":[{"t":"산","correct":true},{"t":"삼","mis":"K1-1-u3-X07"},{"t":"살","mis":"K1-1-u3-X07"}],"explanation":["우뚝 솟은 산 — 「사」 + 받침 ㄴ = 「산」.","「삼」·「살」은 그림과 다른 말이에요.","그림의 뜻을 먼저 떠올려요."],"asset":{"type":"scene","icon":"⛰️","text":"사□"},"variant_rule":{"alt":[{"stem":"그림에 맞게 「채」 아래에 받침을 넣으면 어떤 낱말이 되나요?","options":[{"t":"책","correct":true},{"t":"챈","mis":"K1-1-u3-X07"},{"t":"챕","mis":"K1-1-u3-X07"}],"explanation":["읽는 책 — 「채」 + 받침 ㄱ = 「책」.","「챈」·「챕」은 그림과 다른 글자예요.","그림의 뜻을 먼저 떠올려요."],"asset":{"type":"scene","icon":"📕","text":"채□"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_basic#8','kor',1,1,'u3','L01','g1_1_kor_u3_L01_basic','lesson_basic','K1-1-u3-C1',2,'match','auto','받침이 빠진 쪽지와 바르게 고친 낱말을 이으세요.','{}'::text[],true,'{"seq":8,"concept":"K1-1-u3-C1","difficulty":2,"kind":"match","stem":"받침이 빠진 쪽지와 바르게 고친 낱말을 이으세요.","pairs":[{"l":"수바","r":"수박"},{"l":"기리","r":"기린"},{"l":"가바","r":"가방"}],"mis":"K1-1-u3-X01","explanation":["수바 → 수박, 기리 → 기린, 가바 → 가방.","모두 둘째 글자 아래 받침이 빠졌어요.","받침을 넣으면 뜻이 살아나요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받침이 빠진 쪽지와 바르게 고친 낱말을 이으세요.","pairs":[{"l":"고","r":"곰"},{"l":"거부","r":"거북"},{"l":"사타","r":"사탕"}],"explanation":["고 → 곰, 거부 → 거북, 사타 → 사탕.","빠진 받침을 넣었어요.","받침이 있어야 뜻이 살아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_basic#9','kor',1,1,'u3','L01','g1_1_kor_u3_L01_basic','lesson_basic','K1-1-u3-C1',2,'mc','auto','받침을 빠뜨리지 않고 바르게 쓴 쪽지는 어느 것인가요?',ARRAY['K1-1-u3-X01']::text[],true,'{"seq":9,"concept":"K1-1-u3-C1","difficulty":2,"kind":"mc","stem":"받침을 빠뜨리지 않고 바르게 쓴 쪽지는 어느 것인가요?","options":[{"t":"기린을 보았어요","correct":true},{"t":"기리을 보았어요","mis":"K1-1-u3-X01"},{"t":"기린을 보아어요","mis":"K1-1-u3-X01"}],"explanation":["「기린」의 ㄴ, 「았」의 ㅆ까지 다 썼어요.","「기리」, 「보아어요」는 받침이 빠졌어요.","글자마다 받침을 챙겨요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받침을 빠뜨리지 않고 바르게 쓴 쪽지는 어느 것인가요?","options":[{"t":"곰을 만났어요","correct":true},{"t":"고을 만났어요","mis":"K1-1-u3-X01"},{"t":"곰을 마나어요","mis":"K1-1-u3-X01"}],"explanation":["「곰」의 ㅁ, 「만났」의 ㄴ·ㅆ까지 다 썼어요.","「고」, 「마나어요」는 받침이 빠졌어요.","글자마다 받침을 챙겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_basic#10','kor',1,1,'u3','L01','g1_1_kor_u3_L01_basic','lesson_basic','K1-1-u3-C1',3,'mc','auto','받침이 있는 글자가 두 개인 낱말은 어느 것인가요?',ARRAY['K1-1-u3-X05','K1-1-u3-X01']::text[],true,'{"seq":10,"concept":"K1-1-u3-C1","difficulty":3,"kind":"mc","stem":"받침이 있는 글자가 두 개인 낱말은 어느 것인가요?","options":[{"t":"연필","correct":true},{"t":"수박","mis":"K1-1-u3-X05"},{"t":"사과","mis":"K1-1-u3-X01"}],"explanation":["「연필」은 연(ㄴ)·필(ㄹ) 두 글자에 받침이 있어요.","「수박」은 박 하나, 「사과」는 하나도 없어요.","받침은 한 낱말에 여러 개 있을 수 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받침이 있는 글자가 두 개인 낱말은 어느 것인가요?","options":[{"t":"공책","correct":true},{"t":"가방","mis":"K1-1-u3-X05"},{"t":"나비","mis":"K1-1-u3-X01"}],"explanation":["「공책」은 공(ㅇ)·책(ㄱ) 두 글자에 받침이 있어요.","「가방」은 방 하나, 「나비」는 하나도 없어요.","글자마다 따로 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_challenge#1','kor',1,1,'u3','L01','g1_1_kor_u3_L01_challenge','lesson_challenge','K1-1-u3-C2',2,'mc','auto','채 + 받침 ㄱ 는 어떤 글자가 되나요?',ARRAY['K1-1-u3-X02','K1-1-u3-X06']::text[],true,'{"seq":1,"kind":"mc","stem":"채 + 받침 ㄱ 는 어떤 글자가 되나요?","asset":{"type":"bat","base":"채","b":"ㄱ","s":null},"options":[{"t":"책","correct":true},{"t":"채ㄱ","mis":"K1-1-u3-X02"},{"t":"잭","mis":"K1-1-u3-X06"}],"explanation":["「채」 아래쪽에 받침 ㄱ을 더하면 「책」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「책」은 받침 ㄱ 소리까지 끝까지 읽어요."],"concept":"K1-1-u3-C2","difficulty":2,"variant_rule":{"bat":{"ask":"add","mis":{"side":"X02","cons":"X06"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_challenge#2','kor',1,1,'u3','L01','g1_1_kor_u3_L01_challenge','lesson_challenge','K1-1-u3-C1',2,'ox','auto','「곰」과 「고」는 받침 하나만 다르니 같은 뜻이에요.',ARRAY['K1-1-u3-X16']::text[],false,'{"seq":2,"concept":"K1-1-u3-C1","difficulty":2,"kind":"ox","stem":"「곰」과 「고」는 받침 하나만 다르니 같은 뜻이에요.","answer":"X","reason_options":[{"t":"받침 ㅁ이 빠지면 「곰」의 뜻이 사라지니까","correct":true},{"t":"첫 자음자와 모음자가 같으면 같은 낱말이니까","mis":"K1-1-u3-X16"}],"mis":"K1-1-u3-X16","explanation":["「고」는 곰이 아니에요.","받침 하나로 낱말이 달라져요.","받침까지 보고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_challenge#3','kor',1,1,'u3','L01','g1_1_kor_u3_L01_challenge','lesson_challenge','K1-1-u3-C1',3,'error','auto','은솔이가 쓴 쪽지예요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_challenge#4','kor',1,1,'u3','L01','g1_1_kor_u3_L01_challenge','lesson_challenge','K1-1-u3-C1',3,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X06']::text[],true,'{"seq":4,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"호랑이","at":1,"pic":"🐯"},"options":[{"t":"ㅇ","correct":true},{"t":"ㄴ","mis":"K1-1-u3-X03"},{"t":"ㄹ","mis":"K1-1-u3-X06"}],"explanation":["그림은 「호랑이」예요.","「라」에 받침 ㅇ을 넣어야 「랑」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u3-C1","difficulty":3,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X03","role":"X06"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_challenge#5','kor',1,1,'u3','L01','g1_1_kor_u3_L01_challenge','lesson_challenge','K1-1-u3-C1',3,'mc','auto','다음 글자 가운데 받침이 있는 글자는 모두 몇 개인가요?',ARRAY['K1-1-u3-X15']::text[],true,'{"seq":5,"concept":"K1-1-u3-C1","difficulty":3,"kind":"mc","stem":"다음 글자 가운데 받침이 있는 글자는 모두 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"3개","mis":"K1-1-u3-X15"},{"t":"5개","mis":"K1-1-u3-X15"}],"explanation":["받침이 있는 글자는 별·문·발·숲이에요.","나·코·소·배는 아래쪽이 비어 있어요.","글자 하나하나 아래쪽을 짚으며 세어요."],"asset":{"type":"passage","lines":["별 · 나 · 문 · 코 · 발 · 소 · 숲 · 배"]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 글자 가운데 받침이 있는 글자는 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"K1-1-u3-X15"},{"t":"5개","mis":"K1-1-u3-X15"}],"explanation":["받침이 있는 글자는 강·집·물이에요.","오·이·머·리는 아래쪽이 비어 있어요.","「오」·「이」의 ㅇ은 위쪽 첫 자음자예요."],"asset":{"type":"passage","lines":["강 · 오 · 집 · 이 · 물 · 머 · 리"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_challenge#6','kor',1,1,'u3','L01','g1_1_kor_u3_L01_challenge','lesson_challenge','K1-1-u3-C3',3,'mc','auto','다람쥐를 쓰려다 받침 하나를 빠뜨렸어요. 빠뜨린 것은 어느 글자 아래의 받침인가요?',ARRAY['K1-1-u3-X04']::text[],true,'{"seq":6,"concept":"K1-1-u3-C3","difficulty":3,"kind":"mc","stem":"다람쥐를 쓰려다 받침 하나를 빠뜨렸어요. 빠뜨린 것은 어느 글자 아래의 받침인가요?","options":[{"t":"「라」 아래의 받침 ㅁ","correct":true},{"t":"「다」 아래의 받침 ㅁ","mis":"K1-1-u3-X04"},{"t":"「쥐」 아래의 받침 ㅁ","mis":"K1-1-u3-X04"}],"explanation":["「다람쥐」의 받침은 「람」에 있어요.","「다」·「쥐」에는 받침이 없어요.","천천히 읽으며 소리가 닫히는 글자를 찾아요."],"asset":{"type":"scene","icon":"🐿️","text":"다라쥐"},"variant_rule":{"alt":[{"stem":"돌다리를 쓰려다 받침 하나를 빠뜨렸어요. 빠뜨린 것은 어느 글자 아래의 받침인가요?","options":[{"t":"「도」 아래의 받침 ㄹ","correct":true},{"t":"「다」 아래의 받침 ㄹ","mis":"K1-1-u3-X04"},{"t":"「리」 아래의 받침 ㄹ","mis":"K1-1-u3-X04"}],"explanation":["「돌다리」의 받침은 「돌」에 있어요.","「다」·「리」에는 받침이 없어요.","소리가 닫히는 글자를 찾아요."],"asset":{"type":"scene","icon":"🌉","text":"도다리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_challenge#7','kor',1,1,'u3','L01','g1_1_kor_u3_L01_challenge','lesson_challenge','K1-1-u3-C1',3,'mc','auto','받침을 정확히 써야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u3-X08','K1-1-u3-X01']::text[],false,'{"seq":7,"concept":"K1-1-u3-C1","difficulty":3,"kind":"mc","stem":"받침을 정확히 써야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"받침이 빠지거나 틀리면 낱말의 뜻이 달라지거나 사라져서","correct":true},{"t":"받침이 있어야 글씨가 예뻐 보여서","mis":"K1-1-u3-X08"},{"t":"받침을 많이 쓸수록 칭찬을 받아서","mis":"K1-1-u3-X01"}],"explanation":["받침은 낱말의 뜻을 지켜 줘요.","글씨 모양이나 칭찬 때문이 아니에요.","받침을 바르게 써야 내 마음이 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_challenge#8','kor',1,1,'u3','L01','g1_1_kor_u3_L01_challenge','lesson_challenge','K1-1-u3-C1',4,'mc','auto','다음 문장에서 받침이 빠진 글자는 모두 몇 개인가요?',ARRAY['K1-1-u3-X15']::text[],true,'{"seq":8,"concept":"K1-1-u3-C1","difficulty":4,"kind":"mc","stem":"다음 문장에서 받침이 빠진 글자는 모두 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"K1-1-u3-X15"},{"t":"3개","mis":"K1-1-u3-X15"}],"explanation":["「수바」의 바(박), 「사타」의 타(탕) — 두 글자예요.","다른 글자는 바르게 썼어요.","낱말마다 뜻을 떠올리며 글자를 하나하나 살펴요."],"asset":{"type":"passage","lines":["어제 수바과 사타을 먹었어요."]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 문장에서 받침이 빠진 글자는 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"K1-1-u3-X15"},{"t":"1개","mis":"K1-1-u3-X15"}],"explanation":["「고」(곰)·「기리」의 리(린)·「거부」의 부(북) — 세 글자예요.","다른 글자는 바르게 썼어요.","글자를 하나하나 짚어요."],"asset":{"type":"passage","lines":["동물원에서 고과 기리과 거부을 보았어요."]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_challenge#9','kor',1,1,'u3','L01','g1_1_kor_u3_L01_challenge','lesson_challenge','K1-1-u3-C1',4,'mc','auto','받침을 빠뜨렸더니 아예 다른 뜻의 낱말이 되어 버린 것은 어느 것인가요?',ARRAY['K1-1-u3-X16']::text[],false,'{"seq":9,"concept":"K1-1-u3-C1","difficulty":4,"kind":"mc","stem":"받침을 빠뜨렸더니 아예 다른 뜻의 낱말이 되어 버린 것은 어느 것인가요?","options":[{"t":"문 → 무(먹는 채소)","correct":true},{"t":"곰 → 고","mis":"K1-1-u3-X16"},{"t":"수박 → 수바","mis":"K1-1-u3-X16"}],"explanation":["「문」에서 받침을 빼면 먹는 「무」가 돼요.","「고」·「수바」는 뜻이 사라진 말이에요.","받침 하나로 뜻이 사라지기도, 다른 말이 되기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L01_challenge#10','kor',1,1,'u3','L01','g1_1_kor_u3_L01_challenge','lesson_challenge','K1-1-u3-C1',4,'essay','teacher','「고」와 「곰」을 견주어, 받침을 빠뜨리면 왜 안 되는지 까닭을 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u3-C1","difficulty":4,"kind":"essay","stem":"「고」와 「곰」을 견주어, 받침을 빠뜨리면 왜 안 되는지 까닭을 말해 보세요.","answer_guide":{"answer":"예: 「곰」에서 받침 ㅁ을 빠뜨리면 「고」가 되어 곰이라는 뜻이 사라져요. 그래서 받침을 꼭 써야 해요.","scoring_points":["두 글자에서 달라진 곳(받침 ㅁ)을 찾았는가","받침이 빠지면 뜻이 사라지거나 달라진다고 말했는가","받침을 바르게 써야 한다고 말했는가"]},"explanation":["달라진 곳은 받침 ㅁ.","받침이 빠지면 뜻이 사라져요.","받침까지 바르게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_basic#1','kor',1,1,'u3','L02','g1_1_kor_u3_L02_basic','lesson_basic','K1-1-u3-C2',1,'mc','auto','「다」에 받침 ㄹ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X01','K1-1-u3-X03']::text[],true,'{"seq":1,"kind":"mc","stem":"「다」에 받침 ㄹ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"다","b":"ㄹ","s":null,"lay":true},"options":[{"t":"달","correct":true},{"t":"다","mis":"K1-1-u3-X01"},{"t":"단","mis":"K1-1-u3-X03"}],"explanation":["「다」 아래쪽에 받침 ㄹ을 더하면 「달」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「달」은 받침 ㄹ 소리까지 끝까지 읽어요."],"concept":"K1-1-u3-C2","difficulty":1,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X01","near":"X03"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_basic#2','kor',1,1,'u3','L02','g1_1_kor_u3_L02_basic','lesson_basic','K1-1-u3-C2',1,'mc','auto','받침이 있는 글자는 몇 조각으로 이루어져 있나요?',ARRAY['K1-1-u3-X01','K1-1-u3-X06']::text[],true,'{"seq":2,"concept":"K1-1-u3-C2","difficulty":1,"kind":"mc","stem":"받침이 있는 글자는 몇 조각으로 이루어져 있나요?","options":[{"t":"첫 자음자 · 모음자 · 받침, 세 조각","correct":true},{"t":"자음자 · 모음자, 두 조각","mis":"K1-1-u3-X01"},{"t":"자음자만 세 조각","mis":"K1-1-u3-X06"}],"explanation":["「달」 = 첫 자음자 ㄷ + 모음자 ㅏ + 받침 ㄹ.","받침 글자는 세 조각이에요.","받침도 자음자예요."],"variant_rule":{"alt":[{"stem":"「북」을 이루는 조각을 모두 모은 것은 어느 것인가요?","options":[{"t":"ㅂ · ㅜ · ㄱ","correct":true},{"t":"ㅂ · ㅜ","mis":"K1-1-u3-X01"},{"t":"ㅂ · ㄱ","mis":"K1-1-u3-X06"}],"explanation":["「북」 = ㅂ + ㅜ + 받침 ㄱ.","모음자나 받침 하나만 빠져도 다른 글자예요.","세 조각을 다 챙겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_basic#3','kor',1,1,'u3','L02','g1_1_kor_u3_L02_basic','lesson_basic','K1-1-u3-C3',1,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X07']::text[],true,'{"seq":3,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"양","at":0,"pic":"🐑"},"options":[{"t":"ㅇ","correct":true},{"t":"ㄴ","mis":"K1-1-u3-X03"},{"t":"ㄱ","mis":"K1-1-u3-X07"}],"explanation":["그림은 「양」이에요.","「야」에 받침 ㅇ을 넣어야 「양」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u3-C3","difficulty":1,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X03","any":"X07"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_basic#4','kor',1,1,'u3','L02','g1_1_kor_u3_L02_basic','lesson_basic','K1-1-u3-C2',1,'mc','auto','「북」의 받침은 어느 것인가요?',ARRAY['K1-1-u3-X06','K1-1-u3-X03']::text[],true,'{"seq":4,"kind":"mc","stem":"「북」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"북","eq":false,"lay":"blank"},"options":[{"t":"ㄱ","correct":true},{"t":"ㅂ","mis":"K1-1-u3-X06"},{"t":"ㅇ","mis":"K1-1-u3-X03"}],"explanation":["「북」은 ㅂ + ㅜ + 받침 ㄱ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㅂ은 첫소리, 받침 ㄱ은 끝소리예요."],"concept":"K1-1-u3-C2","difficulty":1,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X06","near":"X03"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_basic#5','kor',1,1,'u3','L02','g1_1_kor_u3_L02_basic','lesson_basic','K1-1-u3-C2',2,'mc','auto','「부」에 받침 ㄱ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X02','K1-1-u3-X06']::text[],true,'{"seq":5,"kind":"mc","stem":"「부」에 받침 ㄱ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"부","b":"ㄱ","s":null},"options":[{"t":"북","correct":true},{"t":"부ㄱ","mis":"K1-1-u3-X02"},{"t":"복","mis":"K1-1-u3-X06"}],"explanation":["「부」 아래쪽에 받침 ㄱ을 더하면 「북」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「북」은 받침 ㄱ 소리까지 끝까지 읽어요."],"concept":"K1-1-u3-C2","difficulty":2,"variant_rule":{"bat":{"ask":"add","mis":{"side":"X02","flip":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_basic#6','kor',1,1,'u3','L02','g1_1_kor_u3_L02_basic','lesson_basic','K1-1-u3-C3',2,'mc','auto','「축구고」에 받침을 넣어 「축구공」을 완성하려고 해요. 어느 글자에 어떤 받침을 넣나요?',ARRAY['K1-1-u3-X04','K1-1-u3-X03']::text[],true,'{"seq":6,"concept":"K1-1-u3-C3","difficulty":2,"kind":"mc","stem":"「축구고」에 받침을 넣어 「축구공」을 완성하려고 해요. 어느 글자에 어떤 받침을 넣나요?","options":[{"t":"「고」에 받침 ㅇ","correct":true},{"t":"「구」에 받침 ㅇ","mis":"K1-1-u3-X04"},{"t":"「고」에 받침 ㄴ","mis":"K1-1-u3-X03"}],"explanation":["「공」 = 「고」 + 받침 ㅇ.","「구」에 넣으면 「궁」이 되고, ㄴ을 넣으면 「곤」이 돼요.","받침이 들어갈 글자와 받침을 함께 생각해요."],"asset":{"type":"scene","icon":"⚽","text":"축구고"},"variant_rule":{"alt":[{"stem":"「고무주」에 받침을 넣어 「고무줄」을 완성하려고 해요. 어느 글자에 어떤 받침을 넣나요?","options":[{"t":"「주」에 받침 ㄹ","correct":true},{"t":"「무」에 받침 ㄹ","mis":"K1-1-u3-X04"},{"t":"「주」에 받침 ㅁ","mis":"K1-1-u3-X03"}],"explanation":["「줄」 = 「주」 + 받침 ㄹ.","「무」에 넣으면 「물」이 되고, ㅁ을 넣으면 「줌」이 돼요.","받침 자리와 받침을 함께 생각해요."],"asset":{"type":"scene","icon":"🪢","text":"고무주"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_basic#7','kor',1,1,'u3','L02','g1_1_kor_u3_L02_basic','lesson_basic','K1-1-u3-C3',2,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X06']::text[],true,'{"seq":7,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"고무줄","at":2,"pic":"🪢"},"options":[{"t":"ㄹ","correct":true},{"t":"ㄴ","mis":"K1-1-u3-X03"},{"t":"ㅈ","mis":"K1-1-u3-X06"}],"explanation":["그림은 「고무줄」이에요.","「주」에 받침 ㄹ을 넣어야 「줄」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u3-C3","difficulty":2,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X03","role":"X06"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_basic#8','kor',1,1,'u3','L02','g1_1_kor_u3_L02_basic','lesson_basic','K1-1-u3-C2',2,'mc','auto','「눈」처럼 모음자가 자음자 아래에 있는 글자에서 받침은 어디에 쓰나요?',ARRAY['K1-1-u3-X02','K1-1-u3-X06']::text[],true,'{"seq":8,"concept":"K1-1-u3-C2","difficulty":2,"kind":"mc","stem":"「눈」처럼 모음자가 자음자 아래에 있는 글자에서 받침은 어디에 쓰나요?","options":[{"t":"모음자 ㅜ 아래, 글자 맨 아래","correct":true},{"t":"모음자 ㅜ 오른쪽","mis":"K1-1-u3-X02"},{"t":"첫 자음자 ㄴ 왼쪽","mis":"K1-1-u3-X06"}],"explanation":["받침은 언제나 글자 맨 아래에 써요.","모음자가 아래에 있으면 받침은 그 아래로 가요.","「감」·「눈」·「북」 모두 받침이 맨 아래예요."],"variant_rule":{"alt":[{"stem":"「감」처럼 모음자가 자음자 옆에 있는 글자에서 받침은 어디에 쓰나요?","options":[{"t":"자음자와 모음자 아래, 글자 맨 아래","correct":true},{"t":"모음자 ㅏ 오른쪽","mis":"K1-1-u3-X02"},{"t":"첫 자음자 ㄱ 위","mis":"K1-1-u3-X06"}],"explanation":["모음자가 옆에 있어도 받침은 맨 아래예요.","오른쪽에 쓰면 한 글자가 되지 않아요.","받침 자리는 하나 — 맨 아래."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_basic#9','kor',1,1,'u3','L02','g1_1_kor_u3_L02_basic','lesson_basic','K1-1-u3-C2',2,'mc','auto','「곰」의 받침 ㅁ을 ㅇ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X06','K1-1-u3-X16']::text[],true,'{"seq":9,"kind":"mc","stem":"「곰」의 받침 ㅁ을 ㅇ으로 바꾸면 어떤 글자가 되나요?","asset":{"type":"bat","s":"곰","eq":false},"options":[{"t":"공","correct":true},{"t":"옴","mis":"K1-1-u3-X06"},{"t":"곰","mis":"K1-1-u3-X16"}],"explanation":["「곰」에서 받침 ㅁ 자리에 ㅇ을 넣으면 「공」이에요.","맨 앞 자음자 ㄱ과 모음자 ㅗ는 그대로예요.","받침이 바뀌면 글자도 소리도 뜻도 달라져요."],"concept":"K1-1-u3-C2","difficulty":2,"variant_rule":{"bat":{"ask":"swap","mis":{"role":"X06","keep":"X16"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_basic#10','kor',1,1,'u3','L02','g1_1_kor_u3_L02_basic','lesson_basic','K1-1-u3-C3',3,'sa','auto','그림을 보고 받침이 빠진 글자를 고쳐 낱말을 바르게 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"K1-1-u3-C3","difficulty":3,"kind":"sa","stem":"그림을 보고 받침이 빠진 글자를 고쳐 낱말을 바르게 쓰세요.","answer":["다람쥐"],"explanation":["「라」에 받침 ㅁ을 넣으면 「다람쥐」.","다른 글자에는 받침이 없어요.","고친 뒤 소리 내어 읽어 확인해요."],"asset":{"type":"scene","icon":"🐿️","text":"다라쥐"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림을 보고 받침이 빠진 글자를 고쳐 낱말을 바르게 쓰세요.","answer":["돌다리"],"explanation":["「도」에 받침 ㄹ을 넣으면 「돌다리」.","다른 글자에는 받침이 없어요.","고친 뒤 소리 내어 읽어 확인해요."],"asset":{"type":"scene","icon":"🌉","text":"도다리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_challenge#1','kor',1,1,'u3','L02','g1_1_kor_u3_L02_challenge','lesson_challenge','K1-1-u3-C2',2,'mc','auto','야 + 받침 ㅇ 는 어떤 글자가 되나요?',ARRAY['K1-1-u3-X02','K1-1-u3-X06']::text[],true,'{"seq":1,"kind":"mc","stem":"야 + 받침 ㅇ 는 어떤 글자가 되나요?","asset":{"type":"bat","base":"야","b":"ㅇ","s":null},"options":[{"t":"양","correct":true},{"t":"야ㅇ","mis":"K1-1-u3-X02"},{"t":"영","mis":"K1-1-u3-X06"}],"explanation":["「야」 아래쪽에 받침 ㅇ을 더하면 「양」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「양」은 받침 ㅇ 소리까지 끝까지 읽어요."],"concept":"K1-1-u3-C2","difficulty":2,"variant_rule":{"bat":{"ask":"add","mis":{"side":"X02","flip":"X06"},"stem":"sum"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_challenge#2','kor',1,1,'u3','L02','g1_1_kor_u3_L02_challenge','lesson_challenge','K1-1-u3-C2',2,'mc','auto','「ㄷ + ㅏ + 받침 ㄹ」을 모아 쓴 글자는 어느 것인가요?',ARRAY['K1-1-u3-X02','K1-1-u3-X06']::text[],true,'{"seq":2,"concept":"K1-1-u3-C2","difficulty":2,"kind":"mc","stem":"「ㄷ + ㅏ + 받침 ㄹ」을 모아 쓴 글자는 어느 것인가요?","options":[{"t":"달","correct":true},{"t":"다ㄹ","mis":"K1-1-u3-X02"},{"t":"랃","mis":"K1-1-u3-X06"}],"explanation":["ㄷ·ㅏ를 쓰고 받침 ㄹ을 맨 아래에 쓰면 「달」.","「다ㄹ」는 받침을 옆에, 「랃」은 첫 자음자와 받침 자리를 바꿨어요.","조각마다 자리가 정해져 있어요."],"variant_rule":{"alt":[{"stem":"「ㅂ + ㅜ + 받침 ㄱ」을 모아 쓴 글자는 어느 것인가요?","options":[{"t":"북","correct":true},{"t":"부ㄱ","mis":"K1-1-u3-X02"},{"t":"굽","mis":"K1-1-u3-X06"}],"explanation":["ㅂ·ㅜ를 쓰고 받침 ㄱ을 맨 아래에 쓰면 「북」.","「부ㄱ」는 받침을 옆에, 「굽」은 자리를 바꿨어요.","조각마다 자리가 정해져 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_challenge#3','kor',1,1,'u3','L02','g1_1_kor_u3_L02_challenge','lesson_challenge','K1-1-u3-C3',3,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X06']::text[],true,'{"seq":3,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"돌다리","at":0,"pic":"🌉"},"options":[{"t":"ㄹ","correct":true},{"t":"ㄴ","mis":"K1-1-u3-X03"},{"t":"ㄷ","mis":"K1-1-u3-X06"}],"explanation":["그림은 「돌다리」예요.","「도」에 받침 ㄹ을 넣어야 「돌」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u3-C3","difficulty":3,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X03","role":"X06"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_challenge#4','kor',1,1,'u3','L02','g1_1_kor_u3_L02_challenge','lesson_challenge','K1-1-u3-C2',3,'error','auto','준우가 「북」을 「부ㄱ」처럼 받침을 옆에 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u3-X02','K1-1-u3-X03','K1-1-u3-X06']::text[],true,'{"seq":4,"concept":"K1-1-u3-C2","difficulty":3,"kind":"error","stem":"준우가 「북」을 「부ㄱ」처럼 받침을 옆에 썼어요. 무엇이 잘못되었나요?","options":[{"t":"받침은 모음자 ㅜ 아래, 글자 맨 아래에 써야 해요","correct":true,"mis_target":"K1-1-u3-X02"},{"t":"ㄱ 대신 ㅇ을 써야 해요 — 「붕」","mis":"K1-1-u3-X03"},{"t":"받침을 쓰면 모음자도 ㅗ로 바꿔야 해요 — 「복」","mis":"K1-1-u3-X06"}],"explanation":["「북」의 받침 ㄱ은 맨 아래에 써요.","받침도 모음자도 바꿀 필요는 없어요.","옆에 쓰면 한 글자가 되지 않아요."],"variant_rule":{"alt":[{"stem":"서윤이가 「달」을 「다ㄹ」처럼 받침을 옆에 썼어요. 무엇이 잘못되었나요?","options":[{"t":"받침은 글자 맨 아래에 써야 해요","correct":true,"mis_target":"K1-1-u3-X02"},{"t":"ㄹ 대신 ㄴ을 써야 해요 — 「단」","mis":"K1-1-u3-X03"},{"t":"받침을 쓰면 모음자도 ㅓ로 바꿔야 해요 — 「덜」","mis":"K1-1-u3-X06"}],"explanation":["「달」의 받침 ㄹ은 맨 아래에 써요.","받침도 모음자도 바꿀 필요는 없어요.","옆에 쓰면 한 글자가 되지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_challenge#5','kor',1,1,'u3','L02','g1_1_kor_u3_L02_challenge','lesson_challenge','K1-1-u3-C3',3,'mc','auto','「바라」에 받침 ㅁ을 넣어 바람이 불 때의 「바람」을 만들려고 해요. 받침은 어느 글자 아래에 넣나요?',ARRAY['K1-1-u3-X04','K1-1-u3-X05']::text[],true,'{"seq":5,"concept":"K1-1-u3-C3","difficulty":3,"kind":"mc","stem":"「바라」에 받침 ㅁ을 넣어 바람이 불 때의 「바람」을 만들려고 해요. 받침은 어느 글자 아래에 넣나요?","options":[{"t":"「라」","correct":true},{"t":"「바」","mis":"K1-1-u3-X04"},{"t":"두 글자 모두","mis":"K1-1-u3-X05"}],"explanation":["「라」 + 받침 ㅁ = 「람」 → 「바람」.","「바」에 넣으면 「밤라」가 돼요.","천천히 읽으며 소리가 닫히는 글자를 찾아요."],"variant_rule":{"alt":[{"stem":"「구르」에 받침 ㅁ을 넣어 하늘의 「구름」을 만들려고 해요. 받침은 어느 글자 아래에 넣나요?","options":[{"t":"「르」","correct":true},{"t":"「구」","mis":"K1-1-u3-X04"},{"t":"두 글자 모두","mis":"K1-1-u3-X05"}],"explanation":["「르」 + 받침 ㅁ = 「름」 → 「구름」.","「구」에 넣으면 「굼르」가 돼요.","소리가 닫히는 글자를 찾아요."]},{"stem":"「창무」에 받침 ㄴ을 넣어 「창문」을 만들려고 해요. 받침은 어느 글자 아래에 넣나요?","options":[{"t":"「무」","correct":true},{"t":"「창」","mis":"K1-1-u3-X04"},{"t":"두 글자 모두","mis":"K1-1-u3-X05"}],"explanation":["「무」 + 받침 ㄴ = 「문」 → 「창문」.","「창」에는 이미 받침 ㅇ이 있어요.","빠진 자리를 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_challenge#6','kor',1,1,'u3','L02','g1_1_kor_u3_L02_challenge','lesson_challenge','K1-1-u3-C2',3,'mc','auto','「곰」에서 받침만 바꾸어 만든 낱말은 어느 것인가요?',ARRAY['K1-1-u3-X06']::text[],true,'{"seq":6,"concept":"K1-1-u3-C2","difficulty":3,"kind":"mc","stem":"「곰」에서 받침만 바꾸어 만든 낱말은 어느 것인가요?","options":[{"t":"공","correct":true},{"t":"봄","mis":"K1-1-u3-X06"},{"t":"감","mis":"K1-1-u3-X06"}],"explanation":["곰 → 공: 받침 ㅁ을 ㅇ으로 바꿨어요.","「봄」은 첫 자음자를, 「감」은 모음자를 바꿨어요.","바꿀 곳은 맨 아래 받침 칸."],"variant_rule":{"alt":[{"stem":"「달」에서 받침만 바꾸어 만든 낱말은 어느 것인가요?","options":[{"t":"단","correct":true},{"t":"말","mis":"K1-1-u3-X06"},{"t":"돌","mis":"K1-1-u3-X06"}],"explanation":["달 → 단: 받침 ㄹ을 ㄴ으로 바꿨어요.","「말」은 첫 자음자를, 「돌」은 모음자를 바꿨어요.","바꿀 곳은 받침 칸."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_challenge#7','kor',1,1,'u3','L02','g1_1_kor_u3_L02_challenge','lesson_challenge','K1-1-u3-C3',3,'mc','auto','「거우」의 빠진 받침을 넣어 그림의 낱말을 완성하면 어떤 낱말이 되나요?',ARRAY['K1-1-u3-X03','K1-1-u3-X04']::text[],true,'{"seq":7,"concept":"K1-1-u3-C3","difficulty":3,"kind":"mc","stem":"「거우」의 빠진 받침을 넣어 그림의 낱말을 완성하면 어떤 낱말이 되나요?","options":[{"t":"거울","correct":true},{"t":"거운","mis":"K1-1-u3-X03"},{"t":"걸우","mis":"K1-1-u3-X04"}],"explanation":["「우」 + 받침 ㄹ = 「울」 → 「거울」.","「거운」은 받침이 틀렸고, 「걸우」는 자리가 틀렸어요.","그림의 뜻을 떠올려요."],"asset":{"type":"scene","icon":"🪞","text":"거우"},"variant_rule":{"alt":[{"stem":"「구르」의 빠진 받침을 넣어 그림의 낱말을 완성하면 어떤 낱말이 되나요?","options":[{"t":"구름","correct":true},{"t":"구릉","mis":"K1-1-u3-X03"},{"t":"굼르","mis":"K1-1-u3-X04"}],"explanation":["「르」 + 받침 ㅁ = 「름」 → 「구름」.","「구릉」은 받침이 틀렸고, 「굼르」는 자리가 틀렸어요.","그림의 뜻을 떠올려요."],"asset":{"type":"scene","icon":"☁️","text":"구르"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_challenge#8','kor',1,1,'u3','L02','g1_1_kor_u3_L02_challenge','lesson_challenge','K1-1-u3-C2',4,'mc','auto','「감」을 만든 조각 「ㄱ · ㅏ · ㅁ」을 그대로 쓰되 자리만 바꾸어 만들 수 있는 글자는 어느 것인가요?',ARRAY['K1-1-u3-X02','K1-1-u3-X06']::text[],true,'{"seq":8,"concept":"K1-1-u3-C2","difficulty":4,"kind":"mc","stem":"「감」을 만든 조각 「ㄱ · ㅏ · ㅁ」을 그대로 쓰되 자리만 바꾸어 만들 수 있는 글자는 어느 것인가요?","options":[{"t":"막","correct":true},{"t":"마ㄱ","mis":"K1-1-u3-X02"},{"t":"각","mis":"K1-1-u3-X06"}],"explanation":["ㅁ을 첫 자음자로, ㄱ을 받침으로 바꾸면 「막」.","「마ㄱ」는 받침을 옆에, 「각」은 ㅁ 조각을 빠뜨렸어요.","같은 조각도 자리가 바뀌면 다른 글자예요."],"variant_rule":{"alt":[{"stem":"「곰」을 만든 조각 「ㄱ · ㅗ · ㅁ」을 그대로 쓰되 자리만 바꾸어 만들 수 있는 글자는 어느 것인가요?","options":[{"t":"목","correct":true},{"t":"모ㄱ","mis":"K1-1-u3-X02"},{"t":"곡","mis":"K1-1-u3-X06"}],"explanation":["ㅁ을 첫 자음자로, ㄱ을 받침으로 바꾸면 「목」.","「모ㄱ」는 받침을 옆에, 「곡」은 ㅁ 조각을 빠뜨렸어요.","자리가 바뀌면 다른 글자예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_challenge#9','kor',1,1,'u3','L02','g1_1_kor_u3_L02_challenge','lesson_challenge','K1-1-u3-C2',4,'essay','teacher','「달」을 세 조각으로 나누고, 받침이 어디에 들어가는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u3-C2","difficulty":4,"kind":"essay","stem":"「달」을 세 조각으로 나누고, 받침이 어디에 들어가는지 설명해 보세요.","answer_guide":{"answer":"예: 「달」은 첫 자음자 ㄷ, 모음자 ㅏ, 받침 ㄹ로 나뉘어요. 받침 ㄹ은 글자 맨 아래에 들어가요.","scoring_points":["세 조각(ㄷ·ㅏ·ㄹ)으로 바르게 나누었는가","받침이 ㄹ이라고 찾았는가","받침이 맨 아래에 들어간다고 말했는가"]},"explanation":["ㄷ·ㅏ·ㄹ 세 조각.","받침은 ㄹ.","받침 자리는 맨 아래."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L02_challenge#10','kor',1,1,'u3','L02','g1_1_kor_u3_L02_challenge','lesson_challenge','K1-1-u3-C3',4,'sa','auto','그림을 보고 빠진 받침을 모두 넣어 낱말을 바르게 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"K1-1-u3-C3","difficulty":4,"kind":"sa","stem":"그림을 보고 빠진 받침을 모두 넣어 낱말을 바르게 쓰세요.","answer":["축구공"],"explanation":["「추」 + ㄱ = 「축」, 「고」 + ㅇ = 「공」.","받침이 두 글자에 들어가요.","다 쓴 뒤 소리 내어 읽어 확인해요."],"asset":{"type":"scene","icon":"⚽","text":"추구고"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림을 보고 빠진 받침을 모두 넣어 낱말을 바르게 쓰세요.","answer":["징검다리"],"explanation":["「지」 + ㅇ = 「징」, 「거」 + ㅁ = 「검」.","받침이 두 글자에 들어가요.","다 쓴 뒤 소리 내어 읽어요."],"asset":{"type":"scene","icon":"🪨","text":"지거다리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_basic#1','kor',1,1,'u3','L04','g1_1_kor_u3_L04_basic','lesson_basic','K1-1-u3-C4',1,'mc','auto','비를 막는 것을 「우상」이라고 잘못 썼어요. 바르게 고친 낱말은 어느 것인가요?',ARRAY['K1-1-u3-X01','K1-1-u3-X03']::text[],true,'{"seq":1,"concept":"K1-1-u3-C4","difficulty":1,"kind":"mc","stem":"비를 막는 것을 「우상」이라고 잘못 썼어요. 바르게 고친 낱말은 어느 것인가요?","options":[{"t":"우산","correct":true},{"t":"우사","mis":"K1-1-u3-X01"},{"t":"우삼","mis":"K1-1-u3-X03"}],"explanation":["비를 막는 것은 「우산」 — 받침 ㄴ.","「우사」는 받침을 빼고, 「우삼」은 다른 받침을 넣었어요.","고친 뒤 소리 내어 읽어 확인해요."],"asset":{"type":"scene","icon":"☂️","text":"우상"},"variant_rule":{"alt":[{"stem":"비 올 때 신는 것을 「잠화」라고 잘못 썼어요. 바르게 고친 낱말은 어느 것인가요?","options":[{"t":"장화","correct":true},{"t":"자화","mis":"K1-1-u3-X01"},{"t":"잔화","mis":"K1-1-u3-X03"}],"explanation":["비 올 때 신는 것은 「장화」 — 받침 ㅇ.","「자화」는 받침을 빼고, 「잔화」는 다른 받침을 넣었어요.","고친 뒤 소리 내어 읽어요."],"asset":{"type":"scene","icon":"👢","text":"잠화"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_basic#2','kor',1,1,'u3','L04','g1_1_kor_u3_L04_basic','lesson_basic','K1-1-u3-C4',1,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X06']::text[],true,'{"seq":2,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"책","at":0,"pic":"📕"},"options":[{"t":"ㄱ","correct":true},{"t":"ㅇ","mis":"K1-1-u3-X03"},{"t":"ㅊ","mis":"K1-1-u3-X06"}],"explanation":["그림은 「책」이에요.","「채」에 받침 ㄱ을 넣어야 「책」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u3-C4","difficulty":1,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X03","role":"X06"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_basic#3','kor',1,1,'u3','L04','g1_1_kor_u3_L04_basic','lesson_basic','K1-1-u3-C5',1,'mc','auto','글씨를 쓸 때 바른 자세는 어느 것인가요?',ARRAY['K1-1-u3-X08']::text[],true,'{"seq":3,"concept":"K1-1-u3-C5","difficulty":1,"kind":"mc","stem":"글씨를 쓸 때 바른 자세는 어느 것인가요?","options":[{"t":"허리를 펴고 바르게 앉아요","correct":true},{"t":"책상에 엎드려 써요","mis":"K1-1-u3-X08"},{"t":"다리를 꼬고 비스듬히 앉아요","mis":"K1-1-u3-X08"}],"explanation":["허리를 펴고 앉으면 글씨가 반듯해져요.","엎드리거나 비스듬히 앉으면 받침이 삐뚤어져요.","바른 자세가 바른 글씨의 시작이에요."],"variant_rule":{"alt":[{"stem":"글씨를 쓸 때 공책은 어떻게 놓나요?","options":[{"t":"몸 앞에 살짝 기울여 놓아요","correct":true},{"t":"책상 끝에 반쯤 걸쳐 놓아요","mis":"K1-1-u3-X08"},{"t":"무릎 위에 올려놓아요","mis":"K1-1-u3-X08"}],"explanation":["공책을 살짝 기울이면 글씨가 잘 써져요.","걸치거나 무릎에 올리면 공책이 흔들려요.","바른 자세가 바른 글씨의 시작이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_basic#4','kor',1,1,'u3','L04','g1_1_kor_u3_L04_basic','lesson_basic','K1-1-u3-C4',1,'ox','auto','거울을 「거우」라고 쓰면 받침을 빠뜨린 거예요.',ARRAY['K1-1-u3-X01']::text[],true,'{"seq":4,"concept":"K1-1-u3-C4","difficulty":1,"kind":"ox","stem":"거울을 「거우」라고 쓰면 받침을 빠뜨린 거예요.","answer":"O","reason_options":[{"t":"「우」 아래에 받침 ㄹ이 있어야 「거울」이 되니까","correct":true},{"t":"받침은 빠뜨려도 같은 낱말이니까","mis":"K1-1-u3-X01"}],"mis":"K1-1-u3-X01","explanation":["「거울」은 「울」에 받침 ㄹ이 있어요.","「거우」는 받침이 빠져 뜻이 사라졌어요.","받침까지 바르게 써요."],"asset":{"type":"scene","icon":"🪞"},"variant_rule":{"alt":[{"stem":"물통을 「물통」이라고 쓰면 바르게 쓴 거예요.","answer":"O","reason_options":[{"t":"물을 담는 통이니까 「물」에 받침 ㄹ이 있어야 하니까","correct":true},{"t":"소리 나는 대로 「무통」이라고 써야 하니까","mis":"K1-1-u3-X01"}],"explanation":["「물통」은 「물」에 받침 ㄹ이 있어요.","소리에 끌려 받침을 빼지 않아요.","뜻을 떠올리며 써요."],"asset":{"type":"scene","icon":"🫙"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_basic#5','kor',1,1,'u3','L04','g1_1_kor_u3_L04_basic','lesson_basic','K1-1-u3-C4',2,'mc','auto','「잠화」의 받침을 바르게 고치려면 어떻게 해야 하나요?',ARRAY['K1-1-u3-X04','K1-1-u3-X03']::text[],true,'{"seq":5,"concept":"K1-1-u3-C4","difficulty":2,"kind":"mc","stem":"「잠화」의 받침을 바르게 고치려면 어떻게 해야 하나요?","options":[{"t":"「잠」의 받침 ㅁ을 ㅇ으로 바꿔요","correct":true},{"t":"「화」에 받침 ㅇ을 넣어요","mis":"K1-1-u3-X04"},{"t":"「잠」의 받침 ㅁ을 ㄴ으로 바꿔요","mis":"K1-1-u3-X03"}],"explanation":["「잠」 → 「장」: 받침 ㅁ 자리에 ㅇ.","「화」는 그대로, ㄴ을 넣으면 「잔화」가 돼요.","틀린 곳을 찾고 → 고치고 → 읽어 확인해요."],"asset":{"type":"scene","icon":"👢","text":"잠화"},"variant_rule":{"alt":[{"stem":"「우상」의 받침을 바르게 고치려면 어떻게 해야 하나요?","options":[{"t":"「상」의 받침 ㅇ을 ㄴ으로 바꿔요","correct":true},{"t":"「우」에 받침 ㄴ을 넣어요","mis":"K1-1-u3-X04"},{"t":"「상」의 받침 ㅇ을 ㅁ으로 바꿔요","mis":"K1-1-u3-X03"}],"explanation":["「상」 → 「산」: 받침 ㅇ 자리에 ㄴ.","「우」는 그대로, ㅁ을 넣으면 「우삼」이 돼요.","틀린 곳 → 고치기 → 읽어 확인."],"asset":{"type":"scene","icon":"☂️","text":"우상"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_basic#6','kor',1,1,'u3','L04','g1_1_kor_u3_L04_basic','lesson_basic','K1-1-u3-C4',2,'mc','auto','그림을 보고 바르게 쓴 낱말을 고르세요.',ARRAY['K1-1-u3-X01','K1-1-u3-X03']::text[],true,'{"seq":6,"concept":"K1-1-u3-C4","difficulty":2,"kind":"mc","stem":"그림을 보고 바르게 쓴 낱말을 고르세요.","options":[{"t":"물통","correct":true},{"t":"무통","mis":"K1-1-u3-X01"},{"t":"물톤","mis":"K1-1-u3-X03"}],"explanation":["물을 담는 통 — 「물통」.","「무통」은 받침 ㄹ을, 「물톤」은 받침 ㅇ을 잘못 썼어요.","소리보다 뜻을 먼저 떠올려요."],"asset":{"type":"scene","icon":"🫙"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림을 보고 바르게 쓴 낱말을 고르세요.","options":[{"t":"거울","correct":true},{"t":"거우","mis":"K1-1-u3-X01"},{"t":"거운","mis":"K1-1-u3-X03"}],"explanation":["얼굴을 비추는 「거울」.","「거우」는 받침을 빼고, 「거운」은 다른 받침을 넣었어요.","뜻을 먼저 떠올려요."],"asset":{"type":"scene","icon":"🪞"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_basic#7','kor',1,1,'u3','L04','g1_1_kor_u3_L04_basic','lesson_basic','K1-1-u3-C4',2,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X06']::text[],true,'{"seq":7,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"화분","at":1,"pic":"🪴"},"options":[{"t":"ㄴ","correct":true},{"t":"ㅇ","mis":"K1-1-u3-X03"},{"t":"ㅂ","mis":"K1-1-u3-X06"}],"explanation":["그림은 「화분」이에요.","「부」에 받침 ㄴ을 넣어야 「분」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u3-C4","difficulty":2,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X03","role":"X06"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_basic#8','kor',1,1,'u3','L04','g1_1_kor_u3_L04_basic','lesson_basic','K1-1-u3-C4',2,'match','auto','잘못 쓴 낱말과 바르게 고친 낱말을 이으세요.','{}'::text[],true,'{"seq":8,"concept":"K1-1-u3-C4","difficulty":2,"kind":"match","stem":"잘못 쓴 낱말과 바르게 고친 낱말을 이으세요.","pairs":[{"l":"잠화","r":"장화"},{"l":"거우","r":"거울"},{"l":"추발","r":"출발"}],"mis":"K1-1-u3-X03","explanation":["잠화 → 장화, 거우 → 거울, 추발 → 출발.","받침을 바꾸거나 빠진 받침을 넣었어요.","고친 뒤 소리 내어 읽어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 잘못 쓴 낱말과 바르게 고친 낱말을 이으세요.","pairs":[{"l":"우상","r":"우산"},{"l":"화부","r":"화분"},{"l":"땅코","r":"땅콩"}],"explanation":["우상 → 우산, 화부 → 화분, 땅코 → 땅콩.","받침을 바꾸거나 빠진 받침을 넣었어요.","고친 뒤 소리 내어 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_basic#9','kor',1,1,'u3','L04','g1_1_kor_u3_L04_basic','lesson_basic','K1-1-u3-C5',2,'mc','auto','연필은 어떻게 잡아야 하나요?',ARRAY['K1-1-u3-X08']::text[],false,'{"seq":9,"concept":"K1-1-u3-C5","difficulty":2,"kind":"mc","stem":"연필은 어떻게 잡아야 하나요?","options":[{"t":"엄지와 검지로 가볍게 잡고 가운데손가락으로 받쳐요","correct":true},{"t":"주먹으로 꽉 움켜쥐어요","mis":"K1-1-u3-X08"},{"t":"연필 끝을 아주 짧게 잡아요","mis":"K1-1-u3-X08"}],"explanation":["세 손가락으로 가볍게 잡으면 오래 써도 덜 아파요.","움켜쥐거나 너무 짧게 잡으면 글씨가 흔들려요.","바르게 잡아야 받침까지 또박또박 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_basic#10','kor',1,1,'u3','L04','g1_1_kor_u3_L04_basic','lesson_basic','K1-1-u3-C4',3,'error','auto','하린이가 쓴 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_challenge#1','kor',1,1,'u3','L04','g1_1_kor_u3_L04_challenge','lesson_challenge','K1-1-u3-C4',2,'mc','auto','「방」의 받침 ㅇ을 ㄹ로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X06','K1-1-u3-X16']::text[],true,'{"seq":1,"kind":"mc","stem":"「방」의 받침 ㅇ을 ㄹ로 바꾸면 어떤 글자가 되나요?","asset":{"type":"bat","s":"방","eq":false},"options":[{"t":"발","correct":true},{"t":"랑","mis":"K1-1-u3-X06"},{"t":"방","mis":"K1-1-u3-X16"}],"explanation":["「방」에서 받침 ㅇ 자리에 ㄹ을 넣으면 「발」이에요.","맨 앞 자음자 ㅂ과 모음자 ㅏ는 그대로예요.","받침이 바뀌면 글자도 소리도 뜻도 달라져요."],"concept":"K1-1-u3-C4","difficulty":2,"variant_rule":{"bat":{"ask":"swap","mis":{"role":"X06","keep":"X16"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_challenge#2','kor',1,1,'u3','L04','g1_1_kor_u3_L04_challenge','lesson_challenge','K1-1-u3-C4',2,'mc','auto','출발에서 도착까지 바르게 쓴 낱말만 차례로 고른 것은 어느 것인가요?',ARRAY['K1-1-u3-X01']::text[],true,'{"seq":2,"concept":"K1-1-u3-C4","difficulty":2,"kind":"mc","stem":"출발에서 도착까지 바르게 쓴 낱말만 차례로 고른 것은 어느 것인가요?","options":[{"t":"출발 → 땅콩 → 기린","correct":true},{"t":"추발 → 땅콩 → 기린","mis":"K1-1-u3-X01"},{"t":"출발 → 땅코 → 기리","mis":"K1-1-u3-X01"}],"explanation":["출발·땅콩·기린은 받침을 바르게 썼어요.","추발·땅코·기리는 받침이 빠졌어요.","갈림길마다 받침을 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 출발에서 도착까지 바르게 쓴 낱말만 차례로 고른 것은 어느 것인가요?","options":[{"t":"장화 → 우산 → 화분","correct":true},{"t":"잠화 → 우산 → 화분","mis":"K1-1-u3-X03"},{"t":"장화 → 우상 → 화부","mis":"K1-1-u3-X03"}],"explanation":["장화·우산·화분은 받침을 바르게 썼어요.","잠화·우상·화부는 받침이 틀리거나 빠졌어요.","갈림길마다 받침을 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_challenge#3','kor',1,1,'u3','L04','g1_1_kor_u3_L04_challenge','lesson_challenge','K1-1-u3-C4',3,'error','auto','시우가 그림을 보고 「화부」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u3-X01','K1-1-u3-X04','K1-1-u3-X03']::text[],true,'{"seq":3,"concept":"K1-1-u3-C4","difficulty":3,"kind":"error","stem":"시우가 그림을 보고 「화부」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"「부」에 받침 ㄴ을 빠뜨렸어요 — 「화분」","correct":true,"mis_target":"K1-1-u3-X01"},{"t":"「화」에 받침 ㄴ을 넣어야 해요 — 「환부」","mis":"K1-1-u3-X04"},{"t":"「부」에 받침 ㅇ을 넣어야 해요 — 「화붕」","mis":"K1-1-u3-X03"}],"explanation":["꽃을 심는 것은 「화분」 — 「분」의 받침 ㄴ.","「환부」·「화붕」은 다른 말이에요.","뜻을 떠올리며 받침 자리를 찾아요."],"asset":{"type":"scene","icon":"🪴","text":"화부"},"variant_rule":{"alt":[{"stem":"민호가 그림을 보고 「구르」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"「르」에 받침 ㅁ을 빠뜨렸어요 — 「구름」","correct":true,"mis_target":"K1-1-u3-X01"},{"t":"「구」에 받침 ㅁ을 넣어야 해요 — 「굼르」","mis":"K1-1-u3-X04"},{"t":"「르」에 받침 ㅇ을 넣어야 해요 — 「구릉」","mis":"K1-1-u3-X03"}],"explanation":["하늘에 뜬 것은 「구름」 — 「름」의 받침 ㅁ.","「굼르」·「구릉」은 그림과 달라요.","뜻을 떠올리며 받침 자리를 찾아요."],"asset":{"type":"scene","icon":"☁️","text":"구르"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_challenge#4','kor',1,1,'u3','L04','g1_1_kor_u3_L04_challenge','lesson_challenge','K1-1-u3-C4',3,'mc','auto','「무통」처럼 소리에 끌려 받침을 빼고 쓰지 않으려면 어떻게 하면 좋을까요?',ARRAY['K1-1-u3-X01','K1-1-u3-X07']::text[],false,'{"seq":4,"concept":"K1-1-u3-C4","difficulty":3,"kind":"mc","stem":"「무통」처럼 소리에 끌려 받침을 빼고 쓰지 않으려면 어떻게 하면 좋을까요?","options":[{"t":"물을 담는 통이라는 뜻을 떠올리며 받침 ㄹ을 챙겨요","correct":true},{"t":"들리는 소리대로만 빨리 써요","mis":"K1-1-u3-X01"},{"t":"받침은 나중에 아무거나 넣어요","mis":"K1-1-u3-X07"}],"explanation":["뜻을 떠올리면 빠진 받침이 보여요.","소리대로만 쓰면 받침을 놓치기 쉬워요.","쓴 뒤 소리 내어 읽어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_challenge#5','kor',1,1,'u3','L04','g1_1_kor_u3_L04_challenge','lesson_challenge','K1-1-u3-C4',3,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X06']::text[],true,'{"seq":5,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"구름","at":1,"pic":"☁️"},"options":[{"t":"ㅁ","correct":true},{"t":"ㅂ","mis":"K1-1-u3-X03"},{"t":"ㄹ","mis":"K1-1-u3-X06"}],"explanation":["그림은 「구름」이에요.","「르」에 받침 ㅁ을 넣어야 「름」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u3-C4","difficulty":3,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X03","role":"X06"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_challenge#6','kor',1,1,'u3','L04','g1_1_kor_u3_L04_challenge','lesson_challenge','K1-1-u3-C5',3,'mc','auto','바르게 쓰기 위한 준비로 알맞지 않은 것은 어느 것인가요?',ARRAY['K1-1-u3-X08']::text[],true,'{"seq":6,"concept":"K1-1-u3-C5","difficulty":3,"kind":"mc","stem":"바르게 쓰기 위한 준비로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"공책을 무릎 위에 올려놓고 써요","correct":true},{"t":"허리를 펴고 앉아요","mis":"K1-1-u3-X08"},{"t":"공책을 살짝 기울여 놓아요","mis":"K1-1-u3-X08"}],"explanation":["공책은 책상 위에 살짝 기울여 놓아요.","허리 펴기·공책 기울이기는 알맞은 준비예요.","바른 자세가 바른 글씨의 시작이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 바르게 쓰기 위한 준비로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"빨리 끝내려고 글자를 몰아서 써요","correct":true},{"t":"연필을 가볍게 바르게 잡아요","mis":"K1-1-u3-X08"},{"t":"한 글자씩 짜임을 생각하며 써요","mis":"K1-1-u3-X08"}],"explanation":["빨리 몰아 쓰면 받침을 빠뜨리기 쉬워요.","연필 바로 잡기·짜임 생각하기는 알맞아요.","천천히 또박또박이 먼저예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_challenge#7','kor',1,1,'u3','L04','g1_1_kor_u3_L04_challenge','lesson_challenge','K1-1-u3-C4',3,'mc','auto','받침을 바르게 쓴 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K1-1-u3-X03']::text[],true,'{"seq":7,"concept":"K1-1-u3-C4","difficulty":3,"kind":"mc","stem":"받침을 바르게 쓴 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"장화 · 우산 · 화분","correct":true},{"t":"장화 · 우상 · 화분","mis":"K1-1-u3-X03"},{"t":"잠화 · 우산 · 화분","mis":"K1-1-u3-X03"}],"explanation":["장화(ㅇ)·우산(ㄴ)·화분(ㄴ) 모두 바르게 썼어요.","우상·잠화는 받침이 틀렸어요.","낱말마다 뜻과 받침을 견줘요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받침을 바르게 쓴 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"거울 · 물통 · 구름","correct":true},{"t":"거울 · 무통 · 구름","mis":"K1-1-u3-X01"},{"t":"거우 · 물통 · 구름","mis":"K1-1-u3-X01"}],"explanation":["거울·물통·구름 모두 바르게 썼어요.","무통·거우는 받침이 빠졌어요.","낱말마다 받침을 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_challenge#8','kor',1,1,'u3','L04','g1_1_kor_u3_L04_challenge','lesson_challenge','K1-1-u3-C4',4,'mc','auto','다음 문장에서 잘못 쓴 낱말 두 개를 바르게 고친 것은 어느 것인가요?',ARRAY['K1-1-u3-X05']::text[],true,'{"seq":8,"concept":"K1-1-u3-C4","difficulty":4,"kind":"mc","stem":"다음 문장에서 잘못 쓴 낱말 두 개를 바르게 고친 것은 어느 것인가요?","options":[{"t":"장화, 우산","correct":true},{"t":"장화, 우상","mis":"K1-1-u3-X05"},{"t":"잠화, 우산","mis":"K1-1-u3-X05"}],"explanation":["「잠화」 → 「장화」, 「우상」 → 「우산」.","하나만 고치면 아직 틀린 낱말이 남아요.","문장 끝까지 낱말마다 받침을 살펴요."],"asset":{"type":"passage","lines":["잠화를 신고 우상을 썼어요."]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 문장에서 잘못 쓴 낱말 두 개를 바르게 고친 것은 어느 것인가요?","options":[{"t":"물통, 거울","correct":true},{"t":"물통, 거우","mis":"K1-1-u3-X05"},{"t":"무통, 거울","mis":"K1-1-u3-X05"}],"explanation":["「무통」 → 「물통」, 「거우」 → 「거울」.","하나만 고치면 아직 틀린 낱말이 남아요.","끝까지 살펴요."],"asset":{"type":"passage","lines":["무통을 들고 거우 앞에 섰어요."]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_challenge#9','kor',1,1,'u3','L04','g1_1_kor_u3_L04_challenge','lesson_challenge','K1-1-u3-C4',4,'essay','teacher','틀린 받침을 고치는 차례를 「잠화 → 장화」를 예로 들어 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u3-C4","difficulty":4,"kind":"essay","stem":"틀린 받침을 고치는 차례를 「잠화 → 장화」를 예로 들어 말해 보세요.","answer_guide":{"answer":"예: 먼저 틀린 곳(「잠」의 받침 ㅁ)을 찾고, 바른 받침 ㅇ으로 고친 뒤, 「장화」라고 소리 내어 읽어 확인해요.","scoring_points":["틀린 곳(받침 ㅁ)을 찾는다고 말했는가","바른 받침(ㅇ)으로 고친다고 말했는가","소리 내어 읽어 확인한다고 말했는가"]},"explanation":["틀린 곳 찾기.","바른 받침으로 고치기.","소리 내어 읽어 확인하기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L04_challenge#10','kor',1,1,'u3','L04','g1_1_kor_u3_L04_challenge','lesson_challenge','K1-1-u3-C4',4,'mc','auto','친구가 「발에 양말을 신었어요.」를 「밥에 양말을 신었어요.」라고 썼어요. 무엇이 문제인가요?',ARRAY['K1-1-u3-X01','K1-1-u3-X16']::text[],true,'{"seq":10,"concept":"K1-1-u3-C4","difficulty":4,"kind":"mc","stem":"친구가 「발에 양말을 신었어요.」를 「밥에 양말을 신었어요.」라고 썼어요. 무엇이 문제인가요?","options":[{"t":"받침 ㄹ을 ㅂ으로 잘못 써서 먹는 「밥」이 되었어요","correct":true},{"t":"받침을 빠뜨려서 「바」가 되었어요","mis":"K1-1-u3-X01"},{"t":"뜻은 같으니 고치지 않아도 돼요","mis":"K1-1-u3-X16"}],"explanation":["「발」과 「밥」은 받침 하나 차이로 뜻이 달라요.","받침을 빠뜨린 것이 아니라 다른 받침을 썼어요.","받침이 틀리면 엉뚱한 뜻이 돼요."],"variant_rule":{"alt":[{"stem":"친구가 「방에서 잤어요.」를 「밤에서 잤어요.」라고 썼어요. 무엇이 문제인가요?","options":[{"t":"받침 ㅇ을 ㅁ으로 잘못 써서 깜깜한 「밤」이 되었어요","correct":true},{"t":"받침을 빠뜨려서 「바」가 되었어요","mis":"K1-1-u3-X01"},{"t":"뜻은 같으니 고치지 않아도 돼요","mis":"K1-1-u3-X16"}],"explanation":["「방」과 「밤」은 받침 하나 차이로 뜻이 달라요.","받침을 빠뜨린 것이 아니에요.","받침이 틀리면 엉뚱한 뜻이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_basic#1','kor',1,1,'u3','L06','g1_1_kor_u3_L06_basic','lesson_basic','K1-1-u3-C6',1,'mc','auto','ㄱ을 두 번 나란히 쓰면 어떤 자음자가 되나요?',ARRAY['K1-1-u3-X10','K1-1-u3-X09']::text[],true,'{"seq":1,"kind":"mc","stem":"ㄱ을 두 번 나란히 쓰면 어떤 자음자가 되나요?","options":[{"t":"ㄲ","correct":true},{"t":"ㅋ","mis":"K1-1-u3-X10"},{"t":"ㄱ","mis":"K1-1-u3-X09"}],"explanation":["ㄱ을 두 번 나란히 쓰면 ㄲ이에요.","ㅋ은 ㄱ에 획을 하나 더한 것이라 달라요.","ㄲ은 ㄱ보다 더 센 소리를 내요."],"concept":"K1-1-u3-C6","difficulty":1,"variant_rule":{"twin":{"ask":"shape","mis":{"asp":"X10","one":"X09","other":"X09"},"dir":"make"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_basic#2','kor',1,1,'u3','L06','g1_1_kor_u3_L06_basic','lesson_basic','K1-1-u3-C6',1,'mc','auto','된소리 자음자를 모두 모은 것은 어느 것인가요?',ARRAY['K1-1-u3-X10','K1-1-u3-X09']::text[],false,'{"seq":2,"concept":"K1-1-u3-C6","difficulty":1,"kind":"mc","stem":"된소리 자음자를 모두 모은 것은 어느 것인가요?","options":[{"t":"ㄲ ㄸ ㅃ ㅆ ㅉ","correct":true},{"t":"ㅋ ㅌ ㅍ ㅊ ㅎ","mis":"K1-1-u3-X10"},{"t":"ㄱ ㄷ ㅂ ㅅ ㅈ","mis":"K1-1-u3-X09"}],"explanation":["같은 자음자를 두 번 나란히 쓴 다섯 개예요.","ㅋ·ㅌ·ㅍ·ㅊ은 획을 더한 것, ㄱ·ㄷ·ㅂ·ㅅ·ㅈ은 한 번 쓴 것이에요.","ㄲ ㄸ ㅃ ㅆ ㅉ은 소리를 세게 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_basic#3','kor',1,1,'u3','L06','g1_1_kor_u3_L06_basic','lesson_basic','K1-1-u3-C7',1,'mc','auto','그림을 보고 바르게 쓴 낱말을 고르세요.',ARRAY['K1-1-u3-X13','K1-1-u3-X10']::text[],true,'{"seq":3,"kind":"mc","stem":"그림을 보고 바르게 쓴 낱말을 고르세요.","asset":{"type":"scene","icon":"🍓"},"options":[{"t":"딸기","correct":true},{"t":"달기","mis":"K1-1-u3-X13"},{"t":"탈기","mis":"K1-1-u3-X10"}],"explanation":["그림은 「딸기」예요.","ㄸ을 ㄷ 하나로 쓰면 다른 말이 돼요.","소리 내어 읽으며 센 소리가 나는 자음자를 확인해요."],"concept":"K1-1-u3-C7","difficulty":1,"variant_rule":{"twin":{"ask":"word","mis":{"plain":"X13","asp":"X10","other":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_basic#4','kor',1,1,'u3','L06','g1_1_kor_u3_L06_basic','lesson_basic','K1-1-u3-C6',1,'ox','auto','ㅃ은 ㅂ을 두 번 나란히 쓴 자음자예요.',ARRAY['K1-1-u3-X10']::text[],true,'{"seq":4,"concept":"K1-1-u3-C6","difficulty":1,"kind":"ox","stem":"ㅃ은 ㅂ을 두 번 나란히 쓴 자음자예요.","answer":"O","reason_options":[{"t":"같은 자음자 ㅂ이 두 개 나란히 있으니까","correct":true},{"t":"ㅂ에 획을 하나 더 그은 것이니까","mis":"K1-1-u3-X10"}],"mis":"K1-1-u3-X10","explanation":["ㅂ + ㅂ = ㅃ.","획을 더한 것은 ㅍ이에요.","ㄲ·ㄸ·ㅆ·ㅉ도 같은 방법이에요."],"variant_rule":{"alt":[{"stem":"ㅋ은 ㄱ을 두 번 나란히 쓴 자음자예요.","answer":"X","reason_options":[{"t":"ㄱ을 두 번 쓴 것은 ㄲ이고, ㅋ은 ㄱ에 획을 더한 것이니까","correct":true},{"t":"ㅋ과 ㄲ은 같은 자음자니까","mis":"K1-1-u3-X10"}],"explanation":["ㄱ + ㄱ = ㄲ.","ㅋ은 ㄱ에 획을 하나 더한 자음자예요.","모양을 견줘 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_basic#5','kor',1,1,'u3','L06','g1_1_kor_u3_L06_basic','lesson_basic','K1-1-u3-C7',2,'mc','auto','「방」의 ㅂ을 ㅃ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X11','K1-1-u3-X10']::text[],true,'{"seq":5,"kind":"mc","stem":"「방」의 ㅂ을 ㅃ으로 바꾸면 어떤 글자가 되나요?","options":[{"t":"빵","correct":true},{"t":"방","mis":"K1-1-u3-X11"},{"t":"팡","mis":"K1-1-u3-X10"}],"explanation":["「방」에서 ㅂ 자리에 ㅃ을 넣으면 「빵」이에요.","모음자와 받침은 그대로예요.","ㅃ은 ㅂ보다 센 소리 — 자음자가 바뀌면 뜻도 달라져요."],"concept":"K1-1-u3-C7","difficulty":2,"variant_rule":{"twin":{"ask":"swap","mis":{"keep":"X11","asp":"X10","other":"X09"},"dir":"up"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_basic#6','kor',1,1,'u3','L06','g1_1_kor_u3_L06_basic','lesson_basic','K1-1-u3-C7',2,'mc','auto','된소리 ㄲ이 들어간 낱말은 어느 것인가요?',ARRAY['K1-1-u3-X12','K1-1-u3-X10']::text[],true,'{"seq":6,"kind":"mc","stem":"된소리 ㄲ이 들어간 낱말은 어느 것인가요?","options":[{"t":"까치","correct":true},{"t":"가방","mis":"K1-1-u3-X12"},{"t":"코","mis":"K1-1-u3-X10"}],"explanation":["「까치」에는 ㄲ이 들어 있어요.","ㄱ·ㅋ이 든 낱말과 견주어 읽어 봐요.","소리 내어 읽고, 글자에서 같은 자음자를 두 번 쓴 곳을 찾아요."],"concept":"K1-1-u3-C7","difficulty":2,"variant_rule":{"twin":{"ask":"pick","mis":{"soft":"X12","asp":"X10","other":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_basic#7','kor',1,1,'u3','L06','g1_1_kor_u3_L06_basic','lesson_basic','K1-1-u3-C7',2,'match','auto','예사소리 낱말과 된소리 낱말의 짝을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"K1-1-u3-C7","difficulty":2,"kind":"match","stem":"예사소리 낱말과 된소리 낱말의 짝을 이으세요.","pairs":[{"l":"굴","r":"꿀"},{"l":"달","r":"딸"},{"l":"살","r":"쌀"}],"mis":"K1-1-u3-X11","explanation":["굴 ↔ 꿀, 달 ↔ 딸, 살 ↔ 쌀.","자음자를 두 번 쓰면 소리가 세져요.","소리가 달라지면 뜻도 달라져요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 예사소리 낱말과 된소리 낱말의 짝을 이으세요.","pairs":[{"l":"방","r":"빵"},{"l":"불","r":"뿔"},{"l":"개","r":"깨"}],"explanation":["방 ↔ 빵, 불 ↔ 뿔, 개 ↔ 깨.","자음자를 두 번 쓰면 소리가 세져요.","소리가 달라지면 뜻도 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_basic#8','kor',1,1,'u3','L06','g1_1_kor_u3_L06_basic','lesson_basic','K1-1-u3-C6',2,'mc','auto','「코끼리」의 가운데 글자 「끼」에 들어 있는 자음자는 어느 것인가요?',ARRAY['K1-1-u3-X10','K1-1-u3-X09']::text[],true,'{"seq":8,"concept":"K1-1-u3-C6","difficulty":2,"kind":"mc","stem":"「코끼리」의 가운데 글자 「끼」에 들어 있는 자음자는 어느 것인가요?","options":[{"t":"ㄲ","correct":true},{"t":"ㅋ","mis":"K1-1-u3-X10"},{"t":"ㄱ","mis":"K1-1-u3-X09"}],"explanation":["「끼」 = ㄲ + ㅣ.","ㅋ은 「코」에 있고, ㄱ 하나로는 「기」가 돼요.","글자마다 첫 자음자를 견줘요."],"asset":{"type":"scene","icon":"🐘","text":"코끼리"},"variant_rule":{"alt":[{"stem":"「코뿔소」의 가운데 글자 「뿔」에 들어 있는 첫 자음자는 어느 것인가요?","options":[{"t":"ㅃ","correct":true},{"t":"ㅍ","mis":"K1-1-u3-X10"},{"t":"ㅂ","mis":"K1-1-u3-X09"}],"explanation":["「뿔」 = ㅃ + ㅜ + 받침 ㄹ.","ㅍ이면 「풀」, ㅂ이면 「불」이 돼요.","첫 자음자를 견줘요."],"asset":{"type":"scene","icon":"🦏","text":"코뿔소"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_basic#9','kor',1,1,'u3','L06','g1_1_kor_u3_L06_basic','lesson_basic','K1-1-u3-C6',2,'mc','auto','ㅉ은 어떤 자음자를 두 번 쓴 것인가요?',ARRAY['K1-1-u3-X10','K1-1-u3-X09']::text[],true,'{"seq":9,"kind":"mc","stem":"ㅉ은 어떤 자음자를 두 번 쓴 것인가요?","options":[{"t":"ㅈ","correct":true},{"t":"ㅊ","mis":"K1-1-u3-X10"},{"t":"ㄱ","mis":"K1-1-u3-X09"}],"explanation":["ㅉ은 ㅈ을 두 번 나란히 쓴 자음자예요.","ㅊ은 ㅈ에 획을 하나 더한 자음자라 달라요.","ㅉ은 ㅈ보다 더 센 소리를 내요."],"concept":"K1-1-u3-C6","difficulty":2,"variant_rule":{"twin":{"ask":"shape","mis":{"asp":"X10","other":"X09","one":"X09"},"dir":"split"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_basic#10','kor',1,1,'u3','L06','g1_1_kor_u3_L06_basic','lesson_basic','K1-1-u3-C7',3,'mc','auto','「방」과 「빵」을 견주어 바르게 말한 것은 어느 것인가요?',ARRAY['K1-1-u3-X06','K1-1-u3-X11']::text[],true,'{"seq":10,"concept":"K1-1-u3-C7","difficulty":3,"kind":"mc","stem":"「방」과 「빵」을 견주어 바르게 말한 것은 어느 것인가요?","options":[{"t":"ㅂ이 ㅃ으로 바뀌어 소리가 세지고 뜻도 달라졌어요","correct":true},{"t":"받침이 바뀌어 뜻이 달라졌어요","mis":"K1-1-u3-X06"},{"t":"소리만 세졌을 뿐 뜻은 같아요","mis":"K1-1-u3-X11"}],"explanation":["바뀐 곳은 첫 자음자 ㅂ → ㅃ.","받침 ㅇ은 그대로예요.","소리가 달라지면 뜻도 달라져요."],"variant_rule":{"alt":[{"stem":"「굴」과 「꿀」을 견주어 바르게 말한 것은 어느 것인가요?","options":[{"t":"ㄱ이 ㄲ으로 바뀌어 소리가 세지고 뜻도 달라졌어요","correct":true},{"t":"받침이 바뀌어 뜻이 달라졌어요","mis":"K1-1-u3-X06"},{"t":"소리만 세졌을 뿐 뜻은 같아요","mis":"K1-1-u3-X11"}],"explanation":["바뀐 곳은 첫 자음자 ㄱ → ㄲ.","받침 ㄹ은 그대로예요.","소리가 달라지면 뜻도 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_challenge#1','kor',1,1,'u3','L06','g1_1_kor_u3_L06_challenge','lesson_challenge','K1-1-u3-C7',2,'mc','auto','「쌀」의 ㅆ을 ㅅ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X11','K1-1-u3-X09']::text[],true,'{"seq":1,"kind":"mc","stem":"「쌀」의 ㅆ을 ㅅ으로 바꾸면 어떤 글자가 되나요?","options":[{"t":"살","correct":true},{"t":"쌀","mis":"K1-1-u3-X11"},{"t":"짤","mis":"K1-1-u3-X09"}],"explanation":["「쌀」에서 ㅆ 자리에 ㅅ을 넣으면 「살」이에요.","모음자와 받침은 그대로예요.","ㅅ은 ㅆ보다 여린 소리 — 자음자가 바뀌면 뜻도 달라져요."],"concept":"K1-1-u3-C7","difficulty":2,"variant_rule":{"twin":{"ask":"swap","mis":{"keep":"X11","asp":"X10","other":"X09"},"dir":"down"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_challenge#2','kor',1,1,'u3','L06','g1_1_kor_u3_L06_challenge','lesson_challenge','K1-1-u3-C7',2,'mc','auto','된소리 ㅉ이 들어간 낱말은 어느 것인가요?',ARRAY['K1-1-u3-X12','K1-1-u3-X10']::text[],true,'{"seq":2,"kind":"mc","stem":"된소리 ㅉ이 들어간 낱말은 어느 것인가요?","options":[{"t":"팔찌","correct":true},{"t":"자두","mis":"K1-1-u3-X12"},{"t":"치마","mis":"K1-1-u3-X10"}],"explanation":["「팔찌」에는 ㅉ이 들어 있어요.","ㅈ·ㅊ이 든 낱말과 견주어 읽어 봐요.","소리 내어 읽고, 글자에서 같은 자음자를 두 번 쓴 곳을 찾아요."],"concept":"K1-1-u3-C7","difficulty":2,"variant_rule":{"twin":{"ask":"pick","mis":{"soft":"X12","asp":"X10","other":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_challenge#3','kor',1,1,'u3','L06','g1_1_kor_u3_L06_challenge','lesson_challenge','K1-1-u3-C7',3,'mc','auto','그림을 보고 바르게 쓴 낱말을 고르세요.',ARRAY['K1-1-u3-X13','K1-1-u3-X10']::text[],true,'{"seq":3,"kind":"mc","stem":"그림을 보고 바르게 쓴 낱말을 고르세요.","asset":{"type":"scene","icon":"🦏"},"options":[{"t":"코뿔소","correct":true},{"t":"코불소","mis":"K1-1-u3-X13"},{"t":"코풀소","mis":"K1-1-u3-X10"}],"explanation":["그림은 「코뿔소」예요.","ㅃ을 ㅂ 하나로 쓰면 다른 말이 돼요.","소리 내어 읽으며 센 소리가 나는 자음자를 확인해요."],"concept":"K1-1-u3-C7","difficulty":3,"variant_rule":{"twin":{"ask":"word","mis":{"plain":"X13","asp":"X10","other":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_challenge#4','kor',1,1,'u3','L06','g1_1_kor_u3_L06_challenge','lesson_challenge','K1-1-u3-C6',3,'error','auto','로아가 「빵」을 쓰면서 「방」처럼 ㅂ을 하나만 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u3-X09','K1-1-u3-X10','K1-1-u3-X03']::text[],true,'{"seq":4,"concept":"K1-1-u3-C6","difficulty":3,"kind":"error","stem":"로아가 「빵」을 쓰면서 「방」처럼 ㅂ을 하나만 썼어요. 무엇이 잘못되었나요?","options":[{"t":"ㅂ을 두 번 나란히 써서 ㅃ으로 써야 해요","correct":true,"mis_target":"K1-1-u3-X09"},{"t":"ㅂ 대신 ㅍ을 써야 해요 — 「팡」","mis":"K1-1-u3-X10"},{"t":"받침 ㅇ을 ㄴ으로 바꿔야 해요 — 「반」","mis":"K1-1-u3-X03"}],"explanation":["먹는 「빵」은 ㅃ — 같은 자음자를 두 번.","ㅍ은 다른 자음자이고, 받침은 바르게 썼어요.","된소리 자음자는 두 번 써요."],"variant_rule":{"alt":[{"stem":"지안이가 「딸기」를 쓰면서 「달기」처럼 ㄷ을 하나만 썼어요. 무엇이 잘못되었나요?","options":[{"t":"ㄷ을 두 번 나란히 써서 ㄸ으로 써야 해요","correct":true,"mis_target":"K1-1-u3-X09"},{"t":"ㄷ 대신 ㅌ을 써야 해요 — 「탈기」","mis":"K1-1-u3-X10"},{"t":"받침 ㄹ을 빼야 해요 — 「다기」","mis":"K1-1-u3-X01"}],"explanation":["「딸기」의 첫 자음자는 ㄸ.","ㅌ은 다른 자음자이고, 받침 ㄹ은 있어야 해요.","된소리 자음자는 두 번 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_challenge#5','kor',1,1,'u3','L06','g1_1_kor_u3_L06_challenge','lesson_challenge','K1-1-u3-C7',3,'ox','auto','「가시」는 된소리로 「까시」라고 세게 읽어야 해요.',ARRAY['K1-1-u3-X12']::text[],true,'{"seq":5,"concept":"K1-1-u3-C7","difficulty":3,"kind":"ox","stem":"「가시」는 된소리로 「까시」라고 세게 읽어야 해요.","answer":"X","reason_options":[{"t":"「가시」에는 같은 자음자를 두 번 쓴 곳이 없어 여린 소리로 읽으니까","correct":true},{"t":"모든 낱말은 힘주어 세게 읽어야 하니까","mis":"K1-1-u3-X12"}],"mis":"K1-1-u3-X12","explanation":["「가시」의 ㄱ은 한 번 쓴 자음자예요.","된소리 자음자가 있을 때만 세게 읽어요.","글자를 보고 소리를 정해요."],"variant_rule":{"alt":[{"stem":"「다리」는 「따리」라고 세게 읽어야 해요.","answer":"X","reason_options":[{"t":"「다리」의 ㄷ은 한 번 쓴 자음자라 여린 소리로 읽으니까","correct":true},{"t":"센 소리로 읽어야 또박또박 들리니까","mis":"K1-1-u3-X12"}],"explanation":["「다리」에는 된소리 자음자가 없어요.","세게 읽으면 다른 말처럼 들려요.","글자를 보고 소리를 정해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_challenge#6','kor',1,1,'u3','L06','g1_1_kor_u3_L06_challenge','lesson_challenge','K1-1-u3-C7',3,'mc','auto','된소리가 든 낱말을 따라 길을 찾아요. 갈림길마다 바르게 고른 것은 어느 것인가요?',ARRAY['K1-1-u3-X12']::text[],false,'{"seq":6,"concept":"K1-1-u3-C7","difficulty":3,"kind":"mc","stem":"된소리가 든 낱말을 따라 길을 찾아요. 갈림길마다 바르게 고른 것은 어느 것인가요?","options":[{"t":"까치 → 빵 → 딸기","correct":true},{"t":"가지 → 빵 → 딸기","mis":"K1-1-u3-X12"},{"t":"까치 → 방울 → 다리","mis":"K1-1-u3-X12"}],"explanation":["까치(ㄲ)·빵(ㅃ)·딸기(ㄸ)에 된소리가 있어요.","가지·방울·다리에는 된소리 자음자가 없어요.","갈림길마다 두 번 쓴 자음자를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_challenge#7','kor',1,1,'u3','L06','g1_1_kor_u3_L06_challenge','lesson_challenge','K1-1-u3-C6',3,'mc','auto','같은 자음자를 두 번 나란히 써서 만든 것이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u3-X09']::text[],true,'{"seq":7,"concept":"K1-1-u3-C6","difficulty":3,"kind":"mc","stem":"같은 자음자를 두 번 나란히 써서 만든 것이 아닌 것은 어느 것인가요?","options":[{"t":"ㅋ","correct":true},{"t":"ㄲ","mis":"K1-1-u3-X09"},{"t":"ㅆ","mis":"K1-1-u3-X09"}],"explanation":["ㅋ은 ㄱ에 획을 하나 더한 자음자예요.","ㄲ은 ㄱ을, ㅆ은 ㅅ을 두 번 썼어요.","된소리 자음자는 다섯 개 — ㄲ ㄸ ㅃ ㅆ ㅉ."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 자음자를 두 번 나란히 써서 만든 것이 아닌 것은 어느 것인가요?","options":[{"t":"ㅊ","correct":true},{"t":"ㅉ","mis":"K1-1-u3-X09"},{"t":"ㄸ","mis":"K1-1-u3-X09"}],"explanation":["ㅊ은 ㅈ에 획을 하나 더한 자음자예요.","ㅉ은 ㅈ을, ㄸ은 ㄷ을 두 번 썼어요.","된소리 자음자는 다섯 개."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_challenge#8','kor',1,1,'u3','L06','g1_1_kor_u3_L06_challenge','lesson_challenge','K1-1-u3-C7',4,'essay','teacher','「굴」과 「꿀」을 견주어 무엇이 다르고, 소리와 뜻이 어떻게 달라지는지 말해 보세요.','{}'::text[],false,'{"seq":8,"concept":"K1-1-u3-C7","difficulty":4,"kind":"essay","stem":"「굴」과 「꿀」을 견주어 무엇이 다르고, 소리와 뜻이 어떻게 달라지는지 말해 보세요.","answer_guide":{"answer":"예: 「굴」의 ㄱ이 「꿀」에서는 ㄲ이에요. ㄲ은 소리를 세게 내고, 바다에 사는 굴이 달콤한 꿀로 뜻도 달라져요.","scoring_points":["달라진 곳(ㄱ → ㄲ)을 찾았는가","소리가 세진다고 말했는가","뜻이 달라진다고 말했는가"]},"explanation":["달라진 곳은 첫 자음자.","ㄲ은 센 소리.","소리가 달라지면 뜻도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_challenge#9','kor',1,1,'u3','L06','g1_1_kor_u3_L06_challenge','lesson_challenge','K1-1-u3-C7',4,'mc','auto','한 글자씩 바꾸어 말 잇기를 해요. 「불 → 뿔 → 풀」에서 자음자는 어떻게 바뀌었나요?',ARRAY['K1-1-u3-X10','K1-1-u3-X06']::text[],true,'{"seq":9,"concept":"K1-1-u3-C7","difficulty":4,"kind":"mc","stem":"한 글자씩 바꾸어 말 잇기를 해요. 「불 → 뿔 → 풀」에서 자음자는 어떻게 바뀌었나요?","options":[{"t":"ㅂ → ㅃ(같은 자음자 두 번) → ㅍ(획을 더한 자음자)","correct":true},{"t":"ㅂ → ㅃ(획을 더한 자음자) → ㅍ(같은 자음자 두 번)","mis":"K1-1-u3-X10"},{"t":"받침 ㄹ이 바뀌었어요","mis":"K1-1-u3-X06"}],"explanation":["뿔은 ㅂ을 두 번 쓴 ㅃ, 풀은 획을 더한 ㅍ.","받침 ㄹ은 세 낱말 모두 그대로예요.","ㅃ과 ㅍ은 모양도 소리도 달라요."],"variant_rule":{"alt":[{"stem":"한 글자씩 바꾸어 말 잇기를 해요. 「달 → 딸 → 탈」에서 자음자는 어떻게 바뀌었나요?","options":[{"t":"ㄷ → ㄸ(같은 자음자 두 번) → ㅌ(획을 더한 자음자)","correct":true},{"t":"ㄷ → ㄸ(획을 더한 자음자) → ㅌ(같은 자음자 두 번)","mis":"K1-1-u3-X10"},{"t":"받침 ㄹ이 바뀌었어요","mis":"K1-1-u3-X06"}],"explanation":["딸은 ㄷ을 두 번 쓴 ㄸ, 탈은 획을 더한 ㅌ.","받침 ㄹ은 그대로예요.","ㄸ과 ㅌ은 모양도 소리도 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L06_challenge#10','kor',1,1,'u3','L06','g1_1_kor_u3_L06_challenge','lesson_challenge','K1-1-u3-C6',4,'mc','auto','세 낱말에 모두 들어 있는 된소리 자음자는 어느 것인가요?',ARRAY['K1-1-u3-X15','K1-1-u3-X10']::text[],true,'{"seq":10,"concept":"K1-1-u3-C6","difficulty":4,"kind":"mc","stem":"세 낱말에 모두 들어 있는 된소리 자음자는 어느 것인가요?","options":[{"t":"ㅉ","correct":true},{"t":"ㅃ","mis":"K1-1-u3-X15"},{"t":"ㅊ","mis":"K1-1-u3-X10"}],"explanation":["찐(ㅉ)·짜(ㅉ)·찌(ㅉ) — 세 낱말 모두 ㅉ.","ㅃ은 「찐빵」에만 있고, ㅊ은 없어요.","낱말마다 글자를 하나하나 짚어요."],"asset":{"type":"passage","lines":["찐빵 · 짜장면 · 팔찌"]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 세 낱말에 모두 들어 있는 된소리 자음자는 어느 것인가요?","options":[{"t":"ㄸ","correct":true},{"t":"ㄲ","mis":"K1-1-u3-X15"},{"t":"ㅌ","mis":"K1-1-u3-X10"}],"explanation":["딸(ㄸ)·땅(ㄸ)·떡(ㄸ) — 세 낱말 모두 ㄸ.","ㄲ은 하나도 없고, ㅌ은 된소리가 아니에요.","글자를 하나하나 짚어요."],"asset":{"type":"passage","lines":["딸기 · 땅콩 · 떡"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_basic#1','kor',1,1,'u3','L08','g1_1_kor_u3_L08_basic','lesson_basic','K1-1-u3-C8',1,'mc','auto','「깡충깡충」 뛰는 모습에 어울리는 동물은 어느 것인가요?',ARRAY['K1-1-u3-X14']::text[],true,'{"seq":1,"concept":"K1-1-u3-C8","difficulty":1,"kind":"mc","stem":"「깡충깡충」 뛰는 모습에 어울리는 동물은 어느 것인가요?","options":[{"t":"토끼","correct":true},{"t":"거북","mis":"K1-1-u3-X14"},{"t":"달팽이","mis":"K1-1-u3-X14"}],"explanation":["토끼는 긴 다리로 깡충깡충 뛰어요.","거북·달팽이는 느릿느릿 기어가요.","흉내 내는 말을 몸으로 따라 해 봐요."],"variant_rule":{"alt":[{"stem":"「어슬렁어슬렁」 걷는 모습에 어울리는 동물은 어느 것인가요?","options":[{"t":"호랑이","correct":true},{"t":"참새","mis":"K1-1-u3-X14"},{"t":"토끼","mis":"K1-1-u3-X14"}],"explanation":["호랑이는 어슬렁어슬렁 천천히 걸어요.","참새는 포르르, 토끼는 깡충깡충 움직여요.","흉내 내는 말을 몸으로 따라 해 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_basic#2','kor',1,1,'u3','L08','g1_1_kor_u3_L08_basic','lesson_basic','K1-1-u3-C8',1,'mc','auto','「뒤뚱뒤뚱」 걷는 모습에 어울리는 동물은 어느 것인가요?',ARRAY['K1-1-u3-X14']::text[],true,'{"seq":2,"concept":"K1-1-u3-C8","difficulty":1,"kind":"mc","stem":"「뒤뚱뒤뚱」 걷는 모습에 어울리는 동물은 어느 것인가요?","options":[{"t":"오리","correct":true},{"t":"호랑이","mis":"K1-1-u3-X14"},{"t":"토끼","mis":"K1-1-u3-X14"}],"explanation":["오리는 몸을 이리저리 흔들며 뒤뚱뒤뚱 걸어요.","호랑이는 어슬렁어슬렁, 토끼는 깡충깡충.","모습을 떠올리며 읽어요."],"variant_rule":{"alt":[{"stem":"「엉금엉금」 기어가는 모습에 어울리는 동물은 어느 것인가요?","options":[{"t":"거북","correct":true},{"t":"토끼","mis":"K1-1-u3-X14"},{"t":"말","mis":"K1-1-u3-X14"}],"explanation":["거북은 엉금엉금 천천히 기어요.","토끼는 깡충깡충, 말은 다그닥다그닥 달려요.","모습을 떠올리며 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_basic#3','kor',1,1,'u3','L08','g1_1_kor_u3_L08_basic','lesson_basic','K1-1-u3-C8',1,'mc','auto','받침을 빠뜨리지 않고 바르게 쓴 낱말을 고르세요.',ARRAY['K1-1-u3-X01']::text[],true,'{"seq":3,"concept":"K1-1-u3-C8","difficulty":1,"kind":"mc","stem":"받침을 빠뜨리지 않고 바르게 쓴 낱말을 고르세요.","options":[{"t":"책상","correct":true},{"t":"책사","mis":"K1-1-u3-X01"},{"t":"채상","mis":"K1-1-u3-X01"}],"explanation":["「책상」은 책(ㄱ)·상(ㅇ) 두 글자에 받침이 있어요.","「책사」·「채상」은 받침 하나를 빠뜨렸어요.","글자마다 받침을 챙겨요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받침을 빠뜨리지 않고 바르게 쓴 낱말을 고르세요.","options":[{"t":"김밥","correct":true},{"t":"기밥","mis":"K1-1-u3-X01"},{"t":"김바","mis":"K1-1-u3-X01"}],"explanation":["「김밥」은 김(ㅁ)·밥(ㅂ) 두 글자에 받침이 있어요.","「기밥」·「김바」는 받침 하나를 빠뜨렸어요.","글자마다 받침을 챙겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_basic#4','kor',1,1,'u3','L08','g1_1_kor_u3_L08_basic','lesson_basic','K1-1-u3-C8',1,'mc','auto','해가 뜨겁게 내리쬐는 모습에 어울리는 말은 어느 것인가요?',ARRAY['K1-1-u3-X14']::text[],true,'{"seq":4,"concept":"K1-1-u3-C8","difficulty":1,"kind":"mc","stem":"해가 뜨겁게 내리쬐는 모습에 어울리는 말은 어느 것인가요?","options":[{"t":"쨍쨍","correct":true},{"t":"주룩주룩","mis":"K1-1-u3-X14"},{"t":"살랑살랑","mis":"K1-1-u3-X14"}],"explanation":["뜨거운 해는 「쨍쨍」.","주룩주룩은 비, 살랑살랑은 바람에 어울려요.","모습을 떠올리며 골라요."],"variant_rule":{"alt":[{"stem":"비가 많이 쏟아지는 모습에 어울리는 말은 어느 것인가요?","options":[{"t":"주룩주룩","correct":true},{"t":"쨍쨍","mis":"K1-1-u3-X14"},{"t":"반짝반짝","mis":"K1-1-u3-X14"}],"explanation":["비는 「주룩주룩」.","쨍쨍은 해, 반짝반짝은 별에 어울려요.","모습을 떠올리며 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_basic#5','kor',1,1,'u3','L08','g1_1_kor_u3_L08_basic','lesson_basic','K1-1-u3-C8',2,'match','auto','동물과 움직이는 모습을 흉내 내는 말을 이으세요.','{}'::text[],true,'{"seq":5,"concept":"K1-1-u3-C8","difficulty":2,"kind":"match","stem":"동물과 움직이는 모습을 흉내 내는 말을 이으세요.","pairs":[{"l":"토끼","r":"깡충깡충"},{"l":"호랑이","r":"어슬렁어슬렁"},{"l":"거북","r":"엉금엉금"}],"mis":"K1-1-u3-X14","explanation":["토끼-깡충깡충, 호랑이-어슬렁어슬렁, 거북-엉금엉금.","움직임을 떠올리면 짝이 보여요.","소리 내어 읽으며 몸으로 따라 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 동물과 움직이는 모습을 흉내 내는 말을 이으세요.","pairs":[{"l":"오리","r":"뒤뚱뒤뚱"},{"l":"토끼","r":"깡충깡충"},{"l":"달팽이","r":"느릿느릿"}],"explanation":["오리-뒤뚱뒤뚱, 토끼-깡충깡충, 달팽이-느릿느릿.","움직임을 떠올리면 짝이 보여요.","몸으로 따라 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_basic#6','kor',1,1,'u3','L08','g1_1_kor_u3_L08_basic','lesson_basic','K1-1-u3-C7',2,'mc','auto','그림을 보고 바르게 쓴 낱말을 고르세요.',ARRAY['K1-1-u3-X13','K1-1-u3-X09']::text[],true,'{"seq":6,"kind":"mc","stem":"그림을 보고 바르게 쓴 낱말을 고르세요.","asset":{"type":"scene","icon":"🍚"},"options":[{"t":"쌀","correct":true},{"t":"살","mis":"K1-1-u3-X13"},{"t":"짤","mis":"K1-1-u3-X09"}],"explanation":["그림은 「쌀」이에요.","ㅆ을 ㅅ 하나로 쓰면 다른 말이 돼요.","소리 내어 읽으며 센 소리가 나는 자음자를 확인해요."],"concept":"K1-1-u3-C7","difficulty":2,"variant_rule":{"twin":{"ask":"word","mis":{"plain":"X13","asp":"X10","other":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_basic#7','kor',1,1,'u3','L08','g1_1_kor_u3_L08_basic','lesson_basic','K1-1-u3-C8',2,'mc','auto','소리 내어 읽기를 잘하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u3-X15']::text[],false,'{"seq":7,"concept":"K1-1-u3-C8","difficulty":2,"kind":"mc","stem":"소리 내어 읽기를 잘하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"받침과 센 소리까지 또박또박 읽어요","correct":true},{"t":"빨리 읽고 얼른 끝내요","mis":"K1-1-u3-X15"},{"t":"틀릴까 봐 작게 웅얼거려요","mis":"K1-1-u3-X15"}],"explanation":["받침·센 소리까지 정확하게 읽는 것이 먼저예요.","빨리·작게 읽으면 낱말이 뭉개져요.","자신 있게, 또박또박."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_basic#8','kor',1,1,'u3','L08','g1_1_kor_u3_L08_basic','lesson_basic','K1-1-u3-C8',2,'mc','auto','받침이 있거나 된소리가 든 낱말만 모은 것은 어느 것인가요?',ARRAY['K1-1-u3-X01']::text[],true,'{"seq":8,"concept":"K1-1-u3-C8","difficulty":2,"kind":"mc","stem":"받침이 있거나 된소리가 든 낱말만 모은 것은 어느 것인가요?","options":[{"t":"빵 · 떡 · 까치","correct":true},{"t":"빵 · 소 · 까치","mis":"K1-1-u3-X01"},{"t":"바다 · 떡 · 하마","mis":"K1-1-u3-X01"}],"explanation":["빵(ㅃ·ㅇ)·떡(ㄸ·ㄱ)·까치(ㄲ)예요.","「소」·「바다」·「하마」에는 받침도 된소리도 없어요.","낱말마다 아래쪽과 첫 자음자를 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받침이 있거나 된소리가 든 낱말만 모은 것은 어느 것인가요?","options":[{"t":"꼬리 · 씨앗 · 새싹","correct":true},{"t":"꼬리 · 새 · 씨앗","mis":"K1-1-u3-X01"},{"t":"하마 · 씨앗 · 새싹","mis":"K1-1-u3-X01"}],"explanation":["꼬리(ㄲ)·씨앗(ㅆ·ㅅ)·새싹(ㅆ·ㄱ)이에요.","「새」·「하마」에는 받침도 된소리도 없어요.","낱말마다 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_basic#9','kor',1,1,'u3','L08','g1_1_kor_u3_L08_basic','lesson_basic','K1-1-u3-C8',2,'ox','auto','「꼬리」에는 받침은 없지만 된소리 자음자가 들어 있어요.',ARRAY['K1-1-u3-X06']::text[],true,'{"seq":9,"concept":"K1-1-u3-C8","difficulty":2,"kind":"ox","stem":"「꼬리」에는 받침은 없지만 된소리 자음자가 들어 있어요.","answer":"O","reason_options":[{"t":"「꼬」의 첫 자음자가 ㄲ이고 아래쪽은 비어 있으니까","correct":true},{"t":"ㄲ은 받침이니까","mis":"K1-1-u3-X06"}],"mis":"K1-1-u3-X06","explanation":["「꼬」 = ㄲ + ㅗ, 아래쪽은 비어 있어요.","ㄲ은 위쪽 첫 자음자 자리에 있어요.","받침과 된소리는 자리가 달라요."],"variant_rule":{"alt":[{"stem":"「딸기」의 「딸」에는 된소리 자음자와 받침이 함께 있어요.","answer":"O","reason_options":[{"t":"첫 자음자가 ㄸ이고 아래쪽에 받침 ㄹ이 있으니까","correct":true},{"t":"ㄸ과 ㄹ은 둘 다 받침이니까","mis":"K1-1-u3-X06"}],"explanation":["「딸」 = ㄸ + ㅏ + 받침 ㄹ.","ㄸ은 첫 자음자, ㄹ은 받침이에요.","자리를 보고 가려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_basic#10','kor',1,1,'u3','L08','g1_1_kor_u3_L08_basic','lesson_basic','K1-1-u3-C8',3,'mc','auto','움직이는 모습을 흉내 내는 말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u3-X14']::text[],true,'{"seq":10,"concept":"K1-1-u3-C8","difficulty":3,"kind":"mc","stem":"움직이는 모습을 흉내 내는 말이 아닌 것은 어느 것인가요?","options":[{"t":"멍멍","correct":true},{"t":"엉금엉금","mis":"K1-1-u3-X14"},{"t":"뒤뚱뒤뚱","mis":"K1-1-u3-X14"}],"explanation":["「멍멍」은 강아지가 짖는 소리를 흉내 낸 말이에요.","엉금엉금·뒤뚱뒤뚱은 움직이는 모습이에요.","소리를 흉내 낸 말과 모습을 흉내 낸 말을 가려요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 움직이는 모습을 흉내 내는 말이 아닌 것은 어느 것인가요?","options":[{"t":"꽥꽥","correct":true},{"t":"깡충깡충","mis":"K1-1-u3-X14"},{"t":"어슬렁어슬렁","mis":"K1-1-u3-X14"}],"explanation":["「꽥꽥」은 오리가 우는 소리를 흉내 낸 말이에요.","깡충깡충·어슬렁어슬렁은 움직이는 모습이에요.","소리와 모습을 가려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_challenge#1','kor',1,1,'u3','L08','g1_1_kor_u3_L08_challenge','lesson_challenge','K1-1-u3-C7',2,'mc','auto','된소리 ㄸ이 들어간 낱말은 어느 것인가요?',ARRAY['K1-1-u3-X12','K1-1-u3-X10']::text[],true,'{"seq":1,"kind":"mc","stem":"된소리 ㄸ이 들어간 낱말은 어느 것인가요?","options":[{"t":"땅콩","correct":true},{"t":"두부","mis":"K1-1-u3-X12"},{"t":"타조","mis":"K1-1-u3-X10"}],"explanation":["「땅콩」에는 ㄸ이 들어 있어요.","ㄷ·ㅌ이 든 낱말과 견주어 읽어 봐요.","소리 내어 읽고, 글자에서 같은 자음자를 두 번 쓴 곳을 찾아요."],"concept":"K1-1-u3-C7","difficulty":2,"variant_rule":{"twin":{"ask":"pick","mis":{"soft":"X12","asp":"X10","other":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_challenge#2','kor',1,1,'u3','L08','g1_1_kor_u3_L08_challenge','lesson_challenge','K1-1-u3-C8',2,'mc','auto','「엉금엉금」 기어가는 모습에 어울리는 동물은 어느 것인가요?',ARRAY['K1-1-u3-X14']::text[],false,'{"seq":2,"concept":"K1-1-u3-C8","difficulty":2,"kind":"mc","stem":"「엉금엉금」 기어가는 모습에 어울리는 동물은 어느 것인가요?","options":[{"t":"거북","correct":true},{"t":"토끼","mis":"K1-1-u3-X14"},{"t":"호랑이","mis":"K1-1-u3-X14"}],"explanation":["거북은 엉금엉금 천천히 기어요.","토끼는 깡충깡충, 호랑이는 어슬렁어슬렁.","모습을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_challenge#3','kor',1,1,'u3','L08','g1_1_kor_u3_L08_challenge','lesson_challenge','K1-1-u3-C8',3,'mc','auto','구름 모양을 보고 떠오른 동물을 읽어요. 「긴 귀가 쫑긋, 깡충 뛰는 동물」은 어느 것인가요?',ARRAY['K1-1-u3-X13','K1-1-u3-X14']::text[],true,'{"seq":3,"concept":"K1-1-u3-C8","difficulty":3,"kind":"mc","stem":"구름 모양을 보고 떠오른 동물을 읽어요. 「긴 귀가 쫑긋, 깡충 뛰는 동물」은 어느 것인가요?","options":[{"t":"토끼","correct":true},{"t":"토기","mis":"K1-1-u3-X13"},{"t":"호랑이","mis":"K1-1-u3-X14"}],"explanation":["긴 귀에 깡충 뛰는 동물은 「토끼」.","「토기」는 ㄲ을 ㄱ으로 읽은 것이고, 호랑이는 어슬렁어슬렁 걸어요.","된소리까지 또박또박 읽어요."],"variant_rule":{"alt":[{"stem":"구름 모양을 보고 떠오른 동물을 읽어요. 「코가 길고 귀가 커다란 동물」은 어느 것인가요?","options":[{"t":"코끼리","correct":true},{"t":"코기리","mis":"K1-1-u3-X13"},{"t":"기린","mis":"K1-1-u3-X14"}],"explanation":["긴 코에 큰 귀는 「코끼리」.","「코기리」는 ㄲ을 ㄱ으로 읽은 것이고, 기린은 목이 길어요.","된소리까지 또박또박."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_challenge#4','kor',1,1,'u3','L08','g1_1_kor_u3_L08_challenge','lesson_challenge','K1-1-u3-C8',3,'error','auto','민호가 「코뿔소」를 「코불소」라고 읽었어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u3-X13','K1-1-u3-X01','K1-1-u3-X10']::text[],true,'{"seq":4,"concept":"K1-1-u3-C8","difficulty":3,"kind":"error","stem":"민호가 「코뿔소」를 「코불소」라고 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"된소리 ㅃ을 여린 소리 ㅂ으로 읽었어요","correct":true,"mis_target":"K1-1-u3-X13"},{"t":"받침 ㄹ을 빼고 읽었어요","mis":"K1-1-u3-X01"},{"t":"ㅃ을 ㅍ으로 읽었어요","mis":"K1-1-u3-X10"}],"explanation":["「뿔」은 ㅃ — 세게 읽어요.","받침 ㄹ은 바르게 읽었고, ㅍ으로 읽지도 않았어요.","된소리 자음자는 센 소리로."],"asset":{"type":"scene","icon":"🦏","text":"코뿔소"},"variant_rule":{"alt":[{"stem":"하린이가 「딸기」를 「달기」라고 읽었어요. 무엇이 잘못되었나요?","options":[{"t":"된소리 ㄸ을 여린 소리 ㄷ으로 읽었어요","correct":true,"mis_target":"K1-1-u3-X13"},{"t":"받침 ㄹ을 빼고 읽었어요","mis":"K1-1-u3-X01"},{"t":"ㄸ을 ㅌ으로 읽었어요","mis":"K1-1-u3-X10"}],"explanation":["「딸」은 ㄸ — 세게 읽어요.","받침 ㄹ은 바르게 읽었어요.","된소리 자음자는 센 소리로."],"asset":{"type":"scene","icon":"🍓","text":"딸기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_challenge#5','kor',1,1,'u3','L08','g1_1_kor_u3_L08_challenge','lesson_challenge','K1-1-u3-C8',3,'mc','auto','「쨍쨍」과 「주룩주룩」을 넣어 날씨를 바르게 말한 것은 어느 것인가요?',ARRAY['K1-1-u3-X14']::text[],true,'{"seq":5,"concept":"K1-1-u3-C8","difficulty":3,"kind":"mc","stem":"「쨍쨍」과 「주룩주룩」을 넣어 날씨를 바르게 말한 것은 어느 것인가요?","options":[{"t":"해가 쨍쨍 비쳐요. 비가 주룩주룩 내려요.","correct":true},{"t":"해가 주룩주룩 비쳐요. 비가 쨍쨍 내려요.","mis":"K1-1-u3-X14"},{"t":"해가 쨍쨍 비쳐요. 비가 쨍쨍 내려요.","mis":"K1-1-u3-X14"}],"explanation":["해는 쨍쨍, 비는 주룩주룩.","흉내 내는 말을 바꾸어 쓰면 모습이 맞지 않아요.","모습을 떠올리며 넣어요."],"variant_rule":{"alt":[{"stem":"「반짝반짝」과 「살랑살랑」을 넣어 바르게 말한 것은 어느 것인가요?","options":[{"t":"별이 반짝반짝 빛나요. 바람이 살랑살랑 불어요.","correct":true},{"t":"별이 살랑살랑 빛나요. 바람이 반짝반짝 불어요.","mis":"K1-1-u3-X14"},{"t":"별이 반짝반짝 빛나요. 바람이 반짝반짝 불어요.","mis":"K1-1-u3-X14"}],"explanation":["별은 반짝반짝, 바람은 살랑살랑.","바꾸어 쓰면 모습이 맞지 않아요.","모습을 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_challenge#6','kor',1,1,'u3','L08','g1_1_kor_u3_L08_challenge','lesson_challenge','K1-1-u3-C8',3,'ox','auto','낱말은 빨리 읽을수록 잘 읽는 거예요.',ARRAY['K1-1-u3-X15']::text[],false,'{"seq":6,"concept":"K1-1-u3-C8","difficulty":3,"kind":"ox","stem":"낱말은 빨리 읽을수록 잘 읽는 거예요.","answer":"X","reason_options":[{"t":"받침과 센 소리까지 정확하게 읽는 것이 먼저이니까","correct":true},{"t":"빨리 읽어야 친구들이 좋아하니까","mis":"K1-1-u3-X15"}],"mis":"K1-1-u3-X15","explanation":["빨리 읽으면 받침·센 소리를 놓치기 쉬워요.","정확하게 읽는 것이 먼저예요.","또박또박, 자신 있게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_challenge#7','kor',1,1,'u3','L08','g1_1_kor_u3_L08_challenge','lesson_challenge','K1-1-u3-C8',3,'mc','auto','「깡충깡충」을 소리 내어 읽을 때 세게 읽어야 하는 자음자는 어느 것인가요?',ARRAY['K1-1-u3-X10','K1-1-u3-X15']::text[],true,'{"seq":7,"concept":"K1-1-u3-C8","difficulty":3,"kind":"mc","stem":"「깡충깡충」을 소리 내어 읽을 때 세게 읽어야 하는 자음자는 어느 것인가요?","options":[{"t":"ㄲ","correct":true},{"t":"ㅊ","mis":"K1-1-u3-X10"},{"t":"ㅇ","mis":"K1-1-u3-X15"}],"explanation":["「깡」의 첫 자음자 ㄲ은 된소리예요.","ㅊ은 「충」의 첫 자음자, ㅇ은 받침이에요.","같은 자음자를 두 번 쓴 곳을 세게."],"variant_rule":{"alt":[{"stem":"「뒤뚱뒤뚱」을 소리 내어 읽을 때 세게 읽어야 하는 자음자는 어느 것인가요?","options":[{"t":"ㄸ","correct":true},{"t":"ㄷ","mis":"K1-1-u3-X09"},{"t":"ㅇ","mis":"K1-1-u3-X15"}],"explanation":["「뚱」의 첫 자음자 ㄸ은 된소리예요.","「뒤」의 ㄷ은 한 번 쓴 자음자, ㅇ은 받침이에요.","두 번 쓴 곳을 세게."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_challenge#8','kor',1,1,'u3','L08','g1_1_kor_u3_L08_challenge','lesson_challenge','K1-1-u3-C8',4,'mc','auto','다음 문장에서 된소리 자음자가 든 낱말은 모두 몇 개인가요?',ARRAY['K1-1-u3-X15']::text[],true,'{"seq":8,"concept":"K1-1-u3-C8","difficulty":4,"kind":"mc","stem":"다음 문장에서 된소리 자음자가 든 낱말은 모두 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"3개","mis":"K1-1-u3-X15"},{"t":"2개","mis":"K1-1-u3-X15"}],"explanation":["토끼·깡충깡충·뛰어·딸기밭으로 — 네 낱말이에요.","「가요」에는 된소리가 없어요.","낱말마다 글자를 하나하나 짚어요."],"asset":{"type":"passage","lines":["토끼가 깡충깡충 뛰어 딸기밭으로 가요."]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 문장에서 된소리 자음자가 든 낱말은 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"K1-1-u3-X15"},{"t":"4개","mis":"K1-1-u3-X15"}],"explanation":["까치가·빵과·떡을 — 세 낱말이에요.","「아침에」·「먹어요」에는 된소리가 없어요.","낱말마다 짚어요."],"asset":{"type":"passage","lines":["아침에 까치가 빵과 떡을 먹어요."]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_challenge#9','kor',1,1,'u3','L08','g1_1_kor_u3_L08_challenge','lesson_challenge','K1-1-u3-C8',4,'mc','auto','「살」과 「쌀」을 넣은 문장에서 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u3-X13','K1-1-u3-X11']::text[],false,'{"seq":9,"concept":"K1-1-u3-C8","difficulty":4,"kind":"mc","stem":"「살」과 「쌀」을 넣은 문장에서 바르게 쓴 것은 어느 것인가요?","options":[{"t":"쌀로 밥을 지어요. 넘어져서 살이 까졌어요.","correct":true},{"t":"살로 밥을 지어요. 넘어져서 쌀이 까졌어요.","mis":"K1-1-u3-X13"},{"t":"쌀로 밥을 지어요. 넘어져서 쌀이 까졌어요.","mis":"K1-1-u3-X11"}],"explanation":["밥을 짓는 것은 「쌀」, 몸의 살갗은 「살」.","두 낱말은 소리도 뜻도 달라요.","뜻을 떠올리며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L08_challenge#10','kor',1,1,'u3','L08','g1_1_kor_u3_L08_challenge','lesson_challenge','K1-1-u3-C8',4,'essay','teacher','좋아하는 동물 하나를 골라 「○○는 ~하게 움직여요.」처럼 흉내 내는 말을 넣어 말하고, 그 말이 어울리는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u3-C8","difficulty":4,"kind":"essay","stem":"좋아하는 동물 하나를 골라 「○○는 ~하게 움직여요.」처럼 흉내 내는 말을 넣어 말하고, 그 말이 어울리는 까닭을 써 보세요.","answer_guide":{"answer":"예: 「오리는 뒤뚱뒤뚱 움직여요.」 — 오리는 다리가 짧아 몸을 흔들며 걷기 때문이에요.","scoring_points":["동물과 흉내 내는 말을 넣어 한 문장으로 말했는가","흉내 내는 말이 그 동물의 움직임과 어울리는가","어울리는 까닭을 썼는가"]},"explanation":["동물 + 흉내 내는 말.","움직임과 어울려야 해요.","까닭도 함께."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_basic#1','kor',1,1,'u3','L10','g1_1_kor_u3_L10_basic','lesson_basic','K1-1-u3-C9',1,'mc','auto','교실 물건 가운데 받침이 있는 낱말은 어느 것인가요?',ARRAY['K1-1-u3-X01']::text[],true,'{"seq":1,"concept":"K1-1-u3-C9","difficulty":1,"kind":"mc","stem":"교실 물건 가운데 받침이 있는 낱말은 어느 것인가요?","options":[{"t":"책상","correct":true},{"t":"의자","mis":"K1-1-u3-X01"},{"t":"가위","mis":"K1-1-u3-X01"}],"explanation":["「책상」은 책(ㄱ)·상(ㅇ)에 받침이 있어요.","「의자」·「가위」는 아래쪽이 비어 있어요.","교실을 둘러보며 받침 낱말을 찾아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 교실 물건 가운데 받침이 있는 낱말은 어느 것인가요?","options":[{"t":"칠판","correct":true},{"t":"지우개","mis":"K1-1-u3-X01"},{"t":"자","mis":"K1-1-u3-X01"}],"explanation":["「칠판」은 칠(ㄹ)·판(ㄴ)에 받침이 있어요.","「지우개」·「자」는 아래쪽이 비어 있어요.","받침 낱말을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_basic#2','kor',1,1,'u3','L10','g1_1_kor_u3_L10_basic','lesson_basic','K1-1-u3-C9',1,'mc','auto','친구가 쓴 낱말 가운데 받침을 빠뜨리지 않고 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-1-u3-X01']::text[],true,'{"seq":2,"concept":"K1-1-u3-C9","difficulty":1,"kind":"mc","stem":"친구가 쓴 낱말 가운데 받침을 빠뜨리지 않고 바르게 쓴 것은 어느 것인가요?","options":[{"t":"연필","correct":true},{"t":"연피","mis":"K1-1-u3-X01"},{"t":"여필","mis":"K1-1-u3-X01"}],"explanation":["「연필」은 연(ㄴ)·필(ㄹ) 두 받침을 다 썼어요.","「연피」·「여필」은 받침 하나를 빠뜨렸어요.","친구 낱말도 받침을 살펴요."],"asset":{"type":"scene","icon":"✏️"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구가 쓴 낱말 가운데 받침을 빠뜨리지 않고 바르게 쓴 것은 어느 것인가요?","options":[{"t":"공책","correct":true},{"t":"고책","mis":"K1-1-u3-X01"},{"t":"공채","mis":"K1-1-u3-X01"}],"explanation":["「공책」은 공(ㅇ)·책(ㄱ) 두 받침을 다 썼어요.","「고책」·「공채」는 받침 하나를 빠뜨렸어요.","친구 낱말도 살펴요."],"asset":{"type":"scene","icon":"📒"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_basic#3','kor',1,1,'u3','L10','g1_1_kor_u3_L10_basic','lesson_basic','K1-1-u3-C7',1,'mc','auto','된소리 ㅃ이 들어간 낱말은 어느 것인가요?',ARRAY['K1-1-u3-X12','K1-1-u3-X10']::text[],true,'{"seq":3,"kind":"mc","stem":"된소리 ㅃ이 들어간 낱말은 어느 것인가요?","options":[{"t":"빵","correct":true},{"t":"바지","mis":"K1-1-u3-X12"},{"t":"포도","mis":"K1-1-u3-X10"}],"explanation":["「빵」에는 ㅃ이 들어 있어요.","ㅂ·ㅍ이 든 낱말과 견주어 읽어 봐요.","소리 내어 읽고, 글자에서 같은 자음자를 두 번 쓴 곳을 찾아요."],"concept":"K1-1-u3-C7","difficulty":1,"variant_rule":{"twin":{"ask":"pick","mis":{"soft":"X12","asp":"X10","other":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_basic#4','kor',1,1,'u3','L10','g1_1_kor_u3_L10_basic','lesson_basic','K1-1-u3-C9',1,'ox','auto','「곰」과 「봄」은 한 자음자만 다르니 같은 뜻이에요.',ARRAY['K1-1-u3-X16']::text[],true,'{"seq":4,"concept":"K1-1-u3-C9","difficulty":1,"kind":"ox","stem":"「곰」과 「봄」은 한 자음자만 다르니 같은 뜻이에요.","answer":"X","reason_options":[{"t":"첫 자음자 하나만 바뀌어도 다른 낱말이 되니까","correct":true},{"t":"글자 모양이 비슷하면 같은 낱말이니까","mis":"K1-1-u3-X16"}],"mis":"K1-1-u3-X16","explanation":["「곰」은 동물, 「봄」은 계절이에요.","낱자 하나만 달라도 뜻이 완전히 달라져요.","바뀐 낱자를 찾아 견줘요."],"variant_rule":{"alt":[{"stem":"「말」과 「물」은 모음자 하나만 다르니 같은 뜻이에요.","answer":"X","reason_options":[{"t":"모음자 하나만 바뀌어도 다른 낱말이 되니까","correct":true},{"t":"글자 모양이 비슷하면 같은 낱말이니까","mis":"K1-1-u3-X16"}],"explanation":["「말」은 동물, 「물」은 마시는 것이에요.","낱자 하나만 달라도 뜻이 달라져요.","바뀐 낱자를 찾아 견줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_basic#5','kor',1,1,'u3','L10','g1_1_kor_u3_L10_basic','lesson_basic','K1-1-u3-C9',2,'mc','auto','「강」의 받침 ㅇ을 ㅁ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X06','K1-1-u3-X16']::text[],true,'{"seq":5,"kind":"mc","stem":"「강」의 받침 ㅇ을 ㅁ으로 바꾸면 어떤 글자가 되나요?","asset":{"type":"bat","s":"강","eq":false},"options":[{"t":"감","correct":true},{"t":"망","mis":"K1-1-u3-X06"},{"t":"강","mis":"K1-1-u3-X16"}],"explanation":["「강」에서 받침 ㅇ 자리에 ㅁ을 넣으면 「감」이에요.","맨 앞 자음자 ㄱ과 모음자 ㅏ는 그대로예요.","받침이 바뀌면 글자도 소리도 뜻도 달라져요."],"concept":"K1-1-u3-C9","difficulty":2,"variant_rule":{"bat":{"ask":"swap","mis":{"role":"X06","keep":"X16"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_basic#6','kor',1,1,'u3','L10','g1_1_kor_u3_L10_basic','lesson_basic','K1-1-u3-C9',2,'mc','auto','「말」에서 한 낱자를 바꾸어 「물」이 되었어요. 무엇이 바뀌었나요?',ARRAY['K1-1-u3-X06']::text[],true,'{"seq":6,"concept":"K1-1-u3-C9","difficulty":2,"kind":"mc","stem":"「말」에서 한 낱자를 바꾸어 「물」이 되었어요. 무엇이 바뀌었나요?","options":[{"t":"모음자 ㅏ가 ㅜ로","correct":true},{"t":"첫 자음자 ㅁ이 ㅂ으로","mis":"K1-1-u3-X06"},{"t":"받침 ㄹ이 ㄴ으로","mis":"K1-1-u3-X06"}],"explanation":["말 → 물: 가운데 모음자만 바뀌었어요.","첫 자음자 ㅁ과 받침 ㄹ은 그대로예요.","두 낱말을 위아래로 놓고 견줘요."],"variant_rule":{"alt":[{"stem":"「곰」에서 한 낱자를 바꾸어 「봄」이 되었어요. 무엇이 바뀌었나요?","options":[{"t":"첫 자음자 ㄱ이 ㅂ으로","correct":true},{"t":"모음자 ㅗ가 ㅜ로","mis":"K1-1-u3-X06"},{"t":"받침 ㅁ이 ㅂ으로","mis":"K1-1-u3-X06"}],"explanation":["곰 → 봄: 첫 자음자만 바뀌었어요.","모음자 ㅗ와 받침 ㅁ은 그대로예요.","위아래로 놓고 견줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_basic#7','kor',1,1,'u3','L10','g1_1_kor_u3_L10_basic','lesson_basic','K1-1-u3-C9',2,'mc','auto','가족을 부르는 말 가운데 받침이 있는 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K1-1-u3-X01']::text[],true,'{"seq":7,"concept":"K1-1-u3-C9","difficulty":2,"kind":"mc","stem":"가족을 부르는 말 가운데 받침이 있는 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"엄마 · 동생 · 형","correct":true},{"t":"동생 · 누나 · 삼촌","mis":"K1-1-u3-X01"},{"t":"이모 · 형 · 엄마","mis":"K1-1-u3-X01"}],"explanation":["엄(ㅁ)·동생(ㅇ·ㅇ)·형(ㅇ)에 받침이 있어요.","「누나」·「이모」에는 받침이 없어요.","낱말마다 아래쪽을 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 가족을 부르는 말 가운데 받침이 있는 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"삼촌 · 동생 · 엄마","correct":true},{"t":"삼촌 · 고모 · 엄마","mis":"K1-1-u3-X01"},{"t":"누나 · 동생 · 형","mis":"K1-1-u3-X01"}],"explanation":["삼촌·동생·엄마 모두 받침이 있어요.","「고모」·「누나」에는 받침이 없어요.","낱말마다 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_basic#8','kor',1,1,'u3','L10','g1_1_kor_u3_L10_basic','lesson_basic','K1-1-u3-C9',2,'match','auto','낱자 하나만 바뀐 낱말끼리 이으세요.','{}'::text[],true,'{"seq":8,"concept":"K1-1-u3-C9","difficulty":2,"kind":"match","stem":"낱자 하나만 바뀐 낱말끼리 이으세요.","pairs":[{"l":"곰","r":"봄"},{"l":"말","r":"물"},{"l":"방","r":"빵"}],"mis":"K1-1-u3-X16","explanation":["곰 → 봄(첫 자음자), 말 → 물(모음자), 방 → 빵(첫 자음자 된소리).","짝마다 낱자 하나만 달라요.","바뀐 낱자에 동그라미를 쳐 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱자 하나만 바뀐 낱말끼리 이으세요.","pairs":[{"l":"곰","r":"공"},{"l":"달","r":"딸"},{"l":"강","r":"감"}],"explanation":["곰 → 공(받침), 달 → 딸(첫 자음자), 강 → 감(받침).","짝마다 낱자 하나만 달라요.","바뀐 낱자에 동그라미."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_basic#9','kor',1,1,'u3','L10','g1_1_kor_u3_L10_basic','lesson_basic','K1-1-u3-C9',2,'mc','auto','그림과 낱말을 바르게 이은 것은 어느 것인가요?',ARRAY['K1-1-u3-X16']::text[],true,'{"seq":9,"concept":"K1-1-u3-C9","difficulty":2,"kind":"mc","stem":"그림과 낱말을 바르게 이은 것은 어느 것인가요?","options":[{"t":"🐻 곰 · 🌸 봄","correct":true},{"t":"🐻 봄 · 🌸 곰","mis":"K1-1-u3-X16"},{"t":"🐻 곰 · 🌸 곰","mis":"K1-1-u3-X16"}],"explanation":["🐻는 「곰」, 🌸는 「봄」.","낱자 하나 차이로 뜻이 전혀 달라요.","소리 내어 읽고 그림과 견줘요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림과 낱말을 바르게 이은 것은 어느 것인가요?","options":[{"t":"🐴 말 · 💧 물","correct":true},{"t":"🐴 물 · 💧 말","mis":"K1-1-u3-X16"},{"t":"🐴 말 · 💧 말","mis":"K1-1-u3-X16"}],"explanation":["🐴는 「말」, 💧는 「물」.","모음자 하나 차이로 뜻이 달라요.","소리 내어 읽고 견줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_basic#10','kor',1,1,'u3','L10','g1_1_kor_u3_L10_basic','lesson_basic','K1-1-u3-C9',3,'mc','auto','「공책」에서 받침을 모두 찾은 것은 어느 것인가요?',ARRAY['K1-1-u3-X05','K1-1-u3-X06']::text[],true,'{"seq":10,"concept":"K1-1-u3-C9","difficulty":3,"kind":"mc","stem":"「공책」에서 받침을 모두 찾은 것은 어느 것인가요?","options":[{"t":"「공」의 ㅇ, 「책」의 ㄱ","correct":true},{"t":"「공」의 ㅇ만","mis":"K1-1-u3-X05"},{"t":"「공」의 ㄱ, 「책」의 ㅊ","mis":"K1-1-u3-X06"}],"explanation":["「공책」은 두 글자 모두 받침이 있어요.","받침은 한 낱말에 여러 개 있을 수 있고, ㄱ·ㅊ은 첫 자음자예요.","글자마다 맨 아래를 짚어요."],"variant_rule":{"alt":[{"stem":"「칠판」에서 받침을 모두 찾은 것은 어느 것인가요?","options":[{"t":"「칠」의 ㄹ, 「판」의 ㄴ","correct":true},{"t":"「칠」의 ㄹ만","mis":"K1-1-u3-X05"},{"t":"「칠」의 ㅊ, 「판」의 ㅍ","mis":"K1-1-u3-X06"}],"explanation":["「칠판」은 두 글자 모두 받침이 있어요.","ㅊ·ㅍ은 첫 자음자예요.","글자마다 맨 아래를 짚어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_challenge#1','kor',1,1,'u3','L10','g1_1_kor_u3_L10_challenge','lesson_challenge','K1-1-u3-C9',2,'mc','auto','「물」의 받침 ㄹ을 ㄴ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X06','K1-1-u3-X16']::text[],true,'{"seq":1,"kind":"mc","stem":"「물」의 받침 ㄹ을 ㄴ으로 바꾸면 어떤 글자가 되나요?","asset":{"type":"bat","s":"물","eq":false},"options":[{"t":"문","correct":true},{"t":"눌","mis":"K1-1-u3-X06"},{"t":"물","mis":"K1-1-u3-X16"}],"explanation":["「물」에서 받침 ㄹ 자리에 ㄴ을 넣으면 「문」이에요.","맨 앞 자음자 ㅁ과 모음자 ㅜ는 그대로예요.","받침이 바뀌면 글자도 소리도 뜻도 달라져요."],"concept":"K1-1-u3-C9","difficulty":2,"variant_rule":{"bat":{"ask":"swap","mis":{"role":"X06","keep":"X16"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_challenge#2','kor',1,1,'u3','L10','g1_1_kor_u3_L10_challenge','lesson_challenge','K1-1-u3-C9',2,'mc','auto','집 물건 가운데 받침이 하나도 없는 낱말은 어느 것인가요?',ARRAY['K1-1-u3-X01']::text[],true,'{"seq":2,"concept":"K1-1-u3-C9","difficulty":2,"kind":"mc","stem":"집 물건 가운데 받침이 하나도 없는 낱말은 어느 것인가요?","options":[{"t":"소파","correct":true},{"t":"칫솔","mis":"K1-1-u3-X01"},{"t":"양말","mis":"K1-1-u3-X01"}],"explanation":["「소파」의 소·파는 아래쪽이 비어 있어요.","「칫솔」·「양말」은 두 글자 모두 받침이 있어요.","집에서도 받침 낱말을 찾아봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 집 물건 가운데 받침이 하나도 없는 낱말은 어느 것인가요?","options":[{"t":"모자","correct":true},{"t":"침대","mis":"K1-1-u3-X01"},{"t":"숟가락","mis":"K1-1-u3-X01"}],"explanation":["「모자」의 모·자는 아래쪽이 비어 있어요.","「침대」의 침, 「숟가락」의 숟·락에는 받침이 있어요.","집에서도 받침 낱말을 찾아봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_challenge#3','kor',1,1,'u3','L10','g1_1_kor_u3_L10_challenge','lesson_challenge','K1-1-u3-C9',3,'mc','auto','된소리 ㅆ이 들어간 낱말은 어느 것인가요?',ARRAY['K1-1-u3-X12','K1-1-u3-X10']::text[],true,'{"seq":3,"kind":"mc","stem":"된소리 ㅆ이 들어간 낱말은 어느 것인가요?","options":[{"t":"씨앗","correct":true},{"t":"시소","mis":"K1-1-u3-X12"},{"t":"빵","mis":"K1-1-u3-X10"}],"explanation":["「씨앗」에는 ㅆ이 들어 있어요.","ㅅ이 든 낱말과 견주어 읽어 봐요.","소리 내어 읽고, 글자에서 같은 자음자를 두 번 쓴 곳을 찾아요."],"concept":"K1-1-u3-C9","difficulty":3,"variant_rule":{"twin":{"ask":"pick","mis":{"soft":"X12","asp":"X10","other":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_challenge#4','kor',1,1,'u3','L10','g1_1_kor_u3_L10_challenge','lesson_challenge','K1-1-u3-C9',3,'error','auto','태민이가 교실 물건 가운데 받침이 있는 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_challenge#5','kor',1,1,'u3','L10','g1_1_kor_u3_L10_challenge','lesson_challenge','K1-1-u3-C9',3,'mc','auto','「강」이 「공」으로 바뀌었어요. 바뀐 것은 무엇인가요?',ARRAY['K1-1-u3-X06']::text[],true,'{"seq":5,"concept":"K1-1-u3-C9","difficulty":3,"kind":"mc","stem":"「강」이 「공」으로 바뀌었어요. 바뀐 것은 무엇인가요?","options":[{"t":"모음자","correct":true},{"t":"첫 자음자","mis":"K1-1-u3-X06"},{"t":"받침","mis":"K1-1-u3-X06"}],"explanation":["강 → 공: 모음자 ㅏ가 ㅗ로 바뀌었어요.","첫 자음자 ㄱ과 받침 ㅇ은 그대로예요.","셋 가운데 무엇이 바뀌었는지 짚어요."],"variant_rule":{"alt":[{"stem":"「곰」이 「공」으로 바뀌었어요. 바뀐 것은 무엇인가요?","options":[{"t":"받침","correct":true},{"t":"첫 자음자","mis":"K1-1-u3-X06"},{"t":"모음자","mis":"K1-1-u3-X06"}],"explanation":["곰 → 공: 받침 ㅁ이 ㅇ으로 바뀌었어요.","첫 자음자 ㄱ과 모음자 ㅗ는 그대로예요.","셋 가운데 무엇이 바뀌었는지 짚어요."]},{"stem":"「곰」이 「봄」으로 바뀌었어요. 바뀐 것은 무엇인가요?","options":[{"t":"첫 자음자","correct":true},{"t":"모음자","mis":"K1-1-u3-X06"},{"t":"받침","mis":"K1-1-u3-X06"}],"explanation":["곰 → 봄: 첫 자음자 ㄱ이 ㅂ으로 바뀌었어요.","모음자 ㅗ와 받침 ㅁ은 그대로예요.","셋 가운데 무엇이 바뀌었는지 짚어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_challenge#6','kor',1,1,'u3','L10','g1_1_kor_u3_L10_challenge','lesson_challenge','K1-1-u3-C9',3,'mc','auto','「불」에서 낱자 하나만 바꾸어 만들 수 없는 낱말은 어느 것인가요?',ARRAY['K1-1-u3-X16']::text[],true,'{"seq":6,"concept":"K1-1-u3-C9","difficulty":3,"kind":"mc","stem":"「불」에서 낱자 하나만 바꾸어 만들 수 없는 낱말은 어느 것인가요?","options":[{"t":"곰","correct":true},{"t":"뿔","mis":"K1-1-u3-X16"},{"t":"풀","mis":"K1-1-u3-X16"}],"explanation":["「곰」은 첫 자음자·모음자·받침이 모두 달라요.","뿔(ㅂ → ㅃ)·풀(ㅂ → ㅍ)은 하나만 바뀌었어요.","바뀐 낱자를 하나씩 세어 봐요."],"variant_rule":{"alt":[{"stem":"「달」에서 낱자 하나만 바꾸어 만들 수 없는 낱말은 어느 것인가요?","options":[{"t":"봄","correct":true},{"t":"딸","mis":"K1-1-u3-X16"},{"t":"돌","mis":"K1-1-u3-X16"}],"explanation":["「봄」은 첫 자음자·모음자·받침이 모두 달라요.","딸(ㄷ → ㄸ)·돌(ㅏ → ㅗ)은 하나만 바뀌었어요.","바뀐 낱자를 세어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_challenge#7','kor',1,1,'u3','L10','g1_1_kor_u3_L10_challenge','lesson_challenge','K1-1-u3-C9',3,'mc','auto','과일 가운데 받침이나 된소리가 든 낱말만 모은 것은 어느 것인가요?',ARRAY['K1-1-u3-X01']::text[],true,'{"seq":7,"concept":"K1-1-u3-C9","difficulty":3,"kind":"mc","stem":"과일 가운데 받침이나 된소리가 든 낱말만 모은 것은 어느 것인가요?","options":[{"t":"딸기 · 수박 · 귤","correct":true},{"t":"딸기 · 수박 · 배","mis":"K1-1-u3-X01"},{"t":"사과 · 수박 · 귤","mis":"K1-1-u3-X01"}],"explanation":["딸기(ㄸ·ㄹ)·수박(ㄱ)·귤(ㄹ)이에요.","「배」·「사과」에는 받침도 된소리도 없어요.","낱말마다 살펴요."],"variant_rule":{"alt":[{"stem":"학용품 가운데 받침이나 된소리가 든 낱말만 모은 것은 어느 것인가요?","options":[{"t":"연필 · 딱풀 · 공책","correct":true},{"t":"연필 · 자 · 공책","mis":"K1-1-u3-X01"},{"t":"가위 · 딱풀 · 공책","mis":"K1-1-u3-X01"}],"explanation":["연필(ㄴ·ㄹ)·딱풀(ㄸ·ㄱ·ㄹ)·공책(ㅇ·ㄱ)이에요.","「자」·「가위」에는 받침도 된소리도 없어요.","낱말마다 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_challenge#8','kor',1,1,'u3','L10','g1_1_kor_u3_L10_challenge','lesson_challenge','K1-1-u3-C9',4,'mc','auto','「말 → 물 → 불 → 뿔」처럼 한 낱자씩 바꾸어 말 잇기를 했어요. 「물 → 불」에서 바뀐 것은 무엇인가요?',ARRAY['K1-1-u3-X06']::text[],true,'{"seq":8,"concept":"K1-1-u3-C9","difficulty":4,"kind":"mc","stem":"「말 → 물 → 불 → 뿔」처럼 한 낱자씩 바꾸어 말 잇기를 했어요. 「물 → 불」에서 바뀐 것은 무엇인가요?","options":[{"t":"첫 자음자 ㅁ → ㅂ","correct":true},{"t":"모음자 ㅜ → ㅗ","mis":"K1-1-u3-X06"},{"t":"받침 ㄹ → ㅂ","mis":"K1-1-u3-X06"}],"explanation":["물 → 불: 첫 자음자만 바뀌었어요.","모음자 ㅜ와 받침 ㄹ은 그대로예요.","말 → 물은 모음자, 불 → 뿔은 된소리로 바뀌었어요."],"variant_rule":{"alt":[{"stem":"「곰 → 공 → 강 → 방」처럼 한 낱자씩 바꾸어 말 잇기를 했어요. 「공 → 강」에서 바뀐 것은 무엇인가요?","options":[{"t":"모음자 ㅗ → ㅏ","correct":true},{"t":"첫 자음자 ㄱ → ㅂ","mis":"K1-1-u3-X06"},{"t":"받침 ㅇ → ㅁ","mis":"K1-1-u3-X06"}],"explanation":["공 → 강: 모음자만 바뀌었어요.","첫 자음자 ㄱ과 받침 ㅇ은 그대로예요.","곰 → 공은 받침, 강 → 방은 첫 자음자가 바뀌었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_challenge#9','kor',1,1,'u3','L10','g1_1_kor_u3_L10_challenge','lesson_challenge','K1-1-u3-C9',4,'mc','auto','「손」에서 낱자 하나를 바꾸어 만든 낱말과 바뀐 낱자를 바르게 짝 지은 것은 어느 것인가요?',ARRAY['K1-1-u3-X06']::text[],true,'{"seq":9,"concept":"K1-1-u3-C9","difficulty":4,"kind":"mc","stem":"「손」에서 낱자 하나를 바꾸어 만든 낱말과 바뀐 낱자를 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"산 — 모음자","correct":true},{"t":"선 — 첫 자음자","mis":"K1-1-u3-X06"},{"t":"솜 — 모음자","mis":"K1-1-u3-X06"}],"explanation":["손 → 산: 모음자 ㅗ가 ㅏ로 바뀌었어요.","「선」은 모음자가, 「솜」은 받침이 바뀌었어요.","무엇이 바뀌었는지 정확히 짚어요."],"variant_rule":{"alt":[{"stem":"「별」에서 낱자 하나를 바꾸어 만든 낱말과 바뀐 낱자를 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"벌 — 모음자","correct":true},{"t":"병 — 첫 자음자","mis":"K1-1-u3-X06"},{"t":"멸 — 받침","mis":"K1-1-u3-X06"}],"explanation":["별 → 벌: 모음자 ㅕ가 ㅓ로 바뀌었어요.","「병」은 받침이, 「멸」은 첫 자음자가 바뀌었어요.","무엇이 바뀌었는지 짚어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_L10_challenge#10','kor',1,1,'u3','L10','g1_1_kor_u3_L10_challenge','lesson_challenge','K1-1-u3-C9',4,'essay','teacher','우리 집에서 받침이나 된소리가 든 낱말 두 개를 찾아 쓰고, 각 낱말에서 받침이나 된소리 자음자를 짚어 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u3-C9","difficulty":4,"kind":"essay","stem":"우리 집에서 받침이나 된소리가 든 낱말 두 개를 찾아 쓰고, 각 낱말에서 받침이나 된소리 자음자를 짚어 말해 보세요.","answer_guide":{"answer":"예: 「칫솔」 — 칫의 ㅅ, 솔의 ㄹ이 받침이에요. 「빨래」 — 빨의 ㅃ이 된소리, ㄹ이 받침이에요.","scoring_points":["받침이나 된소리가 든 낱말을 두 개 바르게 썼는가","받침(또는 된소리)이 있는 글자를 바르게 짚었는가","받침과 된소리 자음자를 자리에 맞게 말했는가"]},"explanation":["낱말 두 개.","받침이나 된소리를 짚기.","자리(첫 자음자·받침)를 가려 말하기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#1','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C1',1,'ox','auto','「수바」처럼 받침을 빠뜨리면 「수박」의 뜻이 전해지지 않아요.',ARRAY['K1-1-u3-X01']::text[],false,'{"seq":1,"concept":"K1-1-u3-C1","difficulty":1,"kind":"ox","stem":"「수바」처럼 받침을 빠뜨리면 「수박」의 뜻이 전해지지 않아요.","answer":"O","reason_options":[{"t":"받침 ㄱ이 있어야 「수박」이 되니까","correct":true},{"t":"받침은 빠져도 뜻이 같으니까","mis":"K1-1-u3-X01"}],"mis":"K1-1-u3-X01","explanation":["「수바」는 무슨 말인지 알기 어려워요.","받침 ㄱ을 넣어야 「수박」이에요.","받침까지 빠뜨리지 않고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#2','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C2',1,'mc','auto','「다」에 받침 ㄹ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X01','K1-1-u3-X03']::text[],true,'{"seq":2,"kind":"mc","stem":"「다」에 받침 ㄹ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"다","b":"ㄹ","s":null,"lay":true},"options":[{"t":"달","correct":true},{"t":"다","mis":"K1-1-u3-X01"},{"t":"단","mis":"K1-1-u3-X03"}],"explanation":["「다」 아래쪽에 받침 ㄹ을 더하면 「달」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「달」은 받침 ㄹ 소리까지 끝까지 읽어요."],"concept":"K1-1-u3-C2","difficulty":1,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X01","near":"X03"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#3','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C3',1,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X06']::text[],true,'{"seq":3,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"곰","at":0,"pic":"🐻"},"options":[{"t":"ㅁ","correct":true},{"t":"ㅂ","mis":"K1-1-u3-X03"},{"t":"ㄱ","mis":"K1-1-u3-X06"}],"explanation":["그림은 「곰」이에요.","「고」에 받침 ㅁ을 넣어야 「곰」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u3-C3","difficulty":1,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X03","role":"X06"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#4','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C4',1,'mc','auto','그림을 보고 바르게 쓴 낱말을 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X01']::text[],false,'{"seq":4,"concept":"K1-1-u3-C4","difficulty":1,"kind":"mc","stem":"그림을 보고 바르게 쓴 낱말을 고르세요.","options":[{"t":"우산","correct":true},{"t":"우상","mis":"K1-1-u3-X03"},{"t":"우사","mis":"K1-1-u3-X01"}],"explanation":["그림은 「우산」 — 「산」의 받침은 ㄴ.","「우상」은 받침이 틀렸고, 「우사」는 받침이 빠졌어요.","뜻을 떠올리며 받침을 확인해요."],"asset":{"type":"scene","icon":"☂️"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#5','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C5',1,'mc','auto','글씨를 쓸 때 바른 자세는 어느 것인가요?',ARRAY['K1-1-u3-X08']::text[],false,'{"seq":5,"concept":"K1-1-u3-C5","difficulty":1,"kind":"mc","stem":"글씨를 쓸 때 바른 자세는 어느 것인가요?","options":[{"t":"허리를 펴고 바르게 앉아요","correct":true},{"t":"책상에 엎드려 써요","mis":"K1-1-u3-X08"},{"t":"다리를 꼬고 비스듬히 앉아요","mis":"K1-1-u3-X08"}],"explanation":["허리를 펴면 글씨가 반듯해져요.","엎드리거나 비스듬히 앉으면 글씨가 삐뚤어져요.","바른 자세가 바른 글씨의 시작."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#6','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C6',1,'mc','auto','ㄷ을 두 번 나란히 쓰면 어떤 자음자가 되나요?',ARRAY['K1-1-u3-X10','K1-1-u3-X09']::text[],true,'{"seq":6,"kind":"mc","stem":"ㄷ을 두 번 나란히 쓰면 어떤 자음자가 되나요?","options":[{"t":"ㄸ","correct":true},{"t":"ㅌ","mis":"K1-1-u3-X10"},{"t":"ㄷ","mis":"K1-1-u3-X09"}],"explanation":["ㄷ을 두 번 나란히 쓰면 ㄸ이에요.","ㅌ은 ㄷ에 획을 하나 더한 것이라 달라요.","ㄸ은 ㄷ보다 더 센 소리를 내요."],"concept":"K1-1-u3-C6","difficulty":1,"variant_rule":{"twin":{"ask":"shape","mis":{"asp":"X10","one":"X09","other":"X09"},"dir":"make"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#7','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C7',1,'mc','auto','그림을 보고 바르게 쓴 낱말을 고르세요.',ARRAY['K1-1-u3-X13','K1-1-u3-X10']::text[],true,'{"seq":7,"kind":"mc","stem":"그림을 보고 바르게 쓴 낱말을 고르세요.","asset":{"type":"scene","icon":"🍯"},"options":[{"t":"꿀","correct":true},{"t":"굴","mis":"K1-1-u3-X13"},{"t":"쿨","mis":"K1-1-u3-X10"}],"explanation":["그림은 「꿀」이에요.","ㄲ을 ㄱ 하나로 쓰면 다른 말이 돼요.","소리 내어 읽으며 센 소리가 나는 자음자를 확인해요."],"concept":"K1-1-u3-C7","difficulty":1,"variant_rule":{"twin":{"ask":"word","mis":{"plain":"X13","asp":"X10","other":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#8','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C8',1,'mc','auto','「깡충깡충」 움직이는 모습에 어울리는 동물은 어느 것인가요?',ARRAY['K1-1-u3-X14']::text[],false,'{"seq":8,"concept":"K1-1-u3-C8","difficulty":1,"kind":"mc","stem":"「깡충깡충」 움직이는 모습에 어울리는 동물은 어느 것인가요?","options":[{"t":"토끼","correct":true},{"t":"거북","mis":"K1-1-u3-X14"},{"t":"달팽이","mis":"K1-1-u3-X14"}],"explanation":["토끼는 깡충깡충 움직여요.","거북·달팽이는 다르게 움직여요.","흉내 내는 말을 몸으로 따라 해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#9','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C2',2,'mc','auto','「북」의 받침은 어느 것인가요?',ARRAY['K1-1-u3-X06','K1-1-u3-X03']::text[],true,'{"seq":9,"kind":"mc","stem":"「북」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"북","eq":false,"lay":"blank"},"options":[{"t":"ㄱ","correct":true},{"t":"ㅂ","mis":"K1-1-u3-X06"},{"t":"ㅇ","mis":"K1-1-u3-X03"}],"explanation":["「북」은 ㅂ + ㅜ + 받침 ㄱ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㅂ은 첫소리, 받침 ㄱ은 끝소리예요."],"concept":"K1-1-u3-C2","difficulty":2,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X06","near":"X03","vow":"X06"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#10','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C3',2,'mc','auto','「바라」에 받침 ㅁ을 넣어 「바람」을 만들려면 어느 글자 아래에 넣나요?',ARRAY['K1-1-u3-X04','K1-1-u3-X05']::text[],false,'{"seq":10,"concept":"K1-1-u3-C3","difficulty":2,"kind":"mc","stem":"「바라」에 받침 ㅁ을 넣어 「바람」을 만들려면 어느 글자 아래에 넣나요?","options":[{"t":"「라」","correct":true},{"t":"「바」","mis":"K1-1-u3-X04"},{"t":"두 글자 모두","mis":"K1-1-u3-X05"}],"explanation":["「라」 + 받침 ㅁ = 「람」.","다른 글자에 넣으면 다른 말이 돼요.","소리가 닫히는 글자를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#11','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C4',2,'error','auto','시우가 그림을 보고 「화부」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u3-X01','K1-1-u3-X04','K1-1-u3-X03']::text[],false,'{"seq":11,"concept":"K1-1-u3-C4","difficulty":2,"kind":"error","stem":"시우가 그림을 보고 「화부」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"「부」에 받침 ㄴ을 빠뜨렸어요 — 「화분」","correct":true,"mis_target":"K1-1-u3-X01"},{"t":"「화」에 받침 ㄴ을 넣어야 해요","mis":"K1-1-u3-X04"},{"t":"「부」에 받침 ㅇ을 넣어야 해요","mis":"K1-1-u3-X03"}],"explanation":["그림은 「화분」 — 「분」의 받침 ㄴ.","다른 글자에 넣거나 다른 받침을 넣으면 그림과 달라요.","뜻을 떠올리며 받침 자리를 찾아요."],"asset":{"type":"scene","icon":"🪴"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#12','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C6',2,'mc','auto','ㄲ은 어떤 자음자를 두 번 쓴 것인가요?',ARRAY['K1-1-u3-X10','K1-1-u3-X09']::text[],true,'{"seq":12,"kind":"mc","stem":"ㄲ은 어떤 자음자를 두 번 쓴 것인가요?","options":[{"t":"ㄱ","correct":true},{"t":"ㅋ","mis":"K1-1-u3-X10"},{"t":"ㅂ","mis":"K1-1-u3-X09"}],"explanation":["ㄲ은 ㄱ을 두 번 나란히 쓴 자음자예요.","ㅋ은 ㄱ에 획을 하나 더한 자음자라 달라요.","ㄲ은 ㄱ보다 더 센 소리를 내요."],"concept":"K1-1-u3-C6","difficulty":2,"variant_rule":{"twin":{"ask":"shape","mis":{"asp":"X10","other":"X09","one":"X09"},"dir":"split"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#13','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C7',2,'mc','auto','「굴」의 ㄱ을 ㄲ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X11','K1-1-u3-X10']::text[],true,'{"seq":13,"kind":"mc","stem":"「굴」의 ㄱ을 ㄲ으로 바꾸면 어떤 글자가 되나요?","options":[{"t":"꿀","correct":true},{"t":"굴","mis":"K1-1-u3-X11"},{"t":"쿨","mis":"K1-1-u3-X10"}],"explanation":["「굴」에서 ㄱ 자리에 ㄲ을 넣으면 「꿀」이에요.","모음자와 받침은 그대로예요.","ㄲ은 ㄱ보다 센 소리 — 자음자가 바뀌면 뜻도 달라져요."],"concept":"K1-1-u3-C7","difficulty":2,"variant_rule":{"twin":{"ask":"swap","mis":{"keep":"X11","asp":"X10","other":"X09"},"dir":"up"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#14','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C8',2,'mc','auto','「해가 ○○ 비쳐요」에 어울리는 흉내 내는 말은 어느 것인가요?',ARRAY['K1-1-u3-X14']::text[],false,'{"seq":14,"concept":"K1-1-u3-C8","difficulty":2,"kind":"mc","stem":"「해가 ○○ 비쳐요」에 어울리는 흉내 내는 말은 어느 것인가요?","options":[{"t":"쨍쨍","correct":true},{"t":"주룩주룩","mis":"K1-1-u3-X14"},{"t":"살랑살랑","mis":"K1-1-u3-X14"}],"explanation":["해가 쨍쨍 비쳐요 — 「쨍쨍」.","주룩주룩·살랑살랑은 다른 모습에 어울려요.","모습을 떠올리며 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#15','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C9',2,'mc','auto','「곰」이 「봄」으로 바뀌었어요. 바뀐 것은 무엇인가요?',ARRAY['K1-1-u3-X06']::text[],false,'{"seq":15,"concept":"K1-1-u3-C9","difficulty":2,"kind":"mc","stem":"「곰」이 「봄」으로 바뀌었어요. 바뀐 것은 무엇인가요?","options":[{"t":"첫 자음자","correct":true},{"t":"모음자","mis":"K1-1-u3-X06"},{"t":"받침","mis":"K1-1-u3-X06"}],"explanation":["곰 → 봄: 첫 자음자가 바뀌었어요.","나머지 두 낱자는 그대로예요.","위아래로 놓고 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#16','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C1',2,'mc','auto','받침이 있는 글자만 모은 것은 어느 것인가요?',ARRAY['K1-1-u3-X01']::text[],false,'{"seq":16,"concept":"K1-1-u3-C1","difficulty":2,"kind":"mc","stem":"받침이 있는 글자만 모은 것은 어느 것인가요?","options":[{"t":"별 · 문 · 발","correct":true},{"t":"별 · 나 · 발","mis":"K1-1-u3-X01"},{"t":"코 · 문 · 소","mis":"K1-1-u3-X01"}],"explanation":["별·문·발은 모두 아래쪽에 받침이 있어요.","다른 보기에는 아래쪽이 비어 있는 글자가 섞였어요.","글자마다 아래쪽을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#17','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C3',3,'sa','auto','그림을 보고 받침이 빠진 글자를 고쳐 낱말을 바르게 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"K1-1-u3-C3","difficulty":3,"kind":"sa","stem":"그림을 보고 받침이 빠진 글자를 고쳐 낱말을 바르게 쓰세요.","answer":["다람쥐"],"explanation":["「라」 아래에 받침 ㅁ을 넣으면 「다람쥐」.","다른 글자에는 받침이 없어요.","고친 뒤 소리 내어 읽어 확인해요."],"asset":{"type":"scene","icon":"🐿️","text":"다라쥐"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#18','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C4',3,'error','auto','하린이가 쓴 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#19','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C7',3,'ox','auto','「가시」는 세게 「까시」라고 읽어야 해요.',ARRAY['K1-1-u3-X12']::text[],false,'{"seq":19,"concept":"K1-1-u3-C7","difficulty":3,"kind":"ox","stem":"「가시」는 세게 「까시」라고 읽어야 해요.","answer":"X","reason_options":[{"t":"「가시」에는 같은 자음자를 두 번 쓴 곳이 없어 여린 소리로 읽으니까","correct":true},{"t":"모든 낱말은 힘주어 세게 읽어야 하니까","mis":"K1-1-u3-X12"}],"mis":"K1-1-u3-X12","explanation":["「가시」에는 된소리 자음자가 없어요.","세게 읽으면 다른 말처럼 들려요.","된소리 자음자가 있을 때만 세게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#20','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C9',3,'error','auto','준우가 교실 물건 가운데 받침이 있는 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#21','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C5',3,'mc','auto','바르게 쓰기 위한 준비로 알맞지 않은 것은 어느 것인가요?',ARRAY['K1-1-u3-X08']::text[],false,'{"seq":21,"concept":"K1-1-u3-C5","difficulty":3,"kind":"mc","stem":"바르게 쓰기 위한 준비로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"공책을 무릎 위에 올려놓고 써요","correct":true},{"t":"허리를 펴고 앉아요","mis":"K1-1-u3-X08"},{"t":"공책을 살짝 기울여 놓아요","mis":"K1-1-u3-X08"}],"explanation":["「공책을 무릎 위에 올려놓고 써요」는 바른 쓰기와 거리가 멀어요.","나머지 둘은 알맞은 준비예요.","바른 자세가 바른 글씨의 시작이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#22','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C6',3,'mc','auto','세 낱말에 모두 들어 있는 된소리 자음자는 어느 것인가요?',ARRAY['K1-1-u3-X15','K1-1-u3-X10']::text[],false,'{"seq":22,"concept":"K1-1-u3-C6","difficulty":3,"kind":"mc","stem":"세 낱말에 모두 들어 있는 된소리 자음자는 어느 것인가요?","options":[{"t":"ㅉ","correct":true},{"t":"ㅃ","mis":"K1-1-u3-X15"},{"t":"ㅊ","mis":"K1-1-u3-X10"}],"explanation":["찐빵 · 짜장면 · 팔찌 — 세 낱말 모두 ㅉ이 있어요.","다른 자음자는 세 낱말 모두에 있지 않아요.","낱말마다 글자를 하나하나 짚어요."],"asset":{"type":"passage","lines":["찐빵 · 짜장면 · 팔찌"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#23','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C8',4,'mc','auto','다음 문장에서 된소리 자음자가 든 낱말은 모두 몇 개인가요?',ARRAY['K1-1-u3-X15']::text[],false,'{"seq":23,"concept":"K1-1-u3-C8","difficulty":4,"kind":"mc","stem":"다음 문장에서 된소리 자음자가 든 낱말은 모두 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"3개","mis":"K1-1-u3-X15"},{"t":"5개","mis":"K1-1-u3-X15"}],"explanation":["토끼가 · 깡충깡충 · 뛰어 · 딸기밭으로 — 4개예요.","다른 낱말에는 된소리 자음자가 없어요.","낱말마다 글자를 하나하나 짚어요."],"asset":{"type":"passage","lines":["토끼가 깡충깡충 뛰어 딸기밭으로 가요."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#24','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C2',4,'mc','auto','「감」을 만든 조각 「ㄱ · ㅏ · ㅁ」을 그대로 쓰되 자리만 바꾸어 만들 수 있는 글자는 어느 것인가요?',ARRAY['K1-1-u3-X02','K1-1-u3-X06']::text[],false,'{"seq":24,"concept":"K1-1-u3-C2","difficulty":4,"kind":"mc","stem":"「감」을 만든 조각 「ㄱ · ㅏ · ㅁ」을 그대로 쓰되 자리만 바꾸어 만들 수 있는 글자는 어느 것인가요?","options":[{"t":"막","correct":true},{"t":"마ㄱ","mis":"K1-1-u3-X02"},{"t":"각","mis":"K1-1-u3-X06"}],"explanation":["첫 자음자와 받침 자리를 바꾸면 「막」.","받침을 옆에 쓰거나 조각 하나를 빠뜨리면 안 돼요.","같은 조각도 자리가 바뀌면 다른 글자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_a#25','kor',1,1,'u3','','g1_1_kor_u3_review_a','unit_review','K1-1-u3-C4',4,'mc','auto','다음 문장에서 잘못 쓴 낱말 두 개를 바르게 고친 것은 어느 것인가요?',ARRAY['K1-1-u3-X05']::text[],false,'{"seq":25,"concept":"K1-1-u3-C4","difficulty":4,"kind":"mc","stem":"다음 문장에서 잘못 쓴 낱말 두 개를 바르게 고친 것은 어느 것인가요?","options":[{"t":"장화, 우산","correct":true},{"t":"장화, 우상","mis":"K1-1-u3-X05"},{"t":"잠화, 우산","mis":"K1-1-u3-X05"}],"explanation":["「잠화」 → 「장화」, 「우상」 → 「우산」.","하나만 고치면 아직 틀린 낱말이 남아요.","문장 끝까지 낱말마다 받침을 살펴요."],"asset":{"type":"passage","lines":["잠화를 신고 우상을 썼어요."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#1','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C1',1,'ox','auto','「고」처럼 받침을 빠뜨리면 「곰」의 뜻이 전해지지 않아요.',ARRAY['K1-1-u3-X01']::text[],false,'{"seq":1,"concept":"K1-1-u3-C1","difficulty":1,"kind":"ox","stem":"「고」처럼 받침을 빠뜨리면 「곰」의 뜻이 전해지지 않아요.","answer":"O","reason_options":[{"t":"받침 ㅁ이 있어야 「곰」이 되니까","correct":true},{"t":"받침은 빠져도 뜻이 같으니까","mis":"K1-1-u3-X01"}],"mis":"K1-1-u3-X01","explanation":["「고」는 무슨 말인지 알기 어려워요.","받침 ㅁ을 넣어야 「곰」이에요.","받침까지 빠뜨리지 않고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#2','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C2',1,'mc','auto','「부」에 받침 ㄱ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X01','K1-1-u3-X03']::text[],true,'{"seq":2,"kind":"mc","stem":"「부」에 받침 ㄱ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"부","b":"ㄱ","s":null,"lay":true},"options":[{"t":"북","correct":true},{"t":"부","mis":"K1-1-u3-X01"},{"t":"붕","mis":"K1-1-u3-X03"}],"explanation":["「부」 아래쪽에 받침 ㄱ을 더하면 「북」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「북」은 받침 ㄱ 소리까지 끝까지 읽어요."],"concept":"K1-1-u3-C2","difficulty":1,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X01","near":"X03"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#3','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C3',1,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X06']::text[],true,'{"seq":3,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"집","at":0,"pic":"🏠"},"options":[{"t":"ㅂ","correct":true},{"t":"ㅁ","mis":"K1-1-u3-X03"},{"t":"ㅈ","mis":"K1-1-u3-X06"}],"explanation":["그림은 「집」이에요.","「지」에 받침 ㅂ을 넣어야 「집」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u3-C3","difficulty":1,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X03","role":"X06"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#4','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C4',1,'mc','auto','그림을 보고 바르게 쓴 낱말을 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X01']::text[],false,'{"seq":4,"concept":"K1-1-u3-C4","difficulty":1,"kind":"mc","stem":"그림을 보고 바르게 쓴 낱말을 고르세요.","options":[{"t":"장화","correct":true},{"t":"잠화","mis":"K1-1-u3-X03"},{"t":"자화","mis":"K1-1-u3-X01"}],"explanation":["그림은 「장화」 — 「장」의 받침은 ㅇ.","「잠화」는 받침이 틀렸고, 「자화」는 받침이 빠졌어요.","뜻을 떠올리며 받침을 확인해요."],"asset":{"type":"scene","icon":"👢"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#5','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C5',1,'mc','auto','연필은 어떻게 잡나요?',ARRAY['K1-1-u3-X08']::text[],false,'{"seq":5,"concept":"K1-1-u3-C5","difficulty":1,"kind":"mc","stem":"연필은 어떻게 잡나요?","options":[{"t":"세 손가락으로 가볍게 잡아요","correct":true},{"t":"주먹으로 꽉 움켜쥐어요","mis":"K1-1-u3-X08"},{"t":"끝을 아주 짧게 잡아요","mis":"K1-1-u3-X08"}],"explanation":["엄지·검지로 잡고 가운데손가락으로 받쳐요.","움켜쥐거나 짧게 잡으면 손이 아파요.","바르게 잡아야 또박또박 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#6','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C6',1,'mc','auto','ㅂ을 두 번 나란히 쓰면 어떤 자음자가 되나요?',ARRAY['K1-1-u3-X10','K1-1-u3-X09']::text[],true,'{"seq":6,"kind":"mc","stem":"ㅂ을 두 번 나란히 쓰면 어떤 자음자가 되나요?","options":[{"t":"ㅃ","correct":true},{"t":"ㅍ","mis":"K1-1-u3-X10"},{"t":"ㅂ","mis":"K1-1-u3-X09"}],"explanation":["ㅂ을 두 번 나란히 쓰면 ㅃ이에요.","ㅍ은 ㅂ에 획을 하나 더한 것이라 달라요.","ㅃ은 ㅂ보다 더 센 소리를 내요."],"concept":"K1-1-u3-C6","difficulty":1,"variant_rule":{"twin":{"ask":"shape","mis":{"asp":"X10","one":"X09","other":"X09"},"dir":"make"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#7','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C7',1,'mc','auto','그림을 보고 바르게 쓴 낱말을 고르세요.',ARRAY['K1-1-u3-X13','K1-1-u3-X10']::text[],true,'{"seq":7,"kind":"mc","stem":"그림을 보고 바르게 쓴 낱말을 고르세요.","asset":{"type":"scene","icon":"🍡"},"options":[{"t":"떡","correct":true},{"t":"덕","mis":"K1-1-u3-X13"},{"t":"턱","mis":"K1-1-u3-X10"}],"explanation":["그림은 「떡」이에요.","ㄸ을 ㄷ 하나로 쓰면 다른 말이 돼요.","소리 내어 읽으며 센 소리가 나는 자음자를 확인해요."],"concept":"K1-1-u3-C7","difficulty":1,"variant_rule":{"twin":{"ask":"word","mis":{"plain":"X13","asp":"X10","other":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#8','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C8',1,'mc','auto','「어슬렁어슬렁」 움직이는 모습에 어울리는 동물은 어느 것인가요?',ARRAY['K1-1-u3-X14']::text[],false,'{"seq":8,"concept":"K1-1-u3-C8","difficulty":1,"kind":"mc","stem":"「어슬렁어슬렁」 움직이는 모습에 어울리는 동물은 어느 것인가요?","options":[{"t":"호랑이","correct":true},{"t":"참새","mis":"K1-1-u3-X14"},{"t":"토끼","mis":"K1-1-u3-X14"}],"explanation":["호랑이는 어슬렁어슬렁 움직여요.","참새·토끼는 다르게 움직여요.","흉내 내는 말을 몸으로 따라 해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#9','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C2',2,'mc','auto','「양」의 받침은 어느 것인가요?',ARRAY['K1-1-u3-X03','K1-1-u3-X06']::text[],true,'{"seq":9,"kind":"mc","stem":"「양」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"양","eq":false,"lay":"blank"},"options":[{"t":"ㅇ","correct":true},{"t":"ㄴ","mis":"K1-1-u3-X03"},{"t":"ㅑ","mis":"K1-1-u3-X06"}],"explanation":["「양」은 ㅇ + ㅑ + 받침 ㅇ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㅇ은 첫소리, 받침 ㅇ은 끝소리예요."],"concept":"K1-1-u3-C2","difficulty":2,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X06","near":"X03","vow":"X06"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#10','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C3',2,'mc','auto','「구르」에 받침 ㅁ을 넣어 「구름」을 만들려면 어느 글자 아래에 넣나요?',ARRAY['K1-1-u3-X04','K1-1-u3-X05']::text[],false,'{"seq":10,"concept":"K1-1-u3-C3","difficulty":2,"kind":"mc","stem":"「구르」에 받침 ㅁ을 넣어 「구름」을 만들려면 어느 글자 아래에 넣나요?","options":[{"t":"「르」","correct":true},{"t":"「구」","mis":"K1-1-u3-X04"},{"t":"두 글자 모두","mis":"K1-1-u3-X05"}],"explanation":["「르」 + 받침 ㅁ = 「름」.","다른 글자에 넣으면 다른 말이 돼요.","소리가 닫히는 글자를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#11','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C4',2,'error','auto','민호가 그림을 보고 「거우」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u3-X01','K1-1-u3-X04','K1-1-u3-X03']::text[],false,'{"seq":11,"concept":"K1-1-u3-C4","difficulty":2,"kind":"error","stem":"민호가 그림을 보고 「거우」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"「우」에 받침 ㄹ을 빠뜨렸어요 — 「거울」","correct":true,"mis_target":"K1-1-u3-X01"},{"t":"「거」에 받침 ㄹ을 넣어야 해요","mis":"K1-1-u3-X04"},{"t":"「우」에 받침 ㄴ을 넣어야 해요","mis":"K1-1-u3-X03"}],"explanation":["그림은 「거울」 — 「울」의 받침 ㄹ.","다른 글자에 넣거나 다른 받침을 넣으면 그림과 달라요.","뜻을 떠올리며 받침 자리를 찾아요."],"asset":{"type":"scene","icon":"🪞"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#12','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C6',2,'mc','auto','ㄸ은 어떤 자음자를 두 번 쓴 것인가요?',ARRAY['K1-1-u3-X10','K1-1-u3-X09']::text[],true,'{"seq":12,"kind":"mc","stem":"ㄸ은 어떤 자음자를 두 번 쓴 것인가요?","options":[{"t":"ㄷ","correct":true},{"t":"ㅌ","mis":"K1-1-u3-X10"},{"t":"ㅈ","mis":"K1-1-u3-X09"}],"explanation":["ㄸ은 ㄷ을 두 번 나란히 쓴 자음자예요.","ㅌ은 ㄷ에 획을 하나 더한 자음자라 달라요.","ㄸ은 ㄷ보다 더 센 소리를 내요."],"concept":"K1-1-u3-C6","difficulty":2,"variant_rule":{"twin":{"ask":"shape","mis":{"asp":"X10","other":"X09","one":"X09"},"dir":"split"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#13','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C7',2,'mc','auto','「달」의 ㄷ을 ㄸ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X11','K1-1-u3-X10']::text[],true,'{"seq":13,"kind":"mc","stem":"「달」의 ㄷ을 ㄸ으로 바꾸면 어떤 글자가 되나요?","options":[{"t":"딸","correct":true},{"t":"달","mis":"K1-1-u3-X11"},{"t":"탈","mis":"K1-1-u3-X10"}],"explanation":["「달」에서 ㄷ 자리에 ㄸ을 넣으면 「딸」이에요.","모음자와 받침은 그대로예요.","ㄸ은 ㄷ보다 센 소리 — 자음자가 바뀌면 뜻도 달라져요."],"concept":"K1-1-u3-C7","difficulty":2,"variant_rule":{"twin":{"ask":"swap","mis":{"keep":"X11","asp":"X10","other":"X09"},"dir":"up"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#14','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C8',2,'mc','auto','「비가 ○○ 내려요」에 어울리는 흉내 내는 말은 어느 것인가요?',ARRAY['K1-1-u3-X14']::text[],false,'{"seq":14,"concept":"K1-1-u3-C8","difficulty":2,"kind":"mc","stem":"「비가 ○○ 내려요」에 어울리는 흉내 내는 말은 어느 것인가요?","options":[{"t":"주룩주룩","correct":true},{"t":"쨍쨍","mis":"K1-1-u3-X14"},{"t":"반짝반짝","mis":"K1-1-u3-X14"}],"explanation":["비가 주룩주룩 내려요 — 「주룩주룩」.","쨍쨍·반짝반짝은 다른 모습에 어울려요.","모습을 떠올리며 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#15','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C9',2,'mc','auto','「말」이 「물」로 바뀌었어요. 바뀐 것은 무엇인가요?',ARRAY['K1-1-u3-X06']::text[],false,'{"seq":15,"concept":"K1-1-u3-C9","difficulty":2,"kind":"mc","stem":"「말」이 「물」로 바뀌었어요. 바뀐 것은 무엇인가요?","options":[{"t":"모음자","correct":true},{"t":"첫 자음자","mis":"K1-1-u3-X06"},{"t":"받침","mis":"K1-1-u3-X06"}],"explanation":["말 → 물: 모음자가 바뀌었어요.","나머지 두 낱자는 그대로예요.","위아래로 놓고 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#16','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C1',2,'mc','auto','받침이 있는 글자만 모은 것은 어느 것인가요?',ARRAY['K1-1-u3-X01']::text[],false,'{"seq":16,"concept":"K1-1-u3-C1","difficulty":2,"kind":"mc","stem":"받침이 있는 글자만 모은 것은 어느 것인가요?","options":[{"t":"숲 · 강 · 집","correct":true},{"t":"숲 · 배 · 집","mis":"K1-1-u3-X01"},{"t":"오 · 강 · 이","mis":"K1-1-u3-X01"}],"explanation":["숲·강·집은 모두 아래쪽에 받침이 있어요.","다른 보기에는 아래쪽이 비어 있는 글자가 섞였어요.","글자마다 아래쪽을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#17','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C3',3,'sa','auto','그림을 보고 받침이 빠진 글자를 고쳐 낱말을 바르게 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"K1-1-u3-C3","difficulty":3,"kind":"sa","stem":"그림을 보고 받침이 빠진 글자를 고쳐 낱말을 바르게 쓰세요.","answer":["수박"],"explanation":["「바」 아래에 받침 ㄱ을 넣으면 「수박」.","다른 글자에는 받침이 없어요.","고친 뒤 소리 내어 읽어 확인해요."],"asset":{"type":"scene","icon":"🍉","text":"수바"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#18','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C4',3,'error','auto','태민이가 쓴 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#19','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C7',3,'ox','auto','「다리」는 세게 「따리」라고 읽어야 해요.',ARRAY['K1-1-u3-X12']::text[],false,'{"seq":19,"concept":"K1-1-u3-C7","difficulty":3,"kind":"ox","stem":"「다리」는 세게 「따리」라고 읽어야 해요.","answer":"X","reason_options":[{"t":"「다리」에는 같은 자음자를 두 번 쓴 곳이 없어 여린 소리로 읽으니까","correct":true},{"t":"모든 낱말은 힘주어 세게 읽어야 하니까","mis":"K1-1-u3-X12"}],"mis":"K1-1-u3-X12","explanation":["「다리」에는 된소리 자음자가 없어요.","세게 읽으면 다른 말처럼 들려요.","된소리 자음자가 있을 때만 세게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#20','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C9',3,'error','auto','서윤이가 가족 가운데 받침이 있는 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#21','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C5',3,'mc','auto','바르게 쓰기 위한 준비로 알맞지 않은 것은 어느 것인가요?',ARRAY['K1-1-u3-X08']::text[],false,'{"seq":21,"concept":"K1-1-u3-C5","difficulty":3,"kind":"mc","stem":"바르게 쓰기 위한 준비로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"빨리 끝내려고 글자를 몰아서 써요","correct":true},{"t":"연필을 가볍게 바르게 잡아요","mis":"K1-1-u3-X08"},{"t":"한 글자씩 짜임을 생각하며 써요","mis":"K1-1-u3-X08"}],"explanation":["「빨리 끝내려고 글자를 몰아서 써요」는 바른 쓰기와 거리가 멀어요.","나머지 둘은 알맞은 준비예요.","바른 자세가 바른 글씨의 시작이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#22','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C6',3,'mc','auto','세 낱말에 모두 들어 있는 된소리 자음자는 어느 것인가요?',ARRAY['K1-1-u3-X15','K1-1-u3-X10']::text[],false,'{"seq":22,"concept":"K1-1-u3-C6","difficulty":3,"kind":"mc","stem":"세 낱말에 모두 들어 있는 된소리 자음자는 어느 것인가요?","options":[{"t":"ㄸ","correct":true},{"t":"ㄲ","mis":"K1-1-u3-X15"},{"t":"ㅌ","mis":"K1-1-u3-X10"}],"explanation":["딸기 · 땅콩 · 떡 — 세 낱말 모두 ㄸ이 있어요.","다른 자음자는 세 낱말 모두에 있지 않아요.","낱말마다 글자를 하나하나 짚어요."],"asset":{"type":"passage","lines":["딸기 · 땅콩 · 떡"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#23','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C8',4,'mc','auto','다음 문장에서 된소리 자음자가 든 낱말은 모두 몇 개인가요?',ARRAY['K1-1-u3-X15']::text[],false,'{"seq":23,"concept":"K1-1-u3-C8","difficulty":4,"kind":"mc","stem":"다음 문장에서 된소리 자음자가 든 낱말은 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"K1-1-u3-X15"},{"t":"4개","mis":"K1-1-u3-X15"}],"explanation":["까치가 · 빵과 · 떡을 — 3개예요.","다른 낱말에는 된소리 자음자가 없어요.","낱말마다 글자를 하나하나 짚어요."],"asset":{"type":"passage","lines":["아침에 까치가 빵과 떡을 먹어요."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#24','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C2',4,'mc','auto','「곰」을 만든 조각 「ㄱ · ㅗ · ㅁ」을 그대로 쓰되 자리만 바꾸어 만들 수 있는 글자는 어느 것인가요?',ARRAY['K1-1-u3-X02','K1-1-u3-X06']::text[],false,'{"seq":24,"concept":"K1-1-u3-C2","difficulty":4,"kind":"mc","stem":"「곰」을 만든 조각 「ㄱ · ㅗ · ㅁ」을 그대로 쓰되 자리만 바꾸어 만들 수 있는 글자는 어느 것인가요?","options":[{"t":"목","correct":true},{"t":"모ㄱ","mis":"K1-1-u3-X02"},{"t":"곡","mis":"K1-1-u3-X06"}],"explanation":["첫 자음자와 받침 자리를 바꾸면 「목」.","받침을 옆에 쓰거나 조각 하나를 빠뜨리면 안 돼요.","같은 조각도 자리가 바뀌면 다른 글자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_b#25','kor',1,1,'u3','','g1_1_kor_u3_review_b','unit_review','K1-1-u3-C4',4,'mc','auto','다음 문장에서 잘못 쓴 낱말 두 개를 바르게 고친 것은 어느 것인가요?',ARRAY['K1-1-u3-X05']::text[],false,'{"seq":25,"concept":"K1-1-u3-C4","difficulty":4,"kind":"mc","stem":"다음 문장에서 잘못 쓴 낱말 두 개를 바르게 고친 것은 어느 것인가요?","options":[{"t":"물통, 거울","correct":true},{"t":"물통, 거우","mis":"K1-1-u3-X05"},{"t":"무통, 거울","mis":"K1-1-u3-X05"}],"explanation":["「무통」 → 「물통」, 「거우」 → 「거울」.","하나만 고치면 아직 틀린 낱말이 남아요.","문장 끝까지 낱말마다 받침을 살펴요."],"asset":{"type":"passage","lines":["무통을 들고 거우 앞에 섰어요."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#1','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C1',1,'ox','auto','「가바」처럼 받침을 빠뜨리면 「가방」의 뜻이 전해지지 않아요.',ARRAY['K1-1-u3-X01']::text[],false,'{"seq":1,"concept":"K1-1-u3-C1","difficulty":1,"kind":"ox","stem":"「가바」처럼 받침을 빠뜨리면 「가방」의 뜻이 전해지지 않아요.","answer":"O","reason_options":[{"t":"받침 ㅇ이 있어야 「가방」이 되니까","correct":true},{"t":"받침은 빠져도 뜻이 같으니까","mis":"K1-1-u3-X01"}],"mis":"K1-1-u3-X01","explanation":["「가바」는 무슨 말인지 알기 어려워요.","받침 ㅇ을 넣어야 「가방」이에요.","받침까지 빠뜨리지 않고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#2','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C2',1,'mc','auto','「야」에 받침 ㅇ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X01','K1-1-u3-X03']::text[],true,'{"seq":2,"kind":"mc","stem":"「야」에 받침 ㅇ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"야","b":"ㅇ","s":null,"lay":true},"options":[{"t":"양","correct":true},{"t":"야","mis":"K1-1-u3-X01"},{"t":"얀","mis":"K1-1-u3-X03"}],"explanation":["「야」 아래쪽에 받침 ㅇ을 더하면 「양」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「양」은 받침 ㅇ 소리까지 끝까지 읽어요."],"concept":"K1-1-u3-C2","difficulty":1,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X01","near":"X03"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#3','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C3',1,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X06']::text[],true,'{"seq":3,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"별","at":0,"pic":"⭐"},"options":[{"t":"ㄹ","correct":true},{"t":"ㄴ","mis":"K1-1-u3-X03"},{"t":"ㅂ","mis":"K1-1-u3-X06"}],"explanation":["그림은 「별」이에요.","「벼」에 받침 ㄹ을 넣어야 「별」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u3-C3","difficulty":1,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X03","role":"X06"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#4','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C4',1,'mc','auto','그림을 보고 바르게 쓴 낱말을 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X01']::text[],false,'{"seq":4,"concept":"K1-1-u3-C4","difficulty":1,"kind":"mc","stem":"그림을 보고 바르게 쓴 낱말을 고르세요.","options":[{"t":"거울","correct":true},{"t":"거운","mis":"K1-1-u3-X03"},{"t":"거우","mis":"K1-1-u3-X01"}],"explanation":["그림은 「거울」 — 「울」의 받침은 ㄹ.","「거운」은 받침이 틀렸고, 「거우」는 받침이 빠졌어요.","뜻을 떠올리며 받침을 확인해요."],"asset":{"type":"scene","icon":"🪞"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#5','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C5',1,'mc','auto','글씨를 쓸 때 공책은 어떻게 놓나요?',ARRAY['K1-1-u3-X08']::text[],false,'{"seq":5,"concept":"K1-1-u3-C5","difficulty":1,"kind":"mc","stem":"글씨를 쓸 때 공책은 어떻게 놓나요?","options":[{"t":"몸 앞에 살짝 기울여 놓아요","correct":true},{"t":"책상 끝에 반쯤 걸쳐 놓아요","mis":"K1-1-u3-X08"},{"t":"무릎 위에 올려놓아요","mis":"K1-1-u3-X08"}],"explanation":["살짝 기울이면 글씨가 잘 써져요.","걸치거나 무릎에 올리면 흔들려요.","공책 자리도 자세예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#6','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C6',1,'mc','auto','ㅅ을 두 번 나란히 쓰면 어떤 자음자가 되나요?',ARRAY['K1-1-u3-X09']::text[],true,'{"seq":6,"kind":"mc","stem":"ㅅ을 두 번 나란히 쓰면 어떤 자음자가 되나요?","options":[{"t":"ㅆ","correct":true},{"t":"ㅅ","mis":"K1-1-u3-X09"},{"t":"ㄸ","mis":"K1-1-u3-X09"}],"explanation":["ㅅ을 두 번 나란히 쓰면 ㅆ이에요.","한 번만 쓰면 그대로 ㅅ이에요.","ㅆ은 ㅅ보다 더 센 소리를 내요."],"concept":"K1-1-u3-C6","difficulty":1,"variant_rule":{"twin":{"ask":"shape","mis":{"asp":"X10","one":"X09","other":"X09"},"dir":"make"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#7','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C7',1,'mc','auto','그림을 보고 바르게 쓴 낱말을 고르세요.',ARRAY['K1-1-u3-X13','K1-1-u3-X10']::text[],true,'{"seq":7,"kind":"mc","stem":"그림을 보고 바르게 쓴 낱말을 고르세요.","asset":{"type":"scene","icon":"🍞"},"options":[{"t":"빵","correct":true},{"t":"방","mis":"K1-1-u3-X13"},{"t":"팡","mis":"K1-1-u3-X10"}],"explanation":["그림은 「빵」이에요.","ㅃ을 ㅂ 하나로 쓰면 다른 말이 돼요.","소리 내어 읽으며 센 소리가 나는 자음자를 확인해요."],"concept":"K1-1-u3-C7","difficulty":1,"variant_rule":{"twin":{"ask":"word","mis":{"plain":"X13","asp":"X10","other":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#8','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C8',1,'mc','auto','「뒤뚱뒤뚱」 움직이는 모습에 어울리는 동물은 어느 것인가요?',ARRAY['K1-1-u3-X14']::text[],false,'{"seq":8,"concept":"K1-1-u3-C8","difficulty":1,"kind":"mc","stem":"「뒤뚱뒤뚱」 움직이는 모습에 어울리는 동물은 어느 것인가요?","options":[{"t":"오리","correct":true},{"t":"호랑이","mis":"K1-1-u3-X14"},{"t":"토끼","mis":"K1-1-u3-X14"}],"explanation":["오리는 뒤뚱뒤뚱 움직여요.","호랑이·토끼는 다르게 움직여요.","흉내 내는 말을 몸으로 따라 해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#9','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C2',2,'mc','auto','「달」의 받침은 어느 것인가요?',ARRAY['K1-1-u3-X06','K1-1-u3-X03']::text[],true,'{"seq":9,"kind":"mc","stem":"「달」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"달","eq":false,"lay":"blank"},"options":[{"t":"ㄹ","correct":true},{"t":"ㄷ","mis":"K1-1-u3-X06"},{"t":"ㄴ","mis":"K1-1-u3-X03"}],"explanation":["「달」은 ㄷ + ㅏ + 받침 ㄹ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㄷ은 첫소리, 받침 ㄹ은 끝소리예요."],"concept":"K1-1-u3-C2","difficulty":2,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X06","near":"X03","vow":"X06"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#10','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C3',2,'mc','auto','「고무주」에 받침 ㄹ을 넣어 「고무줄」을 만들려면 어느 글자 아래에 넣나요?',ARRAY['K1-1-u3-X04']::text[],false,'{"seq":10,"concept":"K1-1-u3-C3","difficulty":2,"kind":"mc","stem":"「고무주」에 받침 ㄹ을 넣어 「고무줄」을 만들려면 어느 글자 아래에 넣나요?","options":[{"t":"「주」","correct":true},{"t":"「무」","mis":"K1-1-u3-X04"},{"t":"「고」","mis":"K1-1-u3-X04"}],"explanation":["「주」 + 받침 ㄹ = 「줄」.","다른 글자에 넣으면 다른 말이 돼요.","소리가 닫히는 글자를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#11','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C4',2,'error','auto','은솔이가 그림을 보고 「기리」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u3-X01','K1-1-u3-X04','K1-1-u3-X03']::text[],false,'{"seq":11,"concept":"K1-1-u3-C4","difficulty":2,"kind":"error","stem":"은솔이가 그림을 보고 「기리」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"「리」에 받침 ㄴ을 빠뜨렸어요 — 「기린」","correct":true,"mis_target":"K1-1-u3-X01"},{"t":"「기」에 받침 ㄴ을 넣어야 해요","mis":"K1-1-u3-X04"},{"t":"「리」에 받침 ㅇ을 넣어야 해요","mis":"K1-1-u3-X03"}],"explanation":["그림은 「기린」 — 「린」의 받침 ㄴ.","다른 글자에 넣거나 다른 받침을 넣으면 그림과 달라요.","뜻을 떠올리며 받침 자리를 찾아요."],"asset":{"type":"scene","icon":"🦒"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#12','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C6',2,'mc','auto','ㅃ은 어떤 자음자를 두 번 쓴 것인가요?',ARRAY['K1-1-u3-X10','K1-1-u3-X09']::text[],true,'{"seq":12,"kind":"mc","stem":"ㅃ은 어떤 자음자를 두 번 쓴 것인가요?","options":[{"t":"ㅂ","correct":true},{"t":"ㅍ","mis":"K1-1-u3-X10"},{"t":"ㄱ","mis":"K1-1-u3-X09"}],"explanation":["ㅃ은 ㅂ을 두 번 나란히 쓴 자음자예요.","ㅍ은 ㅂ에 획을 하나 더한 자음자라 달라요.","ㅃ은 ㅂ보다 더 센 소리를 내요."],"concept":"K1-1-u3-C6","difficulty":2,"variant_rule":{"twin":{"ask":"shape","mis":{"asp":"X10","other":"X09","one":"X09"},"dir":"split"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#13','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C7',2,'mc','auto','「불」의 ㅂ을 ㅃ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X11','K1-1-u3-X10']::text[],true,'{"seq":13,"kind":"mc","stem":"「불」의 ㅂ을 ㅃ으로 바꾸면 어떤 글자가 되나요?","options":[{"t":"뿔","correct":true},{"t":"불","mis":"K1-1-u3-X11"},{"t":"풀","mis":"K1-1-u3-X10"}],"explanation":["「불」에서 ㅂ 자리에 ㅃ을 넣으면 「뿔」이에요.","모음자와 받침은 그대로예요.","ㅃ은 ㅂ보다 센 소리 — 자음자가 바뀌면 뜻도 달라져요."],"concept":"K1-1-u3-C7","difficulty":2,"variant_rule":{"twin":{"ask":"swap","mis":{"keep":"X11","asp":"X10","other":"X09"},"dir":"up"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#14','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C8',2,'mc','auto','「바람이 ○○ 불어요」에 어울리는 흉내 내는 말은 어느 것인가요?',ARRAY['K1-1-u3-X14']::text[],false,'{"seq":14,"concept":"K1-1-u3-C8","difficulty":2,"kind":"mc","stem":"「바람이 ○○ 불어요」에 어울리는 흉내 내는 말은 어느 것인가요?","options":[{"t":"살랑살랑","correct":true},{"t":"쨍쨍","mis":"K1-1-u3-X14"},{"t":"엉금엉금","mis":"K1-1-u3-X14"}],"explanation":["바람이 살랑살랑 불어요 — 「살랑살랑」.","쨍쨍·엉금엉금은 다른 모습에 어울려요.","모습을 떠올리며 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#15','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C9',2,'mc','auto','「곰」이 「공」으로 바뀌었어요. 바뀐 것은 무엇인가요?',ARRAY['K1-1-u3-X06']::text[],false,'{"seq":15,"concept":"K1-1-u3-C9","difficulty":2,"kind":"mc","stem":"「곰」이 「공」으로 바뀌었어요. 바뀐 것은 무엇인가요?","options":[{"t":"받침","correct":true},{"t":"첫 자음자","mis":"K1-1-u3-X06"},{"t":"모음자","mis":"K1-1-u3-X06"}],"explanation":["곰 → 공: 받침이 바뀌었어요.","나머지 두 낱자는 그대로예요.","위아래로 놓고 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#16','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C1',2,'mc','auto','받침이 있는 글자만 모은 것은 어느 것인가요?',ARRAY['K1-1-u3-X01']::text[],false,'{"seq":16,"concept":"K1-1-u3-C1","difficulty":2,"kind":"mc","stem":"받침이 있는 글자만 모은 것은 어느 것인가요?","options":[{"t":"곰 · 산 · 달","correct":true},{"t":"곰 · 사 · 달","mis":"K1-1-u3-X01"},{"t":"고 · 산 · 다","mis":"K1-1-u3-X01"}],"explanation":["곰·산·달은 모두 아래쪽에 받침이 있어요.","다른 보기에는 아래쪽이 비어 있는 글자가 섞였어요.","글자마다 아래쪽을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#17','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C3',3,'sa','auto','그림을 보고 받침이 빠진 글자를 고쳐 낱말을 바르게 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"K1-1-u3-C3","difficulty":3,"kind":"sa","stem":"그림을 보고 받침이 빠진 글자를 고쳐 낱말을 바르게 쓰세요.","answer":["돌다리"],"explanation":["「도」 아래에 받침 ㄹ을 넣으면 「돌다리」.","다른 글자에는 받침이 없어요.","고친 뒤 소리 내어 읽어 확인해요."],"asset":{"type":"scene","icon":"🌉","text":"도다리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#18','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C4',3,'error','auto','지안이가 쓴 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#19','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C7',3,'ox','auto','「바다」는 세게 「빠다」라고 읽어야 해요.',ARRAY['K1-1-u3-X12']::text[],false,'{"seq":19,"concept":"K1-1-u3-C7","difficulty":3,"kind":"ox","stem":"「바다」는 세게 「빠다」라고 읽어야 해요.","answer":"X","reason_options":[{"t":"「바다」에는 같은 자음자를 두 번 쓴 곳이 없어 여린 소리로 읽으니까","correct":true},{"t":"모든 낱말은 힘주어 세게 읽어야 하니까","mis":"K1-1-u3-X12"}],"mis":"K1-1-u3-X12","explanation":["「바다」에는 된소리 자음자가 없어요.","세게 읽으면 다른 말처럼 들려요.","된소리 자음자가 있을 때만 세게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#20','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C9',3,'error','auto','시우가 과일 가운데 받침이 있는 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#21','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C5',3,'mc','auto','바르게 쓰기 위한 준비로 알맞지 않은 것은 어느 것인가요?',ARRAY['K1-1-u3-X08']::text[],false,'{"seq":21,"concept":"K1-1-u3-C5","difficulty":3,"kind":"mc","stem":"바르게 쓰기 위한 준비로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"연필을 주먹으로 꽉 움켜쥐어요","correct":true},{"t":"허리를 펴고 앉아요","mis":"K1-1-u3-X08"},{"t":"공책을 몸 앞에 놓아요","mis":"K1-1-u3-X08"}],"explanation":["「연필을 주먹으로 꽉 움켜쥐어요」는 바른 쓰기와 거리가 멀어요.","나머지 둘은 알맞은 준비예요.","바른 자세가 바른 글씨의 시작이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#22','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C6',3,'mc','auto','세 낱말에 모두 들어 있는 된소리 자음자는 어느 것인가요?',ARRAY['K1-1-u3-X15','K1-1-u3-X10']::text[],false,'{"seq":22,"concept":"K1-1-u3-C6","difficulty":3,"kind":"mc","stem":"세 낱말에 모두 들어 있는 된소리 자음자는 어느 것인가요?","options":[{"t":"ㄲ","correct":true},{"t":"ㅃ","mis":"K1-1-u3-X15"},{"t":"ㅋ","mis":"K1-1-u3-X10"}],"explanation":["까치 · 코끼리 · 토끼 — 세 낱말 모두 ㄲ이 있어요.","다른 자음자는 세 낱말 모두에 있지 않아요.","낱말마다 글자를 하나하나 짚어요."],"asset":{"type":"passage","lines":["까치 · 코끼리 · 토끼"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#23','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C8',4,'mc','auto','다음 문장에서 된소리 자음자가 든 낱말은 모두 몇 개인가요?',ARRAY['K1-1-u3-X15']::text[],false,'{"seq":23,"concept":"K1-1-u3-C8","difficulty":4,"kind":"mc","stem":"다음 문장에서 된소리 자음자가 든 낱말은 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"K1-1-u3-X15"},{"t":"4개","mis":"K1-1-u3-X15"}],"explanation":["코끼리가 · 땅콩을 · 뒤뚱뒤뚱 — 3개예요.","다른 낱말에는 된소리 자음자가 없어요.","낱말마다 글자를 하나하나 짚어요."],"asset":{"type":"passage","lines":["코끼리가 땅콩을 먹고 뒤뚱뒤뚱 걸어요."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#24','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C2',4,'mc','auto','「남」을 만든 조각 「ㄴ · ㅏ · ㅁ」을 그대로 쓰되 자리만 바꾸어 만들 수 있는 글자는 어느 것인가요?',ARRAY['K1-1-u3-X02','K1-1-u3-X06']::text[],false,'{"seq":24,"concept":"K1-1-u3-C2","difficulty":4,"kind":"mc","stem":"「남」을 만든 조각 「ㄴ · ㅏ · ㅁ」을 그대로 쓰되 자리만 바꾸어 만들 수 있는 글자는 어느 것인가요?","options":[{"t":"만","correct":true},{"t":"마ㄴ","mis":"K1-1-u3-X02"},{"t":"난","mis":"K1-1-u3-X06"}],"explanation":["첫 자음자와 받침 자리를 바꾸면 「만」.","받침을 옆에 쓰거나 조각 하나를 빠뜨리면 안 돼요.","같은 조각도 자리가 바뀌면 다른 글자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_c#25','kor',1,1,'u3','','g1_1_kor_u3_review_c','unit_review','K1-1-u3-C4',4,'mc','auto','다음 문장에서 잘못 쓴 낱말 두 개를 바르게 고친 것은 어느 것인가요?',ARRAY['K1-1-u3-X05']::text[],false,'{"seq":25,"concept":"K1-1-u3-C4","difficulty":4,"kind":"mc","stem":"다음 문장에서 잘못 쓴 낱말 두 개를 바르게 고친 것은 어느 것인가요?","options":[{"t":"출발, 운동장","correct":true},{"t":"출발, 운도장","mis":"K1-1-u3-X05"},{"t":"추발, 운동장","mis":"K1-1-u3-X05"}],"explanation":["「추발」 → 「출발」, 「운도장」 → 「운동장」.","하나만 고치면 아직 틀린 낱말이 남아요.","문장 끝까지 낱말마다 받침을 살펴요."],"asset":{"type":"passage","lines":["추발 신호에 맞춰 운도장을 달렸어요."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#1','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C1',1,'ox','auto','「기리」처럼 받침을 빠뜨리면 「기린」의 뜻이 전해지지 않아요.',ARRAY['K1-1-u3-X01']::text[],false,'{"seq":1,"concept":"K1-1-u3-C1","difficulty":1,"kind":"ox","stem":"「기리」처럼 받침을 빠뜨리면 「기린」의 뜻이 전해지지 않아요.","answer":"O","reason_options":[{"t":"받침 ㄴ이 있어야 「기린」이 되니까","correct":true},{"t":"받침은 빠져도 뜻이 같으니까","mis":"K1-1-u3-X01"}],"mis":"K1-1-u3-X01","explanation":["「기리」는 무슨 말인지 알기 어려워요.","받침 ㄴ을 넣어야 「기린」이에요.","받침까지 빠뜨리지 않고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#2','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C2',1,'mc','auto','「고」에 받침 ㅁ을 더하면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X01','K1-1-u3-X03']::text[],true,'{"seq":2,"kind":"mc","stem":"「고」에 받침 ㅁ을 더하면 어떤 글자가 되나요?","asset":{"type":"bat","base":"고","b":"ㅁ","s":null,"lay":true},"options":[{"t":"곰","correct":true},{"t":"고","mis":"K1-1-u3-X01"},{"t":"곱","mis":"K1-1-u3-X03"}],"explanation":["「고」 아래쪽에 받침 ㅁ을 더하면 「곰」이에요.","받침은 글자 아래쪽에 들어가요 — 옆에 따로 쓰지 않아요.","「곰」은 받침 ㅁ 소리까지 끝까지 읽어요."],"concept":"K1-1-u3-C2","difficulty":1,"variant_rule":{"bat":{"ask":"add","mis":{"drop":"X01","near":"X03"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#3','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C3',1,'mc','auto','그림을 보고 받침 칸에 들어갈 자음자를 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X06']::text[],true,'{"seq":3,"kind":"mc","stem":"그림을 보고 받침 칸에 들어갈 자음자를 고르세요.","asset":{"type":"bat_word","w":"손","at":0,"pic":"✋"},"options":[{"t":"ㄴ","correct":true},{"t":"ㅇ","mis":"K1-1-u3-X03"},{"t":"ㅅ","mis":"K1-1-u3-X06"}],"explanation":["그림은 「손」이에요.","「소」에 받침 ㄴ을 넣어야 「손」이 돼요.","그림이 뜻하는 낱말이 되는 받침을 골라요."],"concept":"K1-1-u3-C3","difficulty":1,"variant_rule":{"bat":{"ask":"word","mis":{"near":"X03","role":"X06"},"bats":["ㄱ","ㄴ","ㄹ","ㅁ","ㅂ","ㅇ"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#4','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C4',1,'mc','auto','그림을 보고 바르게 쓴 낱말을 고르세요.',ARRAY['K1-1-u3-X03','K1-1-u3-X01']::text[],false,'{"seq":4,"concept":"K1-1-u3-C4","difficulty":1,"kind":"mc","stem":"그림을 보고 바르게 쓴 낱말을 고르세요.","options":[{"t":"화분","correct":true},{"t":"화붕","mis":"K1-1-u3-X03"},{"t":"화부","mis":"K1-1-u3-X01"}],"explanation":["그림은 「화분」 — 「분」의 받침은 ㄴ.","「화붕」은 받침이 틀렸고, 「화부」는 받침이 빠졌어요.","뜻을 떠올리며 받침을 확인해요."],"asset":{"type":"scene","icon":"🪴"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#5','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C5',1,'mc','auto','받침이 있는 글자는 어떻게 쓰면 좋을까요?',ARRAY['K1-1-u3-X08']::text[],false,'{"seq":5,"concept":"K1-1-u3-C5","difficulty":1,"kind":"mc","stem":"받침이 있는 글자는 어떻게 쓰면 좋을까요?","options":[{"t":"한 글자씩 짜임을 생각하며 또박또박 써요","correct":true},{"t":"빨리 몰아서 한꺼번에 써요","mis":"K1-1-u3-X08"},{"t":"받침은 나중에 한꺼번에 써요","mis":"K1-1-u3-X08"}],"explanation":["짜임을 생각하면 받침 자리가 바르게 잡혀요.","몰아 쓰면 받침을 빠뜨리기 쉬워요.","천천히 또박또박이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#6','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C6',1,'mc','auto','ㅈ을 두 번 나란히 쓰면 어떤 자음자가 되나요?',ARRAY['K1-1-u3-X10','K1-1-u3-X09']::text[],true,'{"seq":6,"kind":"mc","stem":"ㅈ을 두 번 나란히 쓰면 어떤 자음자가 되나요?","options":[{"t":"ㅉ","correct":true},{"t":"ㅊ","mis":"K1-1-u3-X10"},{"t":"ㅈ","mis":"K1-1-u3-X09"}],"explanation":["ㅈ을 두 번 나란히 쓰면 ㅉ이에요.","ㅊ은 ㅈ에 획을 하나 더한 것이라 달라요.","ㅉ은 ㅈ보다 더 센 소리를 내요."],"concept":"K1-1-u3-C6","difficulty":1,"variant_rule":{"twin":{"ask":"shape","mis":{"asp":"X10","one":"X09","other":"X09"},"dir":"make"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#7','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C7',1,'mc','auto','그림을 보고 바르게 쓴 낱말을 고르세요.',ARRAY['K1-1-u3-X13','K1-1-u3-X10']::text[],true,'{"seq":7,"kind":"mc","stem":"그림을 보고 바르게 쓴 낱말을 고르세요.","asset":{"type":"scene","icon":"🐰"},"options":[{"t":"토끼","correct":true},{"t":"토기","mis":"K1-1-u3-X13"},{"t":"토키","mis":"K1-1-u3-X10"}],"explanation":["그림은 「토끼」예요.","ㄲ을 ㄱ 하나로 쓰면 다른 말이 돼요.","소리 내어 읽으며 센 소리가 나는 자음자를 확인해요."],"concept":"K1-1-u3-C7","difficulty":1,"variant_rule":{"twin":{"ask":"word","mis":{"plain":"X13","asp":"X10","other":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#8','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C8',1,'mc','auto','「엉금엉금」 움직이는 모습에 어울리는 동물은 어느 것인가요?',ARRAY['K1-1-u3-X14']::text[],false,'{"seq":8,"concept":"K1-1-u3-C8","difficulty":1,"kind":"mc","stem":"「엉금엉금」 움직이는 모습에 어울리는 동물은 어느 것인가요?","options":[{"t":"거북","correct":true},{"t":"토끼","mis":"K1-1-u3-X14"},{"t":"말","mis":"K1-1-u3-X14"}],"explanation":["거북은 엉금엉금 움직여요.","토끼·말은 다르게 움직여요.","흉내 내는 말을 몸으로 따라 해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#9','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C2',2,'mc','auto','「곰」의 받침은 어느 것인가요?',ARRAY['K1-1-u3-X06','K1-1-u3-X03']::text[],true,'{"seq":9,"kind":"mc","stem":"「곰」의 받침은 어느 것인가요?","asset":{"type":"bat","s":"곰","eq":false,"lay":"blank"},"options":[{"t":"ㅁ","correct":true},{"t":"ㄱ","mis":"K1-1-u3-X06"},{"t":"ㅂ","mis":"K1-1-u3-X03"}],"explanation":["「곰」은 ㄱ + ㅗ + 받침 ㅁ이에요.","받침은 글자 아래쪽에 있는 자음자예요.","맨 앞 자음자 ㄱ은 첫소리, 받침 ㅁ은 끝소리예요."],"concept":"K1-1-u3-C2","difficulty":2,"variant_rule":{"bat":{"ask":"find","mis":{"role":"X06","near":"X03","vow":"X06"},"lay":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#10','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C3',2,'mc','auto','「창무」에 받침 ㄴ을 넣어 「창문」을 만들려면 어느 글자 아래에 넣나요?',ARRAY['K1-1-u3-X04','K1-1-u3-X05']::text[],false,'{"seq":10,"concept":"K1-1-u3-C3","difficulty":2,"kind":"mc","stem":"「창무」에 받침 ㄴ을 넣어 「창문」을 만들려면 어느 글자 아래에 넣나요?","options":[{"t":"「무」","correct":true},{"t":"「창」","mis":"K1-1-u3-X04"},{"t":"두 글자 모두","mis":"K1-1-u3-X05"}],"explanation":["「무」 + 받침 ㄴ = 「문」.","다른 글자에 넣으면 다른 말이 돼요.","소리가 닫히는 글자를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#11','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C4',2,'error','auto','준우가 그림을 보고 「구르」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u3-X01','K1-1-u3-X04','K1-1-u3-X03']::text[],false,'{"seq":11,"concept":"K1-1-u3-C4","difficulty":2,"kind":"error","stem":"준우가 그림을 보고 「구르」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"「르」에 받침 ㅁ을 빠뜨렸어요 — 「구름」","correct":true,"mis_target":"K1-1-u3-X01"},{"t":"「구」에 받침 ㅁ을 넣어야 해요","mis":"K1-1-u3-X04"},{"t":"「르」에 받침 ㅇ을 넣어야 해요","mis":"K1-1-u3-X03"}],"explanation":["그림은 「구름」 — 「름」의 받침 ㅁ.","다른 글자에 넣거나 다른 받침을 넣으면 그림과 달라요.","뜻을 떠올리며 받침 자리를 찾아요."],"asset":{"type":"scene","icon":"☁️"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#12','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C6',2,'mc','auto','ㅉ은 어떤 자음자를 두 번 쓴 것인가요?',ARRAY['K1-1-u3-X10','K1-1-u3-X09']::text[],true,'{"seq":12,"kind":"mc","stem":"ㅉ은 어떤 자음자를 두 번 쓴 것인가요?","options":[{"t":"ㅈ","correct":true},{"t":"ㅊ","mis":"K1-1-u3-X10"},{"t":"ㄷ","mis":"K1-1-u3-X09"}],"explanation":["ㅉ은 ㅈ을 두 번 나란히 쓴 자음자예요.","ㅊ은 ㅈ에 획을 하나 더한 자음자라 달라요.","ㅉ은 ㅈ보다 더 센 소리를 내요."],"concept":"K1-1-u3-C6","difficulty":2,"variant_rule":{"twin":{"ask":"shape","mis":{"asp":"X10","other":"X09","one":"X09"},"dir":"split"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#13','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C7',2,'mc','auto','「개」의 ㄱ을 ㄲ으로 바꾸면 어떤 글자가 되나요?',ARRAY['K1-1-u3-X11','K1-1-u3-X10']::text[],true,'{"seq":13,"kind":"mc","stem":"「개」의 ㄱ을 ㄲ으로 바꾸면 어떤 글자가 되나요?","options":[{"t":"깨","correct":true},{"t":"개","mis":"K1-1-u3-X11"},{"t":"캐","mis":"K1-1-u3-X10"}],"explanation":["「개」에서 ㄱ 자리에 ㄲ을 넣으면 「깨」예요.","모음자는 그대로예요.","ㄲ은 ㄱ보다 센 소리 — 자음자가 바뀌면 뜻도 달라져요."],"concept":"K1-1-u3-C7","difficulty":2,"variant_rule":{"twin":{"ask":"swap","mis":{"keep":"X11","asp":"X10","other":"X09"},"dir":"up"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#14','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C8',2,'mc','auto','「별이 ○○ 빛나요」에 어울리는 흉내 내는 말은 어느 것인가요?',ARRAY['K1-1-u3-X14']::text[],false,'{"seq":14,"concept":"K1-1-u3-C8","difficulty":2,"kind":"mc","stem":"「별이 ○○ 빛나요」에 어울리는 흉내 내는 말은 어느 것인가요?","options":[{"t":"반짝반짝","correct":true},{"t":"주룩주룩","mis":"K1-1-u3-X14"},{"t":"뒤뚱뒤뚱","mis":"K1-1-u3-X14"}],"explanation":["별이 반짝반짝 빛나요 — 「반짝반짝」.","주룩주룩·뒤뚱뒤뚱은 다른 모습에 어울려요.","모습을 떠올리며 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#15','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C9',2,'mc','auto','「강」이 「공」으로 바뀌었어요. 바뀐 것은 무엇인가요?',ARRAY['K1-1-u3-X06']::text[],false,'{"seq":15,"concept":"K1-1-u3-C9","difficulty":2,"kind":"mc","stem":"「강」이 「공」으로 바뀌었어요. 바뀐 것은 무엇인가요?","options":[{"t":"모음자","correct":true},{"t":"첫 자음자","mis":"K1-1-u3-X06"},{"t":"받침","mis":"K1-1-u3-X06"}],"explanation":["강 → 공: 모음자가 바뀌었어요.","나머지 두 낱자는 그대로예요.","위아래로 놓고 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#16','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C1',2,'mc','auto','받침이 있는 글자만 모은 것은 어느 것인가요?',ARRAY['K1-1-u3-X01']::text[],false,'{"seq":16,"concept":"K1-1-u3-C1","difficulty":2,"kind":"mc","stem":"받침이 있는 글자만 모은 것은 어느 것인가요?","options":[{"t":"책 · 손 · 빵","correct":true},{"t":"채 · 손 · 빵","mis":"K1-1-u3-X01"},{"t":"책 · 소 · 바","mis":"K1-1-u3-X01"}],"explanation":["책·손·빵은 모두 아래쪽에 받침이 있어요.","다른 보기에는 아래쪽이 비어 있는 글자가 섞였어요.","글자마다 아래쪽을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#17','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C3',3,'sa','auto','그림을 보고 받침이 빠진 글자를 고쳐 낱말을 바르게 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"K1-1-u3-C3","difficulty":3,"kind":"sa","stem":"그림을 보고 받침이 빠진 글자를 고쳐 낱말을 바르게 쓰세요.","answer":["기린"],"explanation":["「리」 아래에 받침 ㄴ을 넣으면 「기린」.","다른 글자에는 받침이 없어요.","고친 뒤 소리 내어 읽어 확인해요."],"asset":{"type":"scene","icon":"🦒","text":"기리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#18','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C4',3,'error','auto','로아가 쓴 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#19','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C7',3,'ox','auto','「자두」는 세게 「짜두」라고 읽어야 해요.',ARRAY['K1-1-u3-X12']::text[],false,'{"seq":19,"concept":"K1-1-u3-C7","difficulty":3,"kind":"ox","stem":"「자두」는 세게 「짜두」라고 읽어야 해요.","answer":"X","reason_options":[{"t":"「자두」에는 같은 자음자를 두 번 쓴 곳이 없어 여린 소리로 읽으니까","correct":true},{"t":"모든 낱말은 힘주어 세게 읽어야 하니까","mis":"K1-1-u3-X12"}],"mis":"K1-1-u3-X12","explanation":["「자두」에는 된소리 자음자가 없어요.","세게 읽으면 다른 말처럼 들려요.","된소리 자음자가 있을 때만 세게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#20','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C9',3,'error','auto','하린이가 집 물건 가운데 받침이 있는 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#21','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C5',3,'mc','auto','바르게 쓰기 위한 준비로 알맞지 않은 것은 어느 것인가요?',ARRAY['K1-1-u3-X08']::text[],false,'{"seq":21,"concept":"K1-1-u3-C5","difficulty":3,"kind":"mc","stem":"바르게 쓰기 위한 준비로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"엎드려서 얼굴을 공책에 바짝 대요","correct":true},{"t":"허리를 펴고 앉아요","mis":"K1-1-u3-X08"},{"t":"연필을 가볍게 바르게 잡아요","mis":"K1-1-u3-X08"}],"explanation":["「엎드려서 얼굴을 공책에 바짝 대요」는 바른 쓰기와 거리가 멀어요.","나머지 둘은 알맞은 준비예요.","바른 자세가 바른 글씨의 시작이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#22','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C6',3,'mc','auto','세 낱말에 모두 들어 있는 된소리 자음자는 어느 것인가요?',ARRAY['K1-1-u3-X15','K1-1-u3-X10']::text[],false,'{"seq":22,"concept":"K1-1-u3-C6","difficulty":3,"kind":"mc","stem":"세 낱말에 모두 들어 있는 된소리 자음자는 어느 것인가요?","options":[{"t":"ㅃ","correct":true},{"t":"ㄲ","mis":"K1-1-u3-X15"},{"t":"ㅍ","mis":"K1-1-u3-X10"}],"explanation":["빵 · 코뿔소 · 아빠 — 세 낱말 모두 ㅃ이 있어요.","다른 자음자는 세 낱말 모두에 있지 않아요.","낱말마다 글자를 하나하나 짚어요."],"asset":{"type":"passage","lines":["빵 · 코뿔소 · 아빠"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#23','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C8',4,'mc','auto','다음 문장에서 된소리 자음자가 든 낱말은 모두 몇 개인가요?',ARRAY['K1-1-u3-X15']::text[],false,'{"seq":23,"concept":"K1-1-u3-C8","difficulty":4,"kind":"mc","stem":"다음 문장에서 된소리 자음자가 든 낱말은 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"K1-1-u3-X15"},{"t":"4개","mis":"K1-1-u3-X15"}],"explanation":["아빠가 · 팔찌와 · 빵을 — 3개예요.","다른 낱말에는 된소리 자음자가 없어요.","낱말마다 글자를 하나하나 짚어요."],"asset":{"type":"passage","lines":["아빠가 시장에서 팔찌와 빵을 사요."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#24','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C2',4,'mc','auto','「산」을 만든 조각 「ㅅ · ㅏ · ㄴ」을 그대로 쓰되 자리만 바꾸어 만들 수 있는 글자는 어느 것인가요?',ARRAY['K1-1-u3-X02','K1-1-u3-X06']::text[],false,'{"seq":24,"concept":"K1-1-u3-C2","difficulty":4,"kind":"mc","stem":"「산」을 만든 조각 「ㅅ · ㅏ · ㄴ」을 그대로 쓰되 자리만 바꾸어 만들 수 있는 글자는 어느 것인가요?","options":[{"t":"낫","correct":true},{"t":"나ㅅ","mis":"K1-1-u3-X02"},{"t":"삿","mis":"K1-1-u3-X06"}],"explanation":["첫 자음자와 받침 자리를 바꾸면 「낫」.","받침을 옆에 쓰거나 조각 하나를 빠뜨리면 안 돼요.","같은 조각도 자리가 바뀌면 다른 글자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u3_review_d#25','kor',1,1,'u3','','g1_1_kor_u3_review_d','unit_review','K1-1-u3-C4',4,'mc','auto','다음 문장에서 잘못 쓴 낱말 두 개를 바르게 고친 것은 어느 것인가요?',ARRAY['K1-1-u3-X05']::text[],false,'{"seq":25,"concept":"K1-1-u3-C4","difficulty":4,"kind":"mc","stem":"다음 문장에서 잘못 쓴 낱말 두 개를 바르게 고친 것은 어느 것인가요?","options":[{"t":"공책, 연필","correct":true},{"t":"공책, 연피","mis":"K1-1-u3-X05"},{"t":"공채, 연필","mis":"K1-1-u3-X05"}],"explanation":["「공채」 → 「공책」, 「연피」 → 「연필」.","하나만 고치면 아직 틀린 낱말이 남아요.","문장 끝까지 낱말마다 받침을 살펴요."],"asset":{"type":"passage","lines":["공채에 연피로 썼어요."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
